function getAIJsonResponseSchema(stage) {
    if (getAIProvider() === 'DEEPSEEK') return null;
    const strings = { type: 'ARRAY', items: { type: 'STRING' } };
    if (stage === 'ANALYST') {
        return {
            type: 'OBJECT',
            properties: {
                market_view: {
                    type: 'OBJECT',
                    properties: {
                        bias: { type: 'STRING', enum: ['BULLISH', 'BEARISH', 'MIXED', 'NEUTRAL'] },
                        market_phase: { type: 'STRING', enum: ['ORIGINAL_SETUP', 'EARLY_DELIVERY', 'EXPANSION', 'RETRACEMENT', 'CONTINUATION_READY', 'LATE_DELIVERY', 'TRANSITION_WAIT'] },
                        directional_thesis: { type: 'STRING', enum: ['BUY', 'SELL'] },
                        thesis_status: { type: 'STRING', enum: ['INTACT', 'WEAKENING', 'INVALIDATED', 'UNCLEAR'] },
                        original_thesis_status: { type: 'STRING' },
                        preferred_opportunity_role: { type: 'STRING', enum: ['ORIGINAL_THESIS_POI', 'FRESH_RETRACEMENT_POI', 'FRESH_CONTINUATION_POI', 'CONFIRMATION_POI'] },
                        phase_evidence_ids: strings,
                        conflicting_evidence_ids: strings,
                        confidence: { type: 'NUMBER' },
                        market_narrative: { type: 'STRING' },
                        important_liquidity: { type: 'STRING' },
                        structure_interpretation: { type: 'STRING' },
                        risk_notes: strings
                    },
                    required: ['bias', 'market_phase', 'thesis_status', 'phase_evidence_ids', 'conflicting_evidence_ids']
                },
                hypotheses: {
                    type: 'ARRAY',
                    items: {
                        type: 'OBJECT',
                        properties: {
                            hypothesis_id: { type: 'STRING' },
                            strategy: { type: 'STRING' },
                            direction: { type: 'STRING', enum: ['BUY', 'SELL'] },
                            setup_mode: { type: 'STRING', enum: ['LIMIT', 'CONFIRMATION_ENTRY'] },
                            setup_timeframe: { type: 'STRING', enum: ['4H', '1H', '15M'] },
                            execution_timeframe: { type: 'STRING', enum: ['4H', '1H', '15M', '5M'] },
                            preferred_location_zone_ids: strings,
                            preferred_execution_zone_ids: strings,
                            supporting_evidence: strings,
                            conflicting_evidence: strings,
                            target_candidate_ids: strings,
                            reasoning: { type: 'STRING' }
                        },
                        required: ['hypothesis_id', 'strategy', 'direction', 'setup_mode', 'setup_timeframe', 'execution_timeframe']
                    }
                }
            },
            required: ['market_view', 'hypotheses']
        };
    }
    return { type: 'OBJECT', properties: { decision: { type: 'STRING', enum: ['SELECT', 'WAIT', 'BUY_LIMIT', 'SELL_LIMIT'] }, selected_candidate_id: { type: 'STRING' }, preferred_candidate_ids: strings, fallback_candidate_ids: strings, preferred_opportunity_role: { type: 'STRING', enum: ['ORIGINAL_THESIS_POI', 'FRESH_RETRACEMENT_POI', 'FRESH_CONTINUATION_POI', 'CONFIRMATION_POI'] }, fallback_allowed: { type: 'BOOLEAN' }, reasoning: { type: 'STRING' } }, required: ['decision', 'reasoning'] };
}

function getAIErrorCode(error = {}, transportDiagnostic = error?.transport_diagnostic || {}) {
    if (transportDiagnostic.transport_status === 'TIMEOUT') return 'AI_TIMEOUT';
    if (transportDiagnostic.http_status === 429) return 'AI_RATE_LIMITED';
    if (transportDiagnostic.transport_status === 'NETWORK_ERROR') return 'AI_NETWORK_ERROR';
    if (transportDiagnostic.transport_status === 'PARSE_ERROR') return 'AI_PARSE_ERROR';
    if (transportDiagnostic.transport_status === 'HTTP_ERROR') return `AI_HTTP_${transportDiagnostic.http_status || 'ERROR'}`;
    return error?.name === 'AIParseError' ? 'AI_PARSE_ERROR' : null;
}

const CLIENT_PROVIDER_SECRET_PATTERN = /(?:(?:gemini[_-]?api[_-]?key|deepseek[_-]?api[_-]?key|x-goog-api-key|authorization)\s*[:=]?\s*(?:bearer\s+)?[^\s,;]+|bearer\s+[^\s,;]+)/ig;

function sanitizeClientProviderText(value, maxLength = 1000) {
    if (value == null) return null;
    return String(value).slice(0, maxLength).replace(CLIENT_PROVIDER_SECRET_PATTERN, '[REDACTED]');
}

function normalizeClientProviderError(data = {}) {
    const source = data?.provider_error && typeof data.provider_error === 'object'
        ? data.provider_error
        : data?.error && typeof data.error === 'object' ? data.error : null;
    if (!source || Array.isArray(source)) return null;
    const quota = Array.isArray(source.quota) ? source.quota.slice(0, 24).map(item => {
        if (!item || typeof item !== 'object') return null;
        const dimensions = item.quota_dimensions && typeof item.quota_dimensions === 'object' && !Array.isArray(item.quota_dimensions)
            ? Object.fromEntries(Object.entries(item.quota_dimensions).slice(0, 16).filter(([key, value]) => /^[A-Za-z0-9_.-]{1,80}$/.test(key) && ['string', 'number', 'boolean'].includes(typeof value)).map(([key, value]) => [key, sanitizeClientProviderText(value, 160)]))
            : null;
        return {
            ...(item.quota_metric != null ? { quota_metric: sanitizeClientProviderText(item.quota_metric, 200) } : {}),
            ...(item.quota_id != null ? { quota_id: sanitizeClientProviderText(item.quota_id, 200) } : {}),
            ...(item.quota_value != null ? { quota_value: sanitizeClientProviderText(item.quota_value, 120) } : {}),
            ...(dimensions && Object.keys(dimensions).length ? { quota_dimensions: dimensions } : {})
        };
    }).filter(Boolean) : [];
    return {
        ...(source.code != null ? { code: typeof source.code === 'number' ? source.code : sanitizeClientProviderText(source.code, 80) } : {}),
        ...(source.type != null ? { type: sanitizeClientProviderText(source.type, 120) } : {}),
        ...(source.status != null ? { status: sanitizeClientProviderText(source.status, 120) } : {}),
        ...(source.message != null ? { message: sanitizeClientProviderText(source.message) } : {}),
        ...(quota.length ? { quota } : {}),
        ...(source.retry_delay != null ? { retry_delay: sanitizeClientProviderText(source.retry_delay, 80) } : {})
    };
}

if (typeof window !== 'undefined') window.setAIProvider = setAIProvider;

// Legacy helpers remain available for rollback/tests, while production calls
// use the provider-neutral endpoint above.
function getDeepSeekEndpoint() {
    const proxy = getProxyBaseUrl();
    return proxy ? `${proxy}/api/deepseek/chat` : DEEPSEEK_API_URL;
}

function getDeepSeekHeaders() {
    const headers = { 'Content-Type': 'application/json' };
    if (!getProxyBaseUrl() && DEEPSEEK_API_KEY) headers.Authorization = `Bearer ${DEEPSEEK_API_KEY}`;
    return headers;
}

function getAuditWriteToken() {
    const configured = typeof window !== 'undefined' ? window.__ICT_AUDIT_WRITE_TOKEN__ : null;
    return String(configured || '').trim();
}

function scanClock() {
    return typeof performance !== 'undefined' && typeof performance.now === 'function' ? performance.now() : Date.now();
}

function scanTrace(stage, startedAt, details = {}) {
    console.log(`[SCAN] ${stage}`, { elapsed_ms: Math.round((scanClock() - startedAt) * 100) / 100, ...details });
}

function getAIRequestUrlPath(url) {
    const raw = String(url || '');
    try {
        const parsed = new URL(raw, typeof window !== 'undefined' ? window.location.href : undefined);
        return parsed.pathname || '/';
    } catch {
        const match = raw.match(/^[a-z][a-z\d+.-]*:\/\/[^/]+(\/[^?#]*)/i);
        return match?.[1] || raw.split('?')[0].slice(0, 160);
    }
}

async function requestAIJson(url, options = {}, timeoutMs = AI_REQUEST_TIMEOUT_MS) {
    const controller = typeof AbortController === 'function'
        ? new AbortController()
        : { signal: undefined, abort() {} };
    let timeoutId;
    const requestBodyBytes = typeof options.body === 'string'
        ? (typeof TextEncoder === 'function' ? new TextEncoder().encode(options.body).byteLength : options.body.length)
        : null;
    const requestStartedAt = scanClock();
    const deadline = new Promise((resolve, reject) => {
        timeoutId = setTimeout(() => {
            const error = new Error('AI request deadline exceeded');
            error.name = 'AbortError';
            error.transport_diagnostic = {
                provider: getAIProvider(),
                model: getAIModel(),
                transport_status: 'TIMEOUT',
                request_transport: getProxyBaseUrl() ? 'SERVER_PROXY' : 'DIRECT',
                request_url_path: getAIRequestUrlPath(url),
                request_body_bytes: requestBodyBytes,
                timeout_ms: timeoutMs,
                request_duration_ms: Math.max(0, Math.round((scanClock() - requestStartedAt) * 100) / 100),
                abort_reason: 'CLIENT_DEADLINE'
            };
            reject(error);
            controller.abort();
        }, timeoutMs);
    });
    try {
        const requestOptions = controller.signal === undefined
            ? { ...options }
            : { ...options, signal: controller.signal };
        return await Promise.race([deadline, (async () => {
            const startedAt = requestStartedAt;
            let response;
            const requestUrlPath = getAIRequestUrlPath(url);
            try {
                response = await fetch(url, requestOptions);
            } catch (error) {
                error.transport_diagnostic = {
                    provider: getAIProvider(),
                    model: getAIModel(),
                    transport_status: error?.name === 'AbortError' ? 'TIMEOUT' : 'NETWORK_ERROR',
                    request_transport: getProxyBaseUrl() ? 'SERVER_PROXY' : 'DIRECT',
                    request_url_path: requestUrlPath,
                    request_body_bytes: requestBodyBytes,
                    timeout_ms: timeoutMs,
                    request_duration_ms: Math.max(0, Math.round((scanClock() - startedAt) * 100) / 100),
                    transport_error_name: error?.name || 'Error',
                    transport_error_message: String(error?.message || 'AI request failed').slice(0, 240)
                };
                throw error;
            }
            const contentType = response.headers?.get?.('content-type') || null;
            let data;
            try {
                if (typeof response.text === 'function') {
                    const responseText = await response.text();
                    data = responseText ? JSON.parse(responseText) : {};
                } else {
                    data = await response.json();
                }
            } catch (error) {
                const parseError = new Error('AI response JSON could not be parsed');
                parseError.name = 'AIParseError';
                parseError.transport_diagnostic = {
                    provider: getAIProvider(),
                    model: getAIModel(),
                    transport_status: 'PARSE_ERROR',
                    request_transport: getProxyBaseUrl() ? 'SERVER_PROXY' : 'DIRECT',
                    request_url_path: requestUrlPath,
                    request_body_bytes: requestBodyBytes,
                    timeout_ms: timeoutMs,
                    request_duration_ms: Math.max(0, Math.round((scanClock() - startedAt) * 100) / 100),
                    http_status: response.status ?? null,
                    http_status_text: response.statusText || null,
                    response_content_type: contentType,
                    transport_error_name: error?.name || 'SyntaxError',
                    transport_error_message: 'Provider/proxy returned non-JSON content'
                };
                throw parseError;
            }
            const providerTimeout = data?.error?.code === 'UPSTREAM_TIMEOUT' || data?.code === 'UPSTREAM_TIMEOUT' || response.status === 504;
            const providerError = normalizeClientProviderError(data);
            const transportDiagnostic = {
                provider: data?.provider || getAIProvider(),
                model: data?.model || getAIModel(),
                transport_status: providerTimeout ? 'TIMEOUT' : (response.ok === false ? 'HTTP_ERROR' : 'SUCCESS'),
                request_transport: getProxyBaseUrl() ? 'SERVER_PROXY' : 'DIRECT',
                request_url_path: requestUrlPath,
                request_body_bytes: requestBodyBytes,
                timeout_ms: timeoutMs,
                request_duration_ms: Math.max(0, Math.round((scanClock() - startedAt) * 100) / 100),
                http_status: response.status ?? null,
                http_status_text: response.statusText || null,
                response_content_type: contentType,
                provider_error_type: providerError?.status || data?.error?.type || data?.error?.name || null,
                provider_error_code: providerError?.code || data?.error?.code || data?.code || null,
                provider_error_status: providerError?.status || null,
                provider_error_message: providerError?.message || null,
                provider_quota_details: providerError?.quota || [],
                provider_retry_delay: providerError?.retry_delay || null,
                parse_status: 'OK',
                abort_reason: providerTimeout ? 'SERVER_UPSTREAM_TIMEOUT' : null
            };
            transportDiagnostic.usage = data?.usage || data?.usage_metadata || null;
            console.log('[SCAN] AI response received', { provider: getAIProvider(), model: getAIModel(), status: response.status, transport_status: transportDiagnostic.transport_status });
            if (response.ok === false) {
                const error = new Error(`${getAIProvider()} HTTP ${response.status}`);
                error.name = 'AIHttpError';
                error.http_status = response.status;
                error.provider_error = providerError;
                error.transport_diagnostic = transportDiagnostic;
                throw error;
            }
            return { response, data, transport_diagnostic: transportDiagnostic };
        })()]);
    } finally {
        clearTimeout(timeoutId);
    }
}

const SYMBOLS = {
    'BTC/USD':'BTC/USD',
    'EUR/USD':'EUR/USD','GBP/USD':'GBP/USD','USD/JPY':'USD/JPY',
    'AUD/USD':'AUD/USD','USD/CAD':'USD/CAD',
    'USD/CHF':'USD/CHF','NZD/USD':'NZD/USD',
    'EUR/GBP':'EUR/GBP','EUR/JPY':'EUR/JPY','GBP/JPY':'GBP/JPY',
    'XAU/USD':'XAU/USD','XAG/USD':'XAG/USD'
};

function normalizeSymbolInput(value) {
    return String(value || '').trim().toUpperCase().replace(/\s+/g, '');
}

// This is the single browser-side symbol boundary. Trading logic consumes the
// canonical slash form; provider adapters are the only layer that turns it
// into an exchange-qualified symbol. Compact fiat pairs are normalized here
// so quote, history, caches, snapshots, and evidence cannot disagree about
// the selected instrument.
function normalizeCanonicalMarketSymbol(value) {
    const normalized = normalizeSymbolInput(value);
    if (!normalized || normalized.includes(':')) return normalized;
    const aliases = { XAUUSD: 'XAU/USD', XAGUSD: 'XAG/USD', BTCUSD: 'BTC/USD' };
    if (aliases[normalized]) return aliases[normalized];
    const instrument = normalized.replace('/', '');
    if (/^[A-Z]{6}$/.test(instrument)) {
        const base = instrument.slice(0, 3);
        const quote = instrument.slice(3);
        if (FIAT_CURRENCY_CODES.has(base) && FIAT_CURRENCY_CODES.has(quote)) return `${base}/${quote}`;
    }
    return normalized;
}

function validateSymbolInput(value) {
    const symbol = normalizeCanonicalMarketSymbol(value);
    if (!symbol) return { valid: false, symbol: '', reason: 'Symbol is required.' };
    if (symbol.length > 32) return { valid: false, symbol, reason: 'Symbol is too long.' };
    if (!/^[A-Z0-9][A-Z0-9._:-]*(?:\/[A-Z0-9][A-Z0-9._:-]*)?$/.test(symbol)) {
        return { valid: false, symbol, reason: 'Use a provider symbol such as EUR/USD, AAPL, or BTC/USD.' };
    }
    return { valid: true, symbol, reason: null };
}

function getProviderSymbol(value) {
    const normalized = normalizeCanonicalMarketSymbol(value);
    return SYMBOLS[normalized] || normalized;
}

// HAS_REAL_VOLUME: Twelve Data returns synthetic/sparse volume for many forex
// and metals pairs (the v field falls back to 1e6 in getHistory). When false,
// volume-based scoring (volumeTruth surge/fake, sentiment volume, market-phase
// volumeRatio) must be downweighted or zeroed — fake volume is NOT confirmation.
// Crypto pairs (BTC) have real volume; XAU/XAG and FX pairs do not (varies by
// plan, but we default conservative).
function hasRealVolume(p, metadata = {}) {
    if (typeof metadata.volume_reliable === 'boolean') return metadata.volume_reliable;
    const sym = normalizeCanonicalMarketSymbol(p || pair);
    const assetClass = metadata.asset_class || getAssetClass(sym);
    return ['CRYPTO', 'EQUITY', 'INDEX'].includes(assetClass);
}

const FIAT_CURRENCY_CODES = new Set(['USD', 'EUR', 'GBP', 'JPY', 'AUD', 'CAD', 'CHF', 'NZD', 'HKD', 'SGD', 'NOK', 'SEK', 'CNH', 'CNY', 'MXN', 'ZAR', 'TRY', 'PLN']);
const CRYPTO_BASE_CODES = new Set(['BTC', 'ETH', 'SOL', 'XRP', 'ADA', 'DOGE', 'LTC', 'BCH', 'BNB', 'AVAX', 'DOT', 'LINK']);

let lastScanRejections = [];
const TF_MAP = { '1M':'1min','5M':'5min','15M':'15min','1H':'1h','4H':'4h','1D':'1day','1W':'1week' };
const HISTORY_OUTPUT_SIZE_BY_TIMEFRAME = Object.freeze({
    // MODEL_ROUTER audits MSNR on every supplied timeframe with the
    // deterministic 120-bar lookback below.  The old 50/80/100 request
    // sizes could therefore drop the origin of an otherwise still-valid
    // structural record before the router saw it.  This is a bounded input
    // change only; it does not alter any detector or qualification rule.
    '1M': 120,
    '5M': 120,
    '15M': 120,
    '1H': 120,
    '4H': 120,
    '1D': 120
});
const ALL_TIMEFRAMES = ['1M', '5M', '15M', '1H', '4H', '1D', '1W'];
const DEFAULT_ATR_PERIOD = 14;
const BUY_INVALIDATION_FACTOR = 0.998;
const SELL_INVALIDATION_FACTOR = 1.002;

// PURE QUALITY SELECTION: Quality (Conf 58, HTF 1/3, 2+ patterns) is the criteria.
// CHoCH/BOS/compression/ADX are confluence SCORING factors — no hard-block is removed, thresholds tuned.
const MIN_CONFIDENCE = 58;
const MAX_ZONE_TOUCHES = 10;
const LIMIT_ORDER_EXPIRY_HOURS = 4;
const ZONE_PROXIMITY_ALERT_PCT = 0.3;
const LIMIT_ORDER_MAX_DIST_ATR = 6.0;

// These models create an order ahead of price.  They must be evaluated from
// their future entry, not from whether price can revisit the zone today or
// whether a second confirmation candle has already formed.
function isPendingLimitExecutionModel(model) {
    return ['PENDING_LIMIT', 'FRESH_RETRACEMENT_LIMIT', 'STRUCTURAL_LIMIT',
        'MARKET_SHIFT', 'FLIP_ZONE', 'LIQUIDITY_OB_FVG', 'CRT_AGGRESSIVE',
        'CRT_CONSERVATIVE', 'CONTINUATION_MID_MOVE'].includes(String(model || '').toUpperCase());
}
function getCandidateExecutionQualityMinimum(candidate = {}) {
    const fullyAlignedPendingLimit = isPendingLimitExecutionModel(candidate.execution_model || candidate.entry_model)
        && Number(candidate.htf_alignment) === 3
        && candidate.trade_context_classification === 'HTF_ALIGNED_CONTINUATION';
    return fullyAlignedPendingLimit
        ? Number(STRATEGY_SPEC?.CONFIDENCE?.alignedPendingLimitMinimum) || 65
        : Number(STRATEGY_SPEC?.CONFIDENCE?.highQualityMinimum) || 70;
}
const HTF_MIN_MATCH = 1;
const AI_ADVISORY_ONLY = true;
const ICT_LAST_TRADE_TIME_KEY = 'ict_last_trade_time';
const ICT_FIVE_MIN_MS = 5 * 60 * 1000;

// ============================================
// MARKET SETTINGS
// ============================================
function getMarketSettings(p, metadata = {}) {
    const symbol = normalizeSymbolInput(p);
    const assetClass = metadata.asset_class || getAssetClass(symbol);
    const quoteCurrency = symbol.includes('/') ? symbol.split('/').pop() : '';
    const withMetadata = settings => ({
        ...settings,
        pipSize: Number.isFinite(Number(metadata.tick_size)) && Number(metadata.tick_size) > 0 ? Number(metadata.tick_size) : settings.pipSize,
        prec: Number.isInteger(Number(metadata.price_precision)) && Number(metadata.price_precision) >= 0 ? Number(metadata.price_precision) : settings.prec,
        minSL: Number.isFinite(Number(metadata.minimum_price_distance)) && Number(metadata.minimum_price_distance) > 0 ? Number(metadata.minimum_price_distance) : settings.minSL,
        slBuffer: Number.isFinite(Number(metadata.stop_buffer)) && Number(metadata.stop_buffer) >= 0 ? Number(metadata.stop_buffer) : settings.slBuffer,
        maxSLPct: Number.isFinite(Number(metadata.max_stop_pct)) && Number(metadata.max_stop_pct) > 0 ? Number(metadata.max_stop_pct) : settings.maxSLPct,
        targetRR: Number.isFinite(Number(metadata.minimum_rr)) && Number(metadata.minimum_rr) > 0 ? Number(metadata.minimum_rr) : settings.targetRR,
        minSLMultiplier: Number.isFinite(Number(metadata.min_sl_atr_multiplier)) && Number(metadata.min_sl_atr_multiplier) > 0 ? Number(metadata.min_sl_atr_multiplier) : settings.minSLMultiplier
    });
    if (assetClass === 'METAL') return withMetadata({ slBuffer: 3, minSL: 3, maxSLPct: 0.015, targetRR: 2.5, prec: 2, pipSize: 0.1, minSLMultiplier: 2.0 });
    if (assetClass === 'FOREX' && quoteCurrency === 'JPY') return withMetadata({ slBuffer: 0.15, minSL: 0.10, maxSLPct: 0.01, targetRR: 2.5, prec: 3, pipSize: 0.01 });
    if (assetClass === 'CRYPTO') return withMetadata({ slBuffer: 0, minSL: 0, maxSLPct: 0.25, targetRR: 2.5, prec: 8, pipSize: 0.00000001, minSLMultiplier: 2.0 });
    if (assetClass === 'EQUITY' || assetClass === 'INDEX') return withMetadata({ slBuffer: 0, minSL: 0, maxSLPct: 0.10, targetRR: 2.5, prec: 4, pipSize: 0.01, minSLMultiplier: 1.5 });
    if (assetClass === 'UNKNOWN') return withMetadata({ slBuffer: 0, minSL: 0, maxSLPct: 0.10, targetRR: 2.5, prec: 6, pipSize: 0.000001, minSLMultiplier: 1.5 });
    return withMetadata({ slBuffer: 0.0005, minSL: 0.0003, maxSLPct: 0.01, targetRR: 2.5, prec: 5, pipSize: 0.0001 });
}

function getPreferredStopAtrMultiplier(settings = {}) {
    // The old implementation applied a 0.75 factor and then capped at 1.5,
    // which silently made the metal floor effectively 1.5 ATR instead of
    // the configured 2.0 ATR. That is where most of the "stop hit on
    // every setup" behavior came from, because normal wicks through the
    // entry zone were wide enough to trigger the shrunken stop.
    // Honor the full configured minSLMultiplier up to a 3.0 ATR ceiling.
    // Because minSLMultiplier is defined per asset class in
    // getMarketSettings(), this automatically applies to every supported
    // pair (metals -> 2.0 ATR, crypto -> 2.0 ATR, FX -> 1.5 ATR,
    // equity/index -> 1.5 ATR).
    const configured = Number(settings.minSLMultiplier);
    const base = Number.isFinite(configured) && configured > 0 ? configured : 1.5;
    return Math.max(0.75, Math.min(3.0, base));
}

function getPrec(p, metadata = {}) { return getMarketSettings(p, metadata).prec; }

