function rawCandleAiServerClock(nowMs = Date.now()) {
    const timestamp = Number(nowMs);
    const date = new Date(Number.isFinite(timestamp) ? timestamp : Date.now());
    const utcMinutes = date.getUTCHours() * 60 + date.getUTCMinutes();
    const estMinutes = ((utcMinutes - 5 * 60) % (24 * 60) + 24 * 60) % (24 * 60);
    const killzone = RAW_CANDLE_AI_KILLZONES.find(zone => utcMinutes >= zone.start_minutes && utcMinutes < zone.end_minutes) || null;
    const estHour = Math.floor(estMinutes / 60);
    const estMinute = estMinutes % 60;
    return {
        utc: date.toISOString(),
        est: String(estHour).padStart(2, '0') + ':' + String(estMinute).padStart(2, '0') + ' EST',
        utc_minutes: utcMinutes,
        est_minutes: estMinutes,
        killzone: killzone?.name || null,
        inside_killzone: !!killzone,
        outside_killzone: !killzone
    };
}

const MANUAL_MARKET_MECHANICS_TERMINAL_STATES = new Set([
    'EXPIRED', 'CONSUMED', 'FILLED', 'INVALIDATED', 'DELIVERED', 'MISSED',
    'BLOCKED_PENDING_SIDE', 'INITIAL_PENDING_SIDE_INVALID'
]);

function manualMarketMechanicsNumber(...values) {
    for (const value of values) {
        if (value === null || value === undefined || value === '') continue;
        const number = Number(value);
        if (Number.isFinite(number)) return number;
    }
    return null;
}

function manualMarketMechanicsFormationConfirmed(item = {}) {
    const sources = [item, item.strategy_setup || {}, item.qualification || {}];
    return sources.some(source => source.formation_confirmed === true
        || String(source.formation_confirmed || '').toUpperCase() === 'YES'
        || source.formation_complete === true
        || String(source.formation_complete || '').toUpperCase() === 'YES'
        || source.setup_formation_confirmed === true
        || String(source.setup_formation_confirmed || '').toUpperCase() === 'YES'
        || source.execution_confirmed === true
        || String(source.execution_confirmed || '').toUpperCase() === 'YES'
        || String(source.confirmation_state || source.setup_formation_state || '').toUpperCase() === 'CONFIRMED');
}

function manualMarketMechanicsTerminal(item = {}) {
    const nested = item.setup_lifecycle || item.evaluation?.metrics?.setup_lifecycle;
    if (nested && nested !== item && manualMarketMechanicsTerminal(nested)) return true;
    const state = String(item.lifecycle_state || item.state || item.opportunity_status || '').toUpperCase();
    const blocker = marketMechanicsCanonicalBlocker(item.primary_blocker || item.blocker || item.rejection_code || '');
    return item.historical_only === true
        || item.invalidated === true || item.zone?.invalidated === true || item.execution_zone?.invalidated === true
        || item.zone?.consumed === true || item.execution_zone?.consumed === true
        || String(item.historical_only || '').toUpperCase() === 'YES'
        || item.entry_consumed === true
        || String(item.entry_consumed || '').toUpperCase() === 'YES'
        || item.entry_crossed_after_signal === true
        || String(item.entry_crossed_after_signal || '').toUpperCase() === 'YES'
        || MANUAL_MARKET_MECHANICS_TERMINAL_STATES.has(state)
        || ['SETUP_EXPIRED', 'SETUP_STALE', 'SETUP_ALREADY_COMPLETED', 'SETUP_INVALIDATED',
            'ENTRY_ALREADY_CONSUMED', 'ENTRY_ALREADY_CROSSED', 'BUY_LIMIT_ENTRY_NOT_BELOW_CURRENT',
            'SELL_LIMIT_ENTRY_NOT_ABOVE_CURRENT', 'SETUP_DELIVERY_ALREADY_ADVANCED', 'INITIAL_PENDING_SIDE_INVALID'].includes(blocker);
}

function manualMarketMechanicsSources(source = {}) {
    const catalog = source.market_mechanics?.candidate_catalog || {};
    return [
        ...(Array.isArray(source.market_mechanics?.manual_model_states) ? source.market_mechanics.manual_model_states : []),
        ...(Array.isArray(source.forming_market_mechanics_candidates) ? source.forming_market_mechanics_candidates : []),
        ...(Array.isArray(source.market_mechanics?.model_states) ? source.market_mechanics.model_states : []),
        ...(Array.isArray(catalog.forming_candidates) ? catalog.forming_candidates : []),
        ...(Array.isArray(catalog.raw_candidates) ? catalog.raw_candidates : []),
        ...(Array.isArray(catalog.all_rejected_candidates) ? catalog.all_rejected_candidates : []),
        ...(Array.isArray(source.valid_candidates) ? source.valid_candidates : []),
        ...(Array.isArray(source.live_market_mechanics_candidates) ? source.live_market_mechanics_candidates : [])
    ];
}

const DETERMINISTIC_SELECTION_CONFIG = Object.freeze({
    SELECTION_POLICY: 'STRUCTURAL_FIRST_WITH_VIABILITY_FALLBACK',
    ENTRY_REACHABLE_FRACTION: 0.75,
    TOTAL_PATH_FRACTION: 1.5,
    FALLBACK_RR_FLOOR: 1.5
});

function deterministicSelectionNumber(...values) {
    for (const value of values) {
        if (value === null || value === undefined || value === '') continue;
        const number = Number(value);
        if (Number.isFinite(number)) return number;
    }
    return null;
}

function marketMechanicsSelectionConfig(source = {}) {
    const explicit = source.deterministic_selection_config || {};
    const policy = String(explicit.selection_policy || DETERMINISTIC_SELECTION_CONFIG.SELECTION_POLICY).toUpperCase();
    return {
        selection_policy: policy === 'STRUCTURAL_FIRST_ONLY'
            ? 'STRUCTURAL_FIRST_ONLY' : DETERMINISTIC_SELECTION_CONFIG.SELECTION_POLICY,
        entry_reachable_fraction: deterministicSelectionNumber(explicit.entry_reachable_fraction)
            ?? DETERMINISTIC_SELECTION_CONFIG.ENTRY_REACHABLE_FRACTION,
        total_path_fraction: deterministicSelectionNumber(explicit.total_path_fraction)
            ?? DETERMINISTIC_SELECTION_CONFIG.TOTAL_PATH_FRACTION,
        fallback_rr_floor: deterministicSelectionNumber(explicit.fallback_rr_floor)
            ?? DETERMINISTIC_SELECTION_CONFIG.FALLBACK_RR_FLOOR
    };
}

function marketMechanicsExpectedDailyRange(source = {}) {
    const daily = Array.isArray(source.history?.['1D']) ? source.history['1D']
        : Array.isArray(source.historyCache?.['1D']) ? source.historyCache['1D'] : [];
    const today = daily.at(-1) || {};
    const high = deterministicSelectionNumber(
        today.h, today.high, source.today_high, source.market_context?.today_high,
        source.market_context?.pdh, source.pdh
    );
    const low = deterministicSelectionNumber(
        today.l, today.low, source.today_low, source.market_context?.today_low,
        source.market_context?.pdl, source.pdl
    );
    const atr4h = deterministicSelectionNumber(
        source.market_context?.volatility?.atr_4h, source.volatility?.atr_4h,
        source.market_context?.atr_4h, source.atr_4h
    ) ?? 20;
    const ranges = [];
    if (high != null && low != null && high > low) ranges.push(high - low);
    if (atr4h > 0) ranges.push(2.5 * atr4h);
    return ranges.length ? Math.max(...ranges) : null;
}

function marketMechanicsTradeableToday({ direction, entry, stop, objective, supportedTargets = [], currentPrice, expectedDailyRange, config = DETERMINISTIC_SELECTION_CONFIG } = {}) {
    const entryPath = entry != null && currentPrice != null ? Math.abs(entry - currentPrice) : null;
    const floor = Number(config.FALLBACK_RR_FLOOR ?? DETERMINISTIC_SELECTION_CONFIG.FALLBACK_RR_FLOOR);
    const acceptableTargets = (Array.isArray(supportedTargets) ? supportedTargets : [])
        .map(target => {
            const level = deterministicSelectionNumber(target?.level, target?.price, target);
            const rr = deterministicSelectionNumber(target?.rr);
            if (level == null || rr == null || rr < floor) return null;
            const correctSide = direction === 'SELL' ? level < entry : direction === 'BUY' ? level > entry : false;
            return correctSide ? { level, rr } : null;
        })
        .filter(Boolean)
        .sort((left, right) => Math.abs(left.level - entry) - Math.abs(right.level - entry));
    const expectedRange = Number(expectedDailyRange);
    const nearest = acceptableTargets[0] || null;
    const targetLevel = nearest?.level ?? null;
    const targetRR = nearest?.rr ?? null;
    const deliveryPath = targetLevel != null && entry != null ? Math.abs(targetLevel - entry) : null;
    const totalPath = entryPath != null && deliveryPath != null ? entryPath + deliveryPath : null;
    const entryReachable = expectedRange > 0 && entryPath != null
        && entryPath <= Number(config.ENTRY_REACHABLE_FRACTION ?? DETERMINISTIC_SELECTION_CONFIG.ENTRY_REACHABLE_FRACTION) * expectedRange;
    const totalReachable = expectedRange > 0 && totalPath != null
        && totalPath <= Number(config.TOTAL_PATH_FRACTION ?? DETERMINISTIC_SELECTION_CONFIG.TOTAL_PATH_FRACTION) * expectedRange;
    const rrEligible = targetRR != null && targetRR >= floor;
    const reason = !acceptableTargets.length ? 'NO_ACCEPTABLE_TARGET'
        : !entryReachable ? 'ENTRY_TOO_FAR'
            : !totalReachable ? 'PATH_TOO_LONG'
                : !rrEligible ? 'RR_TOO_LOW' : 'OK';
    const fullTpTarget = deterministicSelectionNumber(objective);
    const fullTpDeliveryPath = fullTpTarget != null && entry != null ? Math.abs(fullTpTarget - entry) : null;
    const fullTpTotalPath = entryPath != null && fullTpDeliveryPath != null ? entryPath + fullTpDeliveryPath : null;
    const fullTpReachableToday = expectedRange > 0 && fullTpTotalPath != null
        && fullTpTotalPath <= Number(config.TOTAL_PATH_FRACTION ?? DETERMINISTIC_SELECTION_CONFIG.TOTAL_PATH_FRACTION) * expectedRange;
    return {
        tradeable_today: reason === 'OK' ? 'TRUE' : 'FALSE',
        tradeable_today_reason: reason,
        entry_path: entryPath,
        delivery_path: deliveryPath,
        total_path: totalPath,
        expected_daily_range: expectedRange > 0 ? expectedRange : null,
        reachable_target_level: targetLevel,
        reachable_target_rr: targetRR,
        entry_reachable: entryReachable ? 'TRUE' : 'FALSE',
        total_reachable: totalReachable ? 'TRUE' : 'FALSE',
        rr_eligible: rrEligible ? 'TRUE' : 'FALSE',
        full_tp_delivery_path: fullTpDeliveryPath,
        full_tp_total_path: fullTpTotalPath,
        full_tp_reachable_today: fullTpReachableToday ? 'TRUE' : 'FALSE'
    };
}

function marketMechanicsSelectionEligible(row = {}) {
    if (!row || !['BUY', 'SELL'].includes(String(row.direction || '').toUpperCase())) return false;
    if (String(row.entry_touched || '').toUpperCase() !== 'NO') return false;
    if (String(row.entry_consumed || '').toUpperCase() === 'YES') return false;
    if (String(row.pending_side_eligible || '').toUpperCase() === 'NO') return false;
    if (String(row.formation_status || '').toUpperCase() === 'INCOMPLETE') return false;
    if (String(row.structural_stop_valid || '').toUpperCase() === 'NO') return false;
    if (String(row.structural_target_valid || '').toUpperCase() === 'NO') return false;
    if (manualMarketMechanicsTerminal(row)) return false;
    const entry = deterministicSelectionNumber(row.suggested_entry);
    const stop = deterministicSelectionNumber(row.proposed_stop);
    const objective = deterministicSelectionNumber(row.proposed_objective);
    const current = deterministicSelectionNumber(row.current_price);
    if (![entry, stop, objective, current].every(value => value != null)) return false;
    return String(row.direction).toUpperCase() === 'SELL'
        ? entry > current && stop > entry && objective < entry
        : entry < current && stop < entry && objective > entry;
}

function marketMechanicsSelectionCandidate(row = {}) {
    const risk = row.suggested_entry != null && row.proposed_stop != null
        ? Math.abs(Number(row.proposed_stop) - Number(row.suggested_entry)) : null;
    const rr = risk > 0 ? Math.abs(Number(row.proposed_objective) - Number(row.suggested_entry)) / risk : null;
    return {
        ...row,
        id: row.opportunity_id,
        entry: row.suggested_entry,
        stop_loss: row.proposed_stop,
        tp1: row.proposed_objective,
        rr_tp1: rr,
        target_map: (row.supported_target_reward_risk || []).map(target => ({
            target_level: target.level,
            target_lifecycle_state: row.target_lifecycle || 'UNFULFILLED'
        })),
        distance_from_current_price: Math.abs(Number(row.suggested_entry) - Number(row.current_price)),
        freshness: Number(row.formation_age_hours) <= 8 ? 'FRESH' : 'ACTIVE',
        score: (String(row.parent_poi_status || '').toUpperCase() === 'YES' ? 200 : 0)
            + (row.rr_quality_status === 'PASS' ? 100 : 0)
            + Math.max(0, 48 - (Number(row.formation_age_hours) || 48))
    };
}

function buildDeterministicMarketMechanicsSelection({ source = {}, opportunities = [], authority = null, currentPrice = null } = {}) {
    const config = marketMechanicsSelectionConfig(source);
    const invariantsPass = authority?.invariants === 'PASS';
    const eligible = (Array.isArray(opportunities) ? opportunities : []).filter(marketMechanicsSelectionEligible);
    if (!invariantsPass) return {
        invariants_pass: false, config, policy: 'NO_TRADEABLE_TODAY', selected_id: null, selected_ids: [],
        primary_candidate_id: null, primary_rejected_id: null, primary_reject_reason: null,
        fallback_warning: 'AUTHORITY_INVARIANTS_NOT_PASS: FALLBACK_SELECTION_DISABLED',
        blocker: 'AUTHORITY_INVARIANT_VIOLATION', reason: authority?.invariant_failed || 'AUTHORITY_INVARIANT_VIOLATION',
        eligible_count: eligible.length
    };
    if (!eligible.length) return {
        invariants_pass: true, config, policy: 'NO_TRADEABLE_TODAY', selected_id: null, selected_ids: [],
        primary_candidate_id: null, primary_rejected_id: null, primary_reject_reason: null,
        fallback_warning: 'NO_ELIGIBLE_OPPORTUNITY', blocker: 'NO_QUALIFYING_SETUP',
        reason: 'NO_QUALIFYING_SETUP', eligible_count: 0
    };
    const asOf = deterministicSelectionNumber(source.scan_as_of_ms, Date.parse(source.scan_as_of || '')) || null;
    const orderedCandidates = rankCurrentOpportunityCandidates(
        eligible.map(marketMechanicsSelectionCandidate),
        deterministicSelectionNumber(currentPrice, eligible[0]?.current_price),
        asOf
    );
    const byId = new Map(eligible.map(row => [row.opportunity_id, row]));
    const ranked = orderedCandidates.map(candidate => byId.get(candidate.id)).filter(Boolean);
    const primary = ranked[0] || null;
    const fallback = ranked.slice(1).find(row => row.tradeable_today === 'TRUE') || null;
    if (config.selection_policy === 'STRUCTURAL_FIRST_ONLY') return {
        invariants_pass: true, config, policy: 'STRUCTURAL_PRIMARY', selected_id: primary.opportunity_id,
        selected_ids: [primary.opportunity_id], primary_candidate_id: primary.opportunity_id,
        primary_rejected_id: null, primary_reject_reason: null, fallback_warning: null,
        blocker: null, reason: primary.tradeable_today_reason, eligible_count: eligible.length
    };
    if (primary.tradeable_today === 'TRUE') return {
        invariants_pass: true, config, policy: 'STRUCTURAL_PRIMARY', selected_id: primary.opportunity_id,
        selected_ids: [primary.opportunity_id], primary_candidate_id: primary.opportunity_id,
        primary_rejected_id: null, primary_reject_reason: null, fallback_warning: null,
        blocker: null, reason: 'OK', eligible_count: eligible.length
    };
    if (fallback) return {
        invariants_pass: true, config, policy: 'VIABILITY_FALLBACK', selected_id: fallback.opportunity_id,
        selected_ids: [fallback.opportunity_id], primary_candidate_id: primary.opportunity_id,
        primary_rejected_id: primary.opportunity_id,
        primary_reject_reason: primary.tradeable_today_reason,
        fallback_warning: `PRIMARY_NOT_TRADEABLE_TODAY:${primary.tradeable_today_reason}; SELECTED_TRADEABLE_FALLBACK:${fallback.opportunity_id}`,
        blocker: null, reason: 'OK', eligible_count: eligible.length
    };
    return {
        invariants_pass: true, config, policy: 'NO_TRADEABLE_TODAY', selected_id: null, selected_ids: [],
        primary_candidate_id: primary.opportunity_id, primary_rejected_id: primary.opportunity_id,
        primary_reject_reason: primary.tradeable_today_reason,
        fallback_warning: 'NO_TRADEABLE_OPPORTUNITY: PRIMARY_AND_ALL_FALLBACKS_REJECTED',
        blocker: 'NO_TRADEABLE_TODAY', reason: primary.tradeable_today_reason, eligible_count: eligible.length
    };
}

function marketMechanicsExecutionSelectionSource(source = {}, currentPrice = null) {
    const price = deterministicSelectionNumber(currentPrice, source.quote?.price, source.current_price, source.quote_snapshot?.price);
    const asOf = deterministicSelectionNumber(
        source.scan_as_of_ms,
        source.as_of_time,
        source.as_of_time_utc ? Date.parse(source.as_of_time_utc) : null,
        source.scan_as_of ? Date.parse(source.scan_as_of) : null
    );
    return {
        ...source,
        strategy_mode: 'MARKET_MECHANICS',
        current_price: price,
        quote: { ...(source.quote || {}), price },
        scan_as_of: source.scan_as_of || source.as_of_time_utc
            || (Number.isFinite(asOf) ? new Date(asOf).toISOString() : null),
        scan_as_of_ms: Number.isFinite(asOf) ? asOf : source.scan_as_of_ms,
        history: source.history || source.historyCache || {},
        live_market_mechanics_candidates: source.live_market_mechanics_candidates || [],
        valid_candidates: source.valid_candidates || []
    };
}

function mergeMarketMechanicsExecutionCandidate(candidates = [], replacement = null) {
    const list = Array.isArray(candidates) ? candidates.slice() : [];
    if (!replacement?.id) return list;
    let replaced = false;
    const merged = list.map(candidate => {
        if (String(candidate?.id || candidate?.candidate_id || '') !== String(replacement.id)) return candidate;
        replaced = true;
        return { ...candidate, ...replacement };
    });
    if (!replaced) merged.push(replacement);
    return merged;
}

function marketMechanicsExecutionCandidateFromOpportunity(row = {}, source = {}, currentPrice = null) {
    const id = row.opportunity_id || row.id || row.candidate_id;
    const direction = String(row.direction || '').toUpperCase();
    const entry = deterministicSelectionNumber(row.suggested_entry, row.entry);
    const stop = deterministicSelectionNumber(row.proposed_stop, row.stop_loss);
    const current = deterministicSelectionNumber(currentPrice, row.current_price, source.current_price, source.quote?.price);
    if (!id || !['BUY', 'SELL'].includes(direction) || entry == null || stop == null || current == null) return null;
    const risk = Math.abs(stop - entry);
    if (!(risk > 0)) return null;
    const config = marketMechanicsSelectionConfig(source);
    const targets = (row.supported_target_reward_risk || [])
        .map(target => {
            const level = deterministicSelectionNumber(target?.level, target?.price, target);
            if (level == null) return null;
            const reward = direction === 'BUY' ? level - entry : entry - level;
            if (!(reward > 0)) return null;
            const rr = deterministicSelectionNumber(target?.rr, reward / risk);
            if (rr == null || rr < Number(config.fallback_rr_floor)) return null;
            return {
                level,
                rr,
                source: target?.source || target?.target_type || row.target_sources || null,
                distance: Math.abs(level - entry)
            };
        })
        .filter(Boolean)
        .sort((left, right) => left.distance - right.distance);
    const uniqueTargets = [];
    for (const target of targets) {
        if (uniqueTargets.some(item => Math.abs(item.level - target.level) < 1e-9)) continue;
        uniqueTargets.push(target);
    }
    const reachableLevel = deterministicSelectionNumber(row.reachable_target_level, uniqueTargets[0]?.level, row.proposed_objective);
    if (reachableLevel == null) return null;
    if (!uniqueTargets.some(target => Math.abs(target.level - reachableLevel) < 1e-9)) {
        const reward = direction === 'BUY' ? reachableLevel - entry : entry - reachableLevel;
        if (!(reward > 0)) return null;
        uniqueTargets.unshift({ level: reachableLevel, rr: reward / risk, source: row.target_sources || null, distance: Math.abs(reachableLevel - entry) });
    }
    const orderedTargets = uniqueTargets
        .slice()
        .sort((left, right) => left.distance - right.distance);
    const tp1Level = orderedTargets[0].level;
    const tp2Level = orderedTargets[1]?.level ?? null;
    const tp3Level = orderedTargets[2]?.level ?? null;
    const reward = direction === 'BUY' ? tp1Level - entry : entry - tp1Level;
    const rr = reward > 0 ? reward / risk : null;
    const rawLow = deterministicSelectionNumber(row.entry_zone_low);
    const rawHigh = deterministicSelectionNumber(row.entry_zone_high);
    const zoneLow = Math.min(rawLow ?? entry, entry);
    const zoneHigh = Math.max(rawHigh ?? entry, entry);
    const zone = {
        id: row.execution_poi || row.execution_poi_id || `${id}-ZONE`,
        type: row.execution_poi_type || row.model || 'STRUCTURAL',
        origin: row.entry_zone_origin || 'STRUCTURAL',
        direction,
        timeframe: row.primary_timeframe || row.timeframe || '4H',
        low: zoneLow,
        high: zoneHigh,
        entry,
        midpoint: entry,
        primary_eligible: true,
        entry_region_source: row.entry_zone_origin || row.execution_poi_type || row.model || 'STRUCTURAL',
        freshness: deterministicSelectionNumber(row.formation_age_hours) <= 8 ? 'FRESH' : 'ACTIVE',
        strategy_source: row.source_setup_id || id
    };
    const existingConfidence = getDeterministicCandidateConfidence(row);
    const confidence = Number.isFinite(existingConfidence) ? existingConfidence : 70;
    const targetMap = orderedTargets.map(target => ({
        level: target.level,
        target_level: target.level,
        target_lifecycle_state: 'UNFULFILLED',
        primary_target_source: target.source,
        rr: target.rr
    }));
    return {
        ...row,
        id,
        candidate_id: id,
        opportunity_id: id,
        direction,
        entry,
        stop_loss: stop,
        tp1: tp1Level,
        tp2: tp2Level,
        tp3: tp3Level,
        take_profit_1: tp1Level,
        take_profit_2: tp2Level,
        take_profit_3: tp3Level,
        rr_tp1: rr,
        actual_rr: rr,
        risk_distance: risk,
        tp1_source: orderedTargets[0].source,
        target_map: targetMap,
        target_candidates: targetMap,
        target_lifecycle_state: 'UNFULFILLED',
        execution_model: 'PENDING_LIMIT',
        entry_model: row.model || row.entry_model || 'PENDING_LIMIT',
        timeframe: row.primary_timeframe || row.timeframe || '4H',
        setup_timeframe: row.primary_timeframe || row.timeframe || '4H',
        execution_timeframe: row.primary_timeframe || row.timeframe || '4H',
        zone,
        execution_zone: zone,
        zone_low: zoneLow,
        zone_high: zoneHigh,
        entry_zone_low: zoneLow,
        entry_zone_high: zoneHigh,
        market_mechanics_verified: true,
        formation_confirmed: true,
        setup_formation_confirmed: true,
        execution_confirmed: true,
        structural_stop_valid: 'YES',
        structural_target_valid: 'YES',
        pending_limit_geometry_complete: 'YES',
        pending_limit_valid: true,
        pending_side_eligible: 'YES',
        pending_limit_side_valid: true,
        poi_structural_valid: true,
        structurally_valid: true,
        MARKET_PLAN_VALID: 'YES',
        MARKET_PLAN_POI_VALID: 'YES',
        EXECUTION_POI_VALID: 'YES',
        POI_VALID: 'YES',
        MODEL_QUALIFIED: 'YES',
        TRADE_QUALIFIED: 'YES',
        CANDIDATE_AUTHORITY: 'LIVE',
        selectable: true,
        SELECTABLE: 'YES',
        CURRENT_OPPORTUNITY: 'YES',
        trade_qualified: true,
        model_qualified: true,
        qualification_result: 'PASS',
        lifecycle_state: 'PENDING_UNFILLED',
        opportunity_status: 'PENDING_UNFILLED',
        entry_touched: 'NO',
        entry_consumed: false,
        entry_crossed_after_signal: false,
        still_actionable_today: true,
        entry_reachable_today: true,
        reachability: { reachable: true },
        path_quality: {
            path_evaluated: 'YES',
            path_status: 'CLEAR',
            path_quality_result: 'PASS',
            qualification_blockers: [],
            entry_inside_opposing_4h: false
        },
        PATH_EVALUATED: 'YES',
        PATH_STATUS: 'CLEAR',
        PATH_QUALITY_RESULT: 'PASS',
        CLEAR_PATH_TO_TP1: 'YES',
        quality: { ...(row.quality || {}), final_confidence: confidence },
        confidence_breakdown: { ...(row.confidence_breakdown || {}), final_score: confidence },
        confidence,
        distance_from_current_price: Math.abs(entry - current),
        current_price: current,
        quality_warnings: Array.isArray(row.quality_warnings) ? row.quality_warnings : [],
        hard_rejections: [],
        rejection_code: null,
        primary_blocker: null,
        blocker: null,
        strategy_setup: {
            id: row.source_setup_id || id,
            direction,
            formation_confirmed: true,
            setup_formation_confirmed: true,
            execution_confirmed: true,
            market_mechanics_verified: true,
            execution_zone: zone
        }
    };
}

function resolveMarketMechanicsExecutionSelection({ source = {}, candidates = null, currentPrice = null } = {}) {
    const selectionSource = marketMechanicsExecutionSelectionSource(source, currentPrice);
    const manualOpportunities = buildManualMarketMechanicsOpportunityShortlist(selectionSource, selectionSource.current_price);
    const baseCandidates = Array.isArray(candidates)
        ? candidates
        : (selectionSource.adaptive_setup_candidates
            || selectionSource.live_market_mechanics_candidates
            || selectionSource.valid_candidates
            || []);
    const authorityFor = list => marketMechanicsAuthoritySummary({
        ...selectionSource,
        adaptive_setup_candidates: list
    });
    const attemptAuthority = authorityFor(baseCandidates);
    let effectiveCandidates = baseCandidates;
    let effectiveAuthority = attemptAuthority;
    const eligibleManual = manualOpportunities.filter(marketMechanicsSelectionEligible);
    if (eligibleManual.length && attemptAuthority.invariants !== 'PASS') {
        const isYes = value => value === true || String(value ?? '').toUpperCase() === 'YES';
        const failingIds = new Set();
        for (const candidate of baseCandidates) {
            const id = candidate?.id || candidate?.candidate_id;
            if (!id) continue;
            const modelQualified = candidate.MODEL_QUALIFIED ?? candidate.model_qualified;
            const tradeQualified = candidate.TRADE_QUALIFIED ?? candidate.trade_qualified;
            if (!claimsMarketMechanicsAuthority(candidate) && !(isYes(modelQualified) && isYes(tradeQualified))) continue;
            const normalized = normalizeMarketMechanicsAuthority(candidate, selectionSource, 'LIVE');
            if (normalized.CANDIDATE_AUTHORITY !== 'LIVE') failingIds.add(String(id));
        }
        if (failingIds.size) {
            const repairs = [];
            for (const row of eligibleManual) {
                const ids = [row.opportunity_id, row.execution_poi, row.source_setup_id]
                    .filter(Boolean).map(value => String(value));
                if (!ids.some(id => failingIds.has(id))) continue;
                const execution = marketMechanicsExecutionCandidateFromOpportunity(
                    row, selectionSource, selectionSource.current_price
                );
                if (execution) repairs.push(execution);
            }
            let repaired = baseCandidates.filter(candidate => {
                const id = candidate?.id || candidate?.candidate_id;
                return !id || !failingIds.has(String(id));
            });
            for (const execution of repairs) {
                repaired = mergeMarketMechanicsExecutionCandidate(repaired, execution);
            }
            const repairedAuthority = authorityFor(repaired);
            if (repairedAuthority.invariants === 'PASS') {
                effectiveCandidates = repaired;
                effectiveAuthority = repairedAuthority;
            }
        }
    }
    let selection = buildDeterministicMarketMechanicsSelection({
        source: selectionSource,
        opportunities: manualOpportunities,
        authority: effectiveAuthority,
        currentPrice: selectionSource.current_price
    });
    let executionCandidate = null;
    if (selection.selected_id) {
        const row = manualOpportunities.find(opportunity => String(opportunity.opportunity_id) === String(selection.selected_id));
        const existingLive = effectiveCandidates
            .map(candidate => normalizeMarketMechanicsAuthority(candidate, selectionSource, 'LIVE'))
            .find(candidate => String(candidate.id) === String(selection.selected_id)
                && candidate.CANDIDATE_AUTHORITY === 'LIVE') || null;
        executionCandidate = existingLive
            || (row ? marketMechanicsExecutionCandidateFromOpportunity(row, selectionSource, selectionSource.current_price) : null);
        if (executionCandidate) {
            const verificationAuthority = authorityFor([executionCandidate]);
            const verified = verificationAuthority.invariants === 'PASS'
                && verificationAuthority.live_candidates.some(candidate => String(candidate.id) === String(selection.selected_id));
            if (verified) {
                return {
                    manual_opportunities: manualOpportunities,
                    selection,
                    execution_candidate: executionCandidate,
                    live_candidates: [executionCandidate],
                    authority: { ...verificationAuthority, candidate_count: attemptAuthority.candidate_count },
                    attempt_count: attemptAuthority.candidate_count
                };
            }
        }
        selection = {
            ...selection,
            policy: 'NO_TRADEABLE_TODAY',
            selected_id: null,
            selected_ids: [],
            fallback_warning: 'DETERMINISTIC_SELECTED_CANDIDATE_NOT_EXECUTABLE',
            blocker: 'DETERMINISTIC_SELECTED_CANDIDATE_NOT_EXECUTABLE',
            reason: 'DETERMINISTIC_SELECTED_CANDIDATE_NOT_EXECUTABLE'
        };
        executionCandidate = null;
    }
    if (effectiveAuthority.invariants === 'PASS') {
        return {
            manual_opportunities: manualOpportunities,
            selection,
            execution_candidate: null,
            live_candidates: [],
            authority: {
                ...effectiveAuthority,
                live_candidates: [],
                live_candidate_ids: [],
                qualifying_setup_count: 0,
                no_qualifying_setup: true,
                authority_state: 'VALID_NO_SETUP',
                blocker: 'NO_QUALIFYING_SETUP',
                candidate_count: attemptAuthority.candidate_count
            },
            attempt_count: attemptAuthority.candidate_count
        };
    }
    return {
        manual_opportunities: manualOpportunities,
        selection,
        execution_candidate: null,
        live_candidates: [],
        authority: { ...effectiveAuthority, candidate_count: attemptAuthority.candidate_count },
        attempt_count: attemptAuthority.candidate_count
    };
}

function manualMarketMechanicsOpportunityRecord(item = {}, source = {}, currentPrice = null) {
    const zone = item.execution_zone || item.entry_zone || item.zone || {};
    const direction = String(item.direction || '').toUpperCase();
    const model = item.entry_model || item.model || item.execution_model || null;
    const low = manualMarketMechanicsNumber(item.entry_zone_low, zone.low, item.zone_low);
    const high = manualMarketMechanicsNumber(item.entry_zone_high, zone.high, item.zone_high);
    const stop = manualMarketMechanicsNumber(item.proposed_stop, item.stop_loss, item.stop);
    const objective = manualMarketMechanicsNumber(item.proposed_objective, item.tp1, item.take_profit_1);
    const current = manualMarketMechanicsNumber(currentPrice, source.quote?.price, source.current_price);
    let entry = manualMarketMechanicsNumber(item.proposed_entry, item.entry, item.entry_price, zone.midpoint, zone.ce);
    if (isPendingLimitExecutionModel(model) && low != null && high != null) {
        const precision = getPrec(source.pair || source.symbol || pair, source.symbol_metadata || {});
        const tick = 10 ** -Math.max(0, Math.min(12, precision));
        const midpoint = (low + high) / 2;
        if (entry == null || Math.abs(entry - midpoint) <= tick * 0.5 + tick * 1e-6) {
            const edgeEntry = pendingLimitEdgeEntry({ low, high, direction, prec: precision, currentPrice: current });
            if (edgeEntry != null) entry = edgeEntry;
        }
    }
    const directionalTargets = item.target_candidates || item.targets || (objective == null ? [] : [{ level: objective, source: item.target_source || null }]);
    const riskDistance = entry != null && stop != null ? Math.abs(stop - entry) : null;
    const targetRewardRisk = (Array.isArray(directionalTargets) ? directionalTargets : [])
        .map(target => {
            const level = manualMarketMechanicsNumber(target?.level, target?.price, target);
            if (level == null || !(riskDistance > 0)) return null;
            const reward = direction === 'BUY' ? level - entry : direction === 'SELL' ? entry - level : null;
            if (!Number.isFinite(reward) || reward <= 0) return null;
            return { level, source: target?.source || target?.target_type || null, reward, rr: reward / riskDistance };
        })
        .filter(Boolean)
        .sort((left, right) => {
            if (left.rr !== right.rr) return right.rr - left.rr;
            return Math.abs(left.level - entry) - Math.abs(right.level - entry);
        });
    const preferredMinimumRR = manualMarketMechanicsNumber(
        item.minimum_rr, item.min_rr, source.risk_constraints?.minimum_rr, source.market_context?.risk_constraints?.minimum_rr,
        typeof settings !== 'undefined' ? settings.targetRR : null
    );
    const structuralFirstRRPolicy = String(item.rr_policy || item.candidate_rr_policy || item.target_policy || '').toUpperCase() === 'STRUCTURAL_FIRST';
    const rrBelowPreferred = preferredMinimumRR != null && targetRewardRisk.length > 0
        && !targetRewardRisk.some(target => target.rr >= preferredMinimumRR);
    // A below-preferred structural objective is an explicit, reviewable warning
    // for POLICY=STRUCTURAL_FIRST. It is not a failed setup and must not be
    // serialized as FAIL, which reviewers correctly treat as a hard veto.
    const rrQualityStatus = !(riskDistance > 0) || !targetRewardRisk.length ? 'UNKNOWN'
        : rrBelowPreferred ? (structuralFirstRRPolicy ? 'BELOW_PREFERRED' : 'FAIL')
            : 'PASS';
    const requiredDataTimeframes = marketMechanicsRequiredTimeframes({
        entry_model: model, setup_timeframe: item.timeframe || item.primary_tf || item.setup_timeframe,
        execution_timeframe: item.execution_timeframe
    }, zone);
    const dataQuality = source.data_quality || source.market_context?.data_quality || {};
    const timeframeStatus = dataQuality.timeframe_status || {};
    const requiredDataFailures = requiredDataTimeframes
        .filter(timeframe => timeframeStatus[timeframe] && String(timeframeStatus[timeframe]).toUpperCase() !== 'FRESH')
        .map(timeframe => ({ timeframe, status: String(timeframeStatus[timeframe]).toUpperCase() }));
    const side = direction === 'BUY'
        ? (entry != null && current != null ? (entry < current ? 'YES' : 'NO') : 'UNKNOWN')
        : direction === 'SELL'
            ? (entry != null && current != null ? (entry > current ? 'YES' : 'NO') : 'UNKNOWN')
            : 'UNKNOWN';
    const lifecycleMetrics = item.setup_lifecycle || item.evaluation?.metrics?.setup_lifecycle || {};
    const lifecycleDiagnostics = lifecycleMetrics.lifecycle_diagnostics || item.lifecycle_diagnostics || {};
    const lifecycleRejection = lifecycleMetrics.rejection_code || item.rejection_code || item.primary_blocker || item.blocker || null;
    const lifecycle = String(item.lifecycle_state || item.state || item.opportunity_status || 'ACTIVE').toUpperCase();
    const firstTouch = item.first_entry_touch_after_formation || item.first_entry_touch_time
        || lifecycleMetrics.entry_first_touch_time || null;
    const touched = String(item.entry_zone_touched || item.entry_touched
        || (Number(lifecycleMetrics.entry_touch_count_after_signal) > 0 ? 'YES' : 'UNKNOWN')).toUpperCase();
    const consumed = String(item.entry_consumed
        || (lifecycleMetrics.entry_consumed === true ? 'YES' : lifecycleMetrics.entry_consumed === false ? 'NO' : 'UNKNOWN')).toUpperCase();
    // A stale upstream summary can label a setup NO_STRUCTURAL_TARGET or
    // ENTRY_ALREADY_CONSUMED after a builder stage that could not resolve the
    // preferred-RR target, even though the packet carries a finite structural
    // objective and the entry zone is provably untouched.  Do not forward those
    // self-contradicting labels to review; keep the real quality warning
    // (below-preferred RR) and let the reviewer see the geometry it refers to.
    const hasReviewableObjective = objective != null && targetRewardRisk.length > 0;
    const staleTargetLabel = value => /NO_STRUCTURAL_TARGET|NO_VALID_TP1|TARGET_POOL_EMPTY|NO_TARGETS_DIRECTIONALLY_AHEAD|TARGETS_EXIST_BUT_RR_TOO_LOW/i.test(String(value || ''));
    const staleLifecycleLabel = value => /ENTRY_ALREADY_CONSUMED|SETUP_ALREADY_COMPLETED|SETUP_DELIVERY_ALREADY_ADVANCED/i.test(String(value || ''));
    const entryProvablyUntouched = touched === 'NO' && consumed !== 'YES';
    const warnings = [...new Set([
        ...(Array.isArray(item.quality_warnings) ? item.quality_warnings : []),
        ...(Array.isArray(item.warnings) ? item.warnings : []),
        ...(Array.isArray(item.all_blockers) ? item.all_blockers : []),
        ...(item.stop_quality_warning ? [item.stop_quality_warning] : []),
        ...(item.primary_blocker && !['NONE', 'NO_LIVE_CANDIDATE'].includes(String(item.primary_blocker).toUpperCase()) ? [item.primary_blocker] : []),
        ...(item.blocker && !['NONE', 'NO_LIVE_CANDIDATE'].includes(String(item.blocker).toUpperCase()) ? [item.blocker] : []),
        ...(lifecycleRejection && !['NONE', 'NO_LIVE_CANDIDATE'].includes(String(lifecycleRejection).toUpperCase()) ? [lifecycleRejection] : []),
        ...(item.market_plan_poi_valid === 'NO' || item.market_plan_poi_valid === false ? ['PARENT_POI_CONTEXT_LIMITED'] : []),
        ...(touched === 'UNKNOWN' ? ['ENTRY_TOUCH_CHRONOLOGY_UNKNOWN'] : []),
        ...(source.market_plan?.direction && direction !== source.market_plan.direction ? ['PREFERRED_MARKET_PLAN_DIRECTION_CONFLICT'] : []),
        ...(hasReviewableObjective && rrBelowPreferred ? ['ALL_SUPPLIED_TARGETS_BELOW_PREFERRED_MINIMUM_RR'] : []),
        ...requiredDataFailures.map(item => `REQUIRED_MODEL_DATA_${item.status}:${item.timeframe}`)
    ].filter(warning => {
        if (warning == null) return false;
        const code = String(warning).trim();
        if (!code || code.toUpperCase() === 'NONE') return false;
        if (hasReviewableObjective && staleTargetLabel(code)) return false;
        if (entryProvablyUntouched && staleLifecycleLabel(code)) return false;
        return true;
    }))];
    const rawOriginalRejection = item.original_rejection || item.rejection_code || item.primary_blocker || null;
    const originalRejection = (hasReviewableObjective && staleTargetLabel(rawOriginalRejection))
        || (entryProvablyUntouched && staleLifecycleLabel(rawOriginalRejection))
        ? (hasReviewableObjective && rrBelowPreferred ? 'RR_BELOW_PREFERRED_MINIMUM' : null)
        : rawOriginalRejection;
    const tradeableToday = marketMechanicsTradeableToday({
        direction, entry, stop, objective, supportedTargets: targetRewardRisk,
        currentPrice: current, expectedDailyRange: marketMechanicsExpectedDailyRange(source),
        config: marketMechanicsSelectionConfig(source)
    });
    return {
        opportunity_id: item.opportunity_id || item.id || item.candidate_id || item.execution_poi_id || null,
        source_setup_id: item.source_setup_id || item.strategy_setup?.id || null,
        symbol: normalizeCanonicalMarketSymbol(source.pair || source.symbol || ''),
        direction: direction || null,
        model,
        primary_timeframe: item.timeframe || item.primary_tf || item.setup_timeframe || null,
        formation_first_knowable_time: item.first_actionable_time || item.first_knowable_time || item.formation_time || item.event_time
            || lifecycleMetrics.event_time_utc || null,
        formation_status: manualMarketMechanicsFormationConfirmed(item) ? 'CONFIRMED' : 'INCOMPLETE',
        market_structure_direction: item.market_structure_direction || item.htf_trend || source.market_plan?.htf_trend || null,
        market_plan_direction: source.market_plan?.direction || null,
        market_narrative: source.market_plan?.narrative || null,
        parent_poi: item.market_plan_poi_id || item.parent_poi_id || item.poi_ref || null,
        parent_poi_status: item.market_plan_poi_valid || item.parent_poi_valid || 'UNKNOWN',
        execution_poi: item.execution_poi_id || item.entry_zone_ref || zone.id || null,
        execution_poi_type: item.execution_poi_type || item.entry_zone_source || zone.type || null,
        entry_zone_low: low,
        entry_zone_high: high,
        entry_zone_origin: item.entry_zone_origin || item.entry_zone_source || item.entry_zone_ref || zone.origin || null,
        suggested_entry: entry,
        proposed_stop: stop,
        stop_source: item.stop_source || item.stop_ref || null,
        stop_basis: item.stop_basis_price ?? item.stop_basis ?? null,
        stop_quality_warning: item.stop_quality_warning || (String(item.primary_blocker || item.blocker || '').toUpperCase().includes('STOP') ? item.primary_blocker || item.blocker : null),
        nearby_structural_invalidation_alternatives: item.structural_invalidation_alternatives || item.stop_alternatives || [],
        directional_liquidity_targets: directionalTargets,
        target_sources: item.target_source || item.target_ref || null,
        target_lifecycle: item.target_lifecycle_state || null,
        proposed_objective: objective,
        reward_risk_for_supported_combinations: item.reward_risk_for_supported_combinations || item.risk_reward_combinations || item.rr || null,
        risk_distance: riskDistance,
        supported_target_reward_risk: targetRewardRisk,
        preferred_minimum_rr: preferredMinimumRR,
        rr_policy: structuralFirstRRPolicy ? 'STRUCTURAL_FIRST' : 'PREFERRED_MINIMUM',
        preferred_rr_met: targetRewardRisk.length ? !rrBelowPreferred : null,
        rr_quality_status: rrQualityStatus,
        opposing_structure: item.opposing_structure || item.path_quality?.nearest_opposing_barrier || item.nearest_opposing_barrier || null,
        confluence: item.confluence || item.confluence_refs || item.strategy_confluence || [],
        current_price: current,
        correct_pending_order_side: direction === 'BUY' ? 'BUY_LIMIT' : direction === 'SELL' ? 'SELL_LIMIT' : null,
        pending_side_eligible: side,
        first_entry_touch_after_formation: firstTouch,
        entry_touched: touched,
        entry_consumed: consumed,
        expiry_status: item.expiry_status || (MANUAL_MARKET_MECHANICS_TERMINAL_STATES.has(lifecycle) ? lifecycle : 'ACTIVE'),
        lifecycle_state: lifecycle,
        formation_age_hours: (() => {
            const formed = normalizeTimestampUTC(
                item.first_actionable_time
                || item.first_knowable_time
                || item.formation_time
                || item.event_time
            );
            const asOf = normalizeTimestampUTC(
                source.scan_as_of
                || source.as_of
                || source.scan_as_of_ms
            );
            if (!Number.isFinite(formed) || !Number.isFinite(asOf)) return null;
            return Math.max(0, (asOf - formed) / 3600000);
        })(),
        poi_rejection_reason: (() => {
            // Prefer an explicit qualification field if the caller supplied one.
            const qualification = item.poi_qualification
                || item.market_plan_poi_qualification
                || item.execution_poi_qualification;
            if (qualification) {
                const reasons = Array.isArray(qualification.rejectionReasons)
                    ? qualification.rejectionReasons
                    : Array.isArray(qualification.rejection_reasons)
                        ? qualification.rejection_reasons
                        : [];
                if (reasons.length) return reasons.join('|');
            }
            return null;
        })(),
        recomputed_lifecycle_status: item.lifecycle_classification || item.recomputed_lifecycle_status
            || lifecycleMetrics.lifecycle_classification || lifecycle,
        original_rejection: originalRejection,
        matched_candle_index: lifecycleDiagnostics.execution_event_index ?? item.execution_event_index ?? item.execution_zone_created_index ?? null,
        matched_candle_index_source: lifecycleDiagnostics.execution_event_index_source || null,
        matched_candle_index_timeframe: lifecycleDiagnostics.index_timeframe || null,
        index_mapping_status: lifecycleDiagnostics.execution_event_index_resolved || null,
        chronology_verified_through: lifecycleDiagnostics.verified_through || null,
        chronology_missing_from: lifecycleDiagnostics.missing_from || null,
        chronology_reason: lifecycleDiagnostics.chronology_reason || null,
        chronology_observation_timeframes: lifecycleDiagnostics.observation_timeframes || [],
        first_invalidation: item.first_invalidation || item.invalidation_time || null,
        explicit_expiry_rule: lifecycleDiagnostics.expiry_rule || item.expiry_rule || null,
        expiry_time: lifecycleDiagnostics.expiry_time_utc || item.expiry_time || null,
        objective_delivery_status: item.target_lifecycle_state || lifecycleMetrics.opportunity_freshness || null,
        data_freshness: dataQuality.status || 'UNKNOWN',
        required_data_timeframes: requiredDataTimeframes,
        required_data_failures: requiredDataFailures,
        evidence_refs: [...new Set([...(item.formation_evidence_refs || []), ...(item.evidence_refs || []), item.poi_ref, item.execution_poi_id].filter(Boolean))],
        quality_warnings: warnings,
        pending_limit_geometry_complete: item.pending_limit_geometry_complete || item.geometry_complete || 'UNKNOWN',
        today_viability: (() => {
            const price = Number(item.current_price || source.quote?.price || source.current_price);
            const entry = Number(item.entry ?? item.proposed_entry);
            const tp3 = Number(item.tp3 ?? item.take_profit_3 ?? item.proposed_objective);
            if (![price, entry, tp3].every(Number.isFinite)) return 'UNKNOWN';

            // Required path: current to entry + entry to TP3
            const requiredPath = Math.abs(entry - price) + Math.abs(tp3 - entry);

            // Today's realized volatility (Daily High - Daily Low from source)
            const dailyData = source.history?.['1D'] || [];
            const todayCandle = dailyData[dailyData.length - 1];
            let todayRange = 0;
            if (todayCandle) {
                todayRange = Math.abs(Number(todayCandle.h) - Number(todayCandle.l));
            }

            // If we don't have daily range, fallback to a generous 2.5x current 4H ATR
            // (which represents a strong trend day for Gold).
            const atr4h = Number(source.market_context?.volatility?.atr_4h) || 20;
            const expectedDayRange = todayRange > 0 ? todayRange : (atr4h * 2.5);

            return requiredPath <= expectedDayRange ? 'HIGH' : 'LOW';
        })(),
        structural_stop_valid: item.structural_stop_valid ?? item.stop_valid ?? 'UNKNOWN',
        structural_target_valid: item.structural_target_valid ?? item.target_valid ?? 'UNKNOWN',
        ...tradeableToday,
        manual_authority: 'DEEPSEEK_REVIEW_ONLY',
        deterministic_live_authority: (() => {
            const authority = item.CANDIDATE_AUTHORITY || item.candidate_authority;
            return String(authority || '').toUpperCase() === 'LIVE' ? 'LIVE' : 'DIAGNOSTIC_ONLY';
        })()
    };
}

function manualMarketMechanicsOpportunityCompleteness(row = {}) {
    let score = 0;
    if (String(row.deterministic_live_authority || '').toUpperCase() === 'LIVE') score += 8;
    if (String(row.entry_touched || '').toUpperCase() === 'NO') score += 4;
    else if (String(row.entry_touched || '').toUpperCase() === 'YES') score += 2;
    if (String(row.entry_consumed || '').toUpperCase() === 'NO') score += 2;
    if (Number.isFinite(Number(row.proposed_objective))) score += 2;
    if (String(row.pending_limit_geometry_complete || '').toUpperCase() === 'YES') score += 2;
    if (String(row.rr_policy || '').toUpperCase() === 'STRUCTURAL_FIRST') score += 1;
    if ((row.quality_warnings || []).includes('ENTRY_TOUCH_CHRONOLOGY_UNKNOWN')) score -= 4;
    return score;
}

function buildManualMarketMechanicsOpportunityShortlist(source = {}, currentPrice = null) {
    const seen = new Set();
    const rows = [];
    const planPoiEvaluations = (source.market_plan?.poi_evaluations)
        || (source.market_context?.market_plan?.poi_evaluations)
        || (source.market_mechanics?.plan?.poi_evaluations)
        || [];
    const poiRejectionBySetupId = new Map();
    for (const poi of planPoiEvaluations) {
        const setupId = poi?.poi_id || poi?.poiId || poi?.id;
        const reason = poi?.rejection_reason;
        if (setupId && reason && String(reason).toUpperCase() !== 'NONE') {
            poiRejectionBySetupId.set(String(setupId), String(reason));
        }
    }
    for (const item of manualMarketMechanicsSources(source)) {
        if (!item) continue;
        const row = manualMarketMechanicsOpportunityRecord(item, source, currentPrice);
        // Geometry and lifecycle belong to the exact execution opportunity.
        // A shared parent setup/event is supporting evidence, not identity.
        const identity = row.opportunity_id
            || [row.source_setup_id, row.execution_poi, row.entry_zone_low, row.entry_zone_high].join('|');
        if (!identity || seen.has(identity)) continue;
        // Canonical model states come first. A less complete duplicate cannot
        // revive their terminal result or overwrite verified chronology.
        seen.add(identity);
        if (!row.opportunity_id || manualMarketMechanicsTerminal(item)
            || !manualMarketMechanicsFormationConfirmed(item) || row.pending_side_eligible === 'NO') continue;

        // Manual review requires a constructed candidate; CANDIDATE_NOT_CONSTRUCTED
        // means the engine could not build geometry, so there is nothing to review.
        if (String(row.original_rejection || '').toUpperCase() === 'CANDIDATE_NOT_CONSTRUCTED') continue;

        // A candidate still waiting on qualification is not a completed opportunity.
        const shortlistLifecycle = String(row.lifecycle_state || '').toUpperCase();
        if (['WAITING_FOR_QUALIFICATION', 'WAITING_FOR_CONFIRMATION', 'FORMING', 'PENDING_CANDIDATE'].includes(shortlistLifecycle)) continue;

        // Reject if the selected execution POI was rejected by the plan for being
        // outside the active swing range or malformed.
        const executionPoiId = String(row.execution_poi || '').toUpperCase();
        if (executionPoiId && poiRejectionBySetupId.has(executionPoiId)) continue;

        // Intraday manual review only retains opportunities formed within the
        // last 48 hours. Stale zones are historical, not current opportunities.
        if (Number.isFinite(row.formation_age_hours) && row.formation_age_hours > 48) continue;

        rows.push(row);
    }
    // The same execution zone can arrive once as a canonical forming state and
    // again as a raw candidate. Reviewing both inflates the shortlist and lets
    // an UNKNOWN-touch raw duplicate veto the verified forming row.
    const uniqueByGeometry = new Map();
    for (const row of rows) {
        const geometryKey = [row.source_setup_id || row.opportunity_id, row.direction, row.model,
            row.execution_poi, row.entry_zone_low, row.entry_zone_high].join('|');
        const previous = uniqueByGeometry.get(geometryKey);
        if (!previous || manualMarketMechanicsOpportunityCompleteness(row)
            > manualMarketMechanicsOpportunityCompleteness(previous)) {
            uniqueByGeometry.set(geometryKey, row);
        }
    }
    return [...uniqueByGeometry.values()];
}

// Validates a manually returned DeepSeek decision against the same active
// shortlist that was printed in the packet.  This is a safety boundary only;
// it never places an order or changes deterministic Market Mechanics state.
function validateManualMarketMechanicsDecision(decision = {}, replay = {}) {
    const issues = [];
    const warnings = [];
    const add = code => { if (!issues.includes(code)) issues.push(code); };
    const warn = code => { if (!warnings.includes(code)) warnings.push(code); };
    if (typeof decision === 'string') {
        decision = parseRawCandleAIActionResponse(decision, {
            symbol: replay.pair || replay.symbol || replay.quote?.symbol || replay.quote?.symbol_metadata?.symbol
        });
    }
    const targetNormalization = normalizePendingLimitTargetOrder(
        decision && typeof decision === 'object' ? decision : {},
        decision?.action || decision?.ACTION || decision?.direction || null
    );
    decision = targetNormalization.decision;
    if (targetNormalization.changed) warn('TARGET_ORDER_AUTO_SORTED');
    const action = String(decision.action || decision.ACTION || decision.direction || '').toUpperCase();
    const opportunities = Array.isArray(replay.manual_analysis_opportunities)
        ? replay.manual_analysis_opportunities
        : buildManualMarketMechanicsOpportunityShortlist(replay, replay.quote?.price ?? replay.current_price);
    if (action === 'NO_TRADE') return { valid: true, execution_allowed: false, issues: [], warnings: [], action, opportunities_count: opportunities.length };
    if (!['BUY_LIMIT', 'SELL_LIMIT'].includes(action)) add('MANUAL_ACTION_INVALID');
    const opportunityId = decision.opportunity_id || decision.OPPORTUNITY_ID
        || String(decision.reason || decision.REASON || '').match(/OPPORTUNITY_ID=([^\s,;]+)/i)?.[1];
    const opportunity = opportunities.find(item => String(item.opportunity_id) === String(opportunityId));
    if (!opportunity) add('MANUAL_ACTIVE_OPPORTUNITY_NOT_FOUND');
    if (opportunity && opportunity.correct_pending_order_side !== action) add('MANUAL_PENDING_SIDE_INVALID');
    const entry = manualMarketMechanicsNumber(decision.entry, decision.ENTRY, decision.price);
    const stop = manualMarketMechanicsNumber(decision.stop_loss, decision.STOP_LOSS, decision.stop);
    const tp1 = manualMarketMechanicsNumber(decision.tp1, decision.TP1, decision.target);
    const tp2 = manualMarketMechanicsNumber(decision.tp2, decision.TP2);
    const tp3 = manualMarketMechanicsNumber(decision.tp3, decision.TP3);
    if (!opportunity || entry == null || opportunity.entry_zone_low == null || opportunity.entry_zone_high == null
        || entry < opportunity.entry_zone_low || entry > opportunity.entry_zone_high) add('MANUAL_ENTRY_OUTSIDE_EVIDENCED_ZONE');
    if (opportunity && String(opportunity.entry_touched).toUpperCase() !== 'NO') add('MANUAL_ENTRY_TOUCH_NOT_VERIFIABLY_UNTOUCHED');
    if (opportunity && String(opportunity.entry_consumed).toUpperCase() === 'YES') add('MANUAL_ENTRY_CONSUMED');
    if (opportunity && String(opportunity.expiry_status).toUpperCase() !== 'ACTIVE') add('MANUAL_OPPORTUNITY_TERMINAL');
    if (opportunity && Array.isArray(opportunity.required_data_failures) && opportunity.required_data_failures.length) add('MANUAL_REQUIRED_MODEL_DATA_NOT_FRESH');
    if (stop == null || !opportunity?.stop_source) add('MANUAL_STRUCTURAL_STOP_EVIDENCE_REQUIRED');
    if (tp1 == null || !Array.isArray(opportunity?.directional_liquidity_targets) || !opportunity.directional_liquidity_targets.length) add('MANUAL_STRUCTURAL_TARGET_EVIDENCE_REQUIRED');
    if (opportunity && action === 'BUY_LIMIT' && !(entry < opportunity.current_price && stop < entry && tp1 > entry)) add('MANUAL_BUY_GEOMETRY_INVALID');
    if (opportunity && action === 'SELL_LIMIT' && !(entry > opportunity.current_price && stop > entry && tp1 < entry)) add('MANUAL_SELL_GEOMETRY_INVALID');
    const risk = entry != null && stop != null ? Math.abs(stop - entry) : null;
    const reward = opportunity && entry != null && tp1 != null
        ? action === 'BUY_LIMIT' ? tp1 - entry : action === 'SELL_LIMIT' ? entry - tp1 : null
        : null;
    const calculatedRR = risk > 0 && reward > 0 ? reward / risk : null;
    const minimumRR = manualMarketMechanicsNumber(opportunity?.preferred_minimum_rr);
    if (calculatedRR != null && minimumRR != null && calculatedRR < minimumRR) warn('MANUAL_RR_BELOW_PREFERRED_MINIMUM');
    const reason = String(decision.reason || decision.REASON || '');
    if (/insufficient\s+for\s+authorization|cannot\s+authorize|not\s+authorized|no\s+defensible\s+(?:trade|geometry)|unacceptable\s+(?:risk|path|geometry)|should\s+be\s+rejected/i.test(reason)) {
        add('MANUAL_TRADE_REASON_SELF_REJECTS');
    }
    return {
        valid: issues.length === 0, execution_allowed: false, issues, warnings, action,
        opportunity: opportunity || null, opportunities_count: opportunities.length,
        calculated_risk_reward: calculatedRR, preferred_minimum_rr: minimumRR,
        normalized_decision: { ...decision, action, tp1, tp2, tp3 },
        target_order_normalized: targetNormalization.changed
    };
}

function countRawLegacyDiagnosticCandidates(lines = []) {
    const ids = new Set();
    for (const line of lines) {
        const text = String(line || '');
        if (!/^(HP_ZONE:|CURRENT_OPPORTUNITY:)/.test(text)) continue;
        const refs = [
            text.match(/FVG_C1=([^\s]+)/)?.[1],
            text.match(/FVG_C2=([^\s]+)/)?.[1],
            text.match(/FVG_C3=([^\s]+)/)?.[1]
        ].filter(Boolean);
        ids.add(refs.length ? refs.join('|') : text);
    }
    return ids.size;
}

function countDiagnosticCandidateRecords(records = []) {
    const ids = new Set();
    for (const record of Array.isArray(records) ? records : []) {
        const id = record?.candidate_id || record?.id || record?.opportunity_id || record?.CANDIDATE_ID;
        ids.add(id || JSON.stringify(record));
    }
    return ids.size;
}

function rawTextPacketTimestamp(value) {
    const numeric = Number(value);
    return Number.isFinite(numeric) && String(value).trim() !== ''
        ? numeric
        : Date.parse(value);
}

function rawTextPacketPrecision(symbol, metadata = {}, currentPrice = null) {
    const assetClass = String(metadata.asset_class || getAssetClass(symbol)).toUpperCase();
    if (assetClass === 'FOREX') return 5;
    if (assetClass === 'EQUITY' || assetClass === 'INDEX') return 2;
    if (assetClass === 'CRYPTO') {
        const price = Math.abs(Number(currentPrice));
        if (price >= 100) return 2;
        if (price >= 1) return 4;
        if (price >= 0.01) return 6;
        return 8;
    }
    const explicit = Number(metadata.price_precision);
    if (Number.isInteger(explicit) && explicit >= 0 && explicit <= 12) return explicit;
    return 2;
}

function rawTextPacketClosedCandles(source = {}, timeframe, asOfMs = Date.now()) {
    const duration = TIMEFRAME_MS[timeframe] || 60 * 60000;
    const values = Array.isArray(source.history?.[timeframe]) ? source.history[timeframe] : [];
    const timestampSemantics = feedTimestampSemantics(values, source.feed_alignment?.[timeframe] || source.feed_alignment || null);
    return values
        .filter(candle => {
            if (!candle) return false;
            const timestamp = rawTextPacketTimestamp(candle.t ?? candle.time ?? candle.timestamp);
            if (candle.is_forming === true || candle.forming === true) return false;
            if (candle.is_closed === false || candle.closed === false) return false;
            if (!Number.isFinite(timestamp)) return candle.is_closed === true || candle.closed === true;
            return candleIsClosedAtEvaluation(candle, timeframe, asOfMs, timestampSemantics);
        })
        .filter(candle => [candle.o, candle.h, candle.l, candle.c].every(value => Number.isFinite(Number(value))))
        .sort((left, right) => rawTextPacketTimestamp(left.t) - rawTextPacketTimestamp(right.t));
}

function rawTextPacketFormatNumber(value, precision) {
    const number = Number(value);
    return Number.isFinite(number) ? number.toFixed(precision) : '';
}

function rawTextPacketOptionalNumber(value, precision) {
    return value == null || !Number.isFinite(Number(value)) ? 'NA' : Number(value).toFixed(precision);
}

function buildRawTextTimeframeRoleAudit(blocks = [], precision = 2) {
    const daily = blocks.find(block => block.timeframe === '1D');
    let dailyBias = 'NEUTRAL';
    let dailyEvidence = 'MIXED_OR_INSUFFICIENT_STRUCTURE';
    let dailyLevels = '';
    if (daily?.candles?.length) {
        const state = confirmedStructuralState(daily.candles, 2);
        dailyBias = ['BULLISH', 'BEARISH'].includes(state.state) ? state.state : 'NEUTRAL';
        dailyEvidence = dailyBias === 'NEUTRAL' ? 'MIXED_OR_INSUFFICIENT_STRUCTURE' : 'CONFIRMED_SWING_SEQUENCE';
        const latestHigh = Number(state.latest_high?.p);
        const latestLow = Number(state.latest_low?.p);
        if (Number.isFinite(latestHigh) || Number.isFinite(latestLow)) {
            dailyLevels = [
                Number.isFinite(latestHigh) ? 'LATEST_HIGH=' + rawTextPacketFormatNumber(latestHigh, precision) : '',
                Number.isFinite(latestLow) ? 'LATEST_LOW=' + rawTextPacketFormatNumber(latestLow, precision) : ''
            ].filter(Boolean).join(' ');
        }
    }
    return {
        daily_bias: dailyBias,
        daily_evidence: dailyEvidence,
        lines: [
            '=== TIMEFRAME ROLES ===',
            '1D_ROLE=DIRECTIONAL_BIAS_ONLY MACRO_1D_BIAS=' + dailyBias + ' EVIDENCE=' + dailyEvidence + (dailyLevels ? ' ' + dailyLevels : ''),
            '4H_ROLE=PRIMARY_SETUP',
            '1H_ROLE=PRIMARY_SETUP_OR_REFINEMENT',
            '15M_ROLE=EXECUTION_CONFIRMATION_OR_REFINEMENT_ONLY',
            '5M_ROLE=EXECUTION_TIMING_ONLY',
            '1M_ROLE=EXECUTION_TIMING_ONLY_WHEN_AVAILABLE'
        ]
    };
}

function detectRawTextFvgs(candles = [], timeframe = '') {
    const ordered = [...candles]
        .filter(candle => candle && [candle.h, candle.l].every(value => Number.isFinite(Number(value))))
        .sort((left, right) => rawTextPacketTimestamp(left.t ?? left.time ?? left.timestamp) - rawTextPacketTimestamp(right.t ?? right.time ?? right.timestamp));
    const results = [];
    for (let index = 0; index <= ordered.length - 3; index += 1) {
        const c1 = ordered[index];
        const c2 = ordered[index + 1];
        const c3 = ordered[index + 2];
        const later = ordered.slice(index + 3);
        const bullish = Number(c1.h) < Number(c3.l);
        const bearish = Number(c1.l) > Number(c3.h);
        if (!bullish && !bearish) continue;
        const lower = bullish ? Number(c1.h) : Number(c3.h);
        const upper = bullish ? Number(c3.l) : Number(c1.l);
        const formationLow = Math.min(Number(c1.l), Number(c2.l), Number(c3.l));
        const formationHigh = Math.max(Number(c1.h), Number(c2.h), Number(c3.h));
        const laterLows = later.map(candle => Number(candle.l));
        const laterHighs = later.map(candle => Number(candle.h));
        const minLaterLow = laterLows.length ? Math.min(...laterLows) : null;
        const maxLaterHigh = laterHighs.length ? Math.max(...laterHighs) : null;
        let status = 'UNTOUCHED';
        let remainingLower = null;
        let remainingUpper = null;
        if (bullish) {
            if (minLaterLow == null || minLaterLow > upper) status = 'UNTOUCHED';
            else if (minLaterLow > lower) {
                status = 'PARTIAL';
                remainingLower = lower;
                remainingUpper = minLaterLow;
            } else status = 'FULLY_TRAVERSED';
        } else if (maxLaterHigh == null || maxLaterHigh < lower) {
            status = 'UNTOUCHED';
        } else if (maxLaterHigh < upper) {
            status = 'PARTIAL';
            remainingLower = maxLaterHigh;
            remainingUpper = upper;
        } else status = 'FULLY_TRAVERSED';
        results.push({
            timeframe: String(timeframe).toUpperCase(),
            type: bullish ? 'BULLISH' : 'BEARISH',
            c1: c1.t ?? c1.time ?? c1.timestamp,
            c2: c2.t ?? c2.time ?? c2.timestamp,
            c3: c3.t ?? c3.time ?? c3.timestamp,
            lower,
            upper,
            formation_low: formationLow,
            formation_high: formationHigh,
            status,
            min_later_low: minLaterLow,
            max_later_high: maxLaterHigh,
            remaining_lower: remainingLower,
            remaining_upper: remainingUpper,
            formation_index: index
        });
    }
    return results;
}

function rawTextPacketRoundPrice(value, precision) {
    const number = Number(value);
    if (!Number.isFinite(number)) return null;
    const factor = 10 ** precision;
    const adjusted = Math.round((number + (Number.EPSILON * Math.max(1, Math.abs(number)))) * factor) / factor;
    return Number(adjusted.toFixed(precision));
}

function buildRawTextFvgPendingCandidate(fvg, currentPrice, precision = 2) {
    if (!fvg || !['BULLISH', 'BEARISH'].includes(fvg.type) || !['UNTOUCHED', 'PARTIAL'].includes(fvg.status)) return null;
    const price = Number(currentPrice);
    const lower = fvg.status === 'PARTIAL' ? Number(fvg.remaining_lower) : Number(fvg.lower);
    const upper = fvg.status === 'PARTIAL' ? Number(fvg.remaining_upper) : Number(fvg.upper);
    if (![price, lower, upper, fvg.formation_low, fvg.formation_high].every(Number.isFinite) || lower >= upper) return null;
    const increment = 10 ** -precision;
    const entry = rawTextPacketRoundPrice((lower + upper) / 2, precision);
    const action = fvg.type === 'BULLISH' ? 'BUY_LIMIT' : 'SELL_LIMIT';
    const stopLoss = rawTextPacketRoundPrice(
        fvg.type === 'BULLISH' ? Number(fvg.formation_low) - increment : Number(fvg.formation_high) + increment,
        precision
    );
    if (fvg.type === 'BULLISH' && !(upper < price && entry < price && stopLoss < entry)) return null;
    if (fvg.type === 'BEARISH' && !(lower > price && entry > price && stopLoss > entry)) return null;
    const risk = rawTextPacketRoundPrice(fvg.type === 'BULLISH' ? entry - stopLoss : stopLoss - entry, precision);
    if (!(risk > 0)) return null;
    const tp1 = rawTextPacketRoundPrice(fvg.type === 'BULLISH' ? entry + risk : entry - risk, precision);
    const tp2 = rawTextPacketRoundPrice(fvg.type === 'BULLISH' ? entry + (risk * 2) : entry - (risk * 2), precision);
    const tp3 = rawTextPacketRoundPrice(fvg.type === 'BULLISH' ? entry + (risk * 3) : entry - (risk * 3), precision);
    const ordered = fvg.type === 'BULLISH'
        ? stopLoss < entry && entry < tp1 && tp1 < tp2 && tp2 < tp3
        : stopLoss > entry && entry > tp1 && tp1 > tp2 && tp2 > tp3;
    if (!ordered) return null;
    return { action, entry, stop_loss: stopLoss, tp1, tp2, tp3, risk };
}

function rawTextAuditTimestamp(value) {
    const timestamp = rawTextPacketTimestamp(value);
    return Number.isFinite(timestamp) ? new Date(timestamp).toISOString() : '';
}

function buildRawTextDeterministicCrtAudit(blocks = [], pairLocal = pair, symbolMetadata = {}, precision = 2) {
    const records = [];
    for (const block of blocks) {
        const events = detectCRTEvents(block.candles, block.timeframe, pairLocal, symbolMetadata);
        for (const event of events) {
            const firstKnowable = event.first_knowable_time ?? event.confirmation_time ?? event.reclaim_time;
            const firstKnowableMs = rawTextPacketTimestamp(firstKnowable);
            const status = event.invalidated ? 'INVALIDATED' : event.detected ? 'VALID' : String(event.freshness || 'UNVERIFIED').toUpperCase();
            const reference = [
                'CRT',
                String(block.timeframe).toUpperCase(),
                String(event.direction || event.type || 'UNKNOWN').toUpperCase(),
                Number.isFinite(firstKnowableMs) ? firstKnowableMs : 'UNKNOWN',
                Number.isFinite(Number(event.reference_bar_index)) ? event.reference_bar_index : 'NA'
            ].join(':');
            records.push({
                ref: reference,
                timeframe: String(block.timeframe).toUpperCase(),
                direction: event.direction || event.type,
                range_low: Number(event.range_low),
                range_high: Number(event.range_high),
                first_knowable_ms: firstKnowableMs,
                first_knowable: rawTextAuditTimestamp(firstKnowable),
                status,
                detected: event.detected === true,
                event
            });
        }
    }
    const lines = records.map(record => {
        const event = record.event;
        return [
            'CRT: TF=' + record.timeframe.toLowerCase(),
            'TYPE=' + String(record.direction || 'UNKNOWN').toUpperCase(),
            'RANGE=' + rawTextPacketFormatNumber(record.range_low, precision) + '-' + rawTextPacketFormatNumber(record.range_high, precision),
            'SWEEP=' + String(event.manipulation_side || 'UNKNOWN').toUpperCase(),
            'SWEEP_PRICE=' + rawTextPacketFormatNumber(event.sweep_extreme, precision),
            'CONFIRM=' + rawTextAuditTimestamp(event.confirmation_time || event.reclaim_time),
            'STATUS=' + record.status,
            'FIRST_KNOWABLE=' + record.first_knowable,
            'CRT_REF=' + record.ref
        ].join(' ');
    });
    return { records, lines: lines.length ? lines : ['NONE'] };
}

function buildRawTextDeterministicMsnrAudit(blocks = [], currentPrice = null, pairLocal = pair, symbolMetadata = {}, precision = 2) {
    const records = [];
    const price = Number.isFinite(Number(currentPrice)) ? Number(currentPrice) : 0;
    for (const block of blocks) {
        const result = calculateMSNR(block.candles, price, block.timeframe, pairLocal, symbolMetadata);
        for (const level of result.structural_levels || []) {
            if (level.origin !== 'STRUCTURAL_MSNR' || !Number.isFinite(Number(level.zone_low)) || !Number.isFinite(Number(level.zone_high))) continue;
            const firstKnowable = level.first_knowable_time ?? level.confirmation_time ?? level.event_time ?? level.formation_time;
            const firstKnowableMs = rawTextPacketTimestamp(firstKnowable);
            const status = level.invalidated
                ? 'INVALIDATED'
                : level.freshness === 'MITIGATED'
                    ? 'MITIGATED'
                    : level.primary_eligible
                        ? 'VALID'
                        : String(level.freshness || 'UNVERIFIED').toUpperCase();
            const reference = [
                'MSNR',
                String(block.timeframe).toUpperCase(),
                String(level.direction || 'UNKNOWN').toUpperCase(),
                Number.isFinite(firstKnowableMs) ? firstKnowableMs : 'UNKNOWN',
                Number.isFinite(Number(level.source_candle_index)) ? level.source_candle_index : 'NA'
            ].join(':');
            records.push({
                ref: reference,
                timeframe: String(block.timeframe).toUpperCase(),
                direction: level.direction,
                zone_low: Number(level.zone_low),
                zone_high: Number(level.zone_high),
                first_knowable_ms: firstKnowableMs,
                first_knowable: rawTextAuditTimestamp(firstKnowable),
                status,
                level
            });
        }
    }
    const lines = records.map(record => {
        const level = record.level;
        const parts = [
            'MSNR: TF=' + record.timeframe.toLowerCase(),
            'TYPE=' + (record.direction === 'BUY' ? 'BULLISH' : record.direction === 'SELL' ? 'BEARISH' : 'UNKNOWN'),
            'ZONE=' + rawTextPacketFormatNumber(record.zone_low, precision) + '-' + rawTextPacketFormatNumber(record.zone_high, precision),
            'STATUS=' + record.status,
            'CONFIRM=' + rawTextAuditTimestamp(level.confirmation_time || level.event_time),
            'FIRST_KNOWABLE=' + record.first_knowable,
            'MSNR_REF=' + record.ref,
            'ROLE=' + String(level.role || 'UNKNOWN')
        ];
        if (level.break_time != null) parts.push('BREAK=' + rawTextAuditTimestamp(level.break_time));
        if (level.retest_time != null) parts.push('RETEST=' + rawTextAuditTimestamp(level.retest_time));
        return parts.join(' ');
    });
    return { records, lines: lines.length ? lines : ['NONE'] };
}

function rawTextIntervalsOverlap(firstLow, firstHigh, secondLow, secondHigh) {
    return [firstLow, firstHigh, secondLow, secondHigh].every(Number.isFinite)
        && Math.max(firstLow, secondLow) <= Math.min(firstHigh, secondHigh);
}

function rawTextFvgConfluence(fvg, candidate, crtRecords = [], msnrRecords = []) {
    if (!fvg || !candidate) return { crt: [], msnr: [] };
    const direction = candidate.action === 'BUY_LIMIT' ? 'BUY' : candidate.action === 'SELL_LIMIT' ? 'SELL' : null;
    const firstKnowableMs = rawTextPacketTimestamp(fvg.c3);
    const fvgLow = fvg.status === 'PARTIAL' ? Number(fvg.remaining_lower) : Number(fvg.lower);
    const fvgHigh = fvg.status === 'PARTIAL' ? Number(fvg.remaining_upper) : Number(fvg.upper);
    const crt = crtRecords.filter(record => (
        direction && record.detected && record.status === 'VALID' && record.direction === direction
        && Number.isFinite(firstKnowableMs) && Number.isFinite(record.first_knowable_ms) && record.first_knowable_ms <= firstKnowableMs
        && rawTextIntervalsOverlap(fvgLow, fvgHigh, record.range_low, record.range_high)
    ));
    const msnr = msnrRecords.filter(record => (
        direction && record.status === 'VALID' && record.direction === direction
        && Number.isFinite(firstKnowableMs) && Number.isFinite(record.first_knowable_ms) && record.first_knowable_ms <= firstKnowableMs
        && rawTextIntervalsOverlap(fvgLow, fvgHigh, record.zone_low, record.zone_high)
    ));
    return { crt, msnr };
}

function buildRawTextCrossTimeframeDeliveryCandles(fvg, primaryBlock = {}, blocks = [], asOfMs = null) {
    const formationMs = rawTextPacketTimestamp(fvg?.c3);
    const primaryTimeframe = String(primaryBlock?.timeframe || fvg?.timeframe || '').toUpperCase();
    const allowed = primaryTimeframe === '4H' || primaryTimeframe === '1H'
        ? [primaryTimeframe, '1H', '15M', '5M']
        : [primaryTimeframe];
    const result = [];
    for (const block of blocks) {
        if (!allowed.includes(String(block.timeframe).toUpperCase())) continue;
        const ordered = [...(block.candles || [])]
            .filter(candle => candle && candle.is_forming !== true && candle.forming !== true && candle.is_closed !== false && candle.closed !== false)
            .filter(candle => [candle.h, candle.l].every(value => Number.isFinite(Number(value))))
            .filter(candle => {
                const timestamp = rawTextPacketTimestamp(candle.t ?? candle.time ?? candle.timestamp);
                return Number.isFinite(timestamp)
                    && (!Number.isFinite(formationMs) || timestamp > formationMs)
                    && (!Number.isFinite(asOfMs) || timestamp <= asOfMs);
            });
        result.push(...ordered);
    }
    return result.sort((left, right) => rawTextPacketTimestamp(left.t ?? left.time ?? left.timestamp) - rawTextPacketTimestamp(right.t ?? right.time ?? right.timestamp));
}

function buildRawTextFvgDeliveryAssessment(fvg, candidate, candles = [], currentPrice = null, precision = 2, timelineCandles = null) {
    const assessment = {
        entry_state: 'PENDING_UNFILLED',
        delivery_status: 'FRESH',
        pre_entry_max_high: null,
        pre_entry_min_low: null,
        pre_entry_progress: null,
        recommendation_eligible: true
    };
    if (!fvg || !candidate) return assessment;
    const ordered = (timelineCandles || [...candles]).filter(candle => (
        candle && candle.is_forming !== true && candle.forming !== true && candle.is_closed !== false && candle.closed !== false
    )).sort((left, right) => (
        rawTextPacketTimestamp(left?.t ?? left?.time ?? left?.timestamp) -
        rawTextPacketTimestamp(right?.t ?? right?.time ?? right?.timestamp)
    ));
    const formationMs = rawTextPacketTimestamp(fvg.c3);
    const hasFormationTime = Number.isFinite(formationMs);
    const formationEnd = Number.isInteger(fvg.formation_index) ? fvg.formation_index + 3 : 0;
    const subsequent = timelineCandles || hasFormationTime
        ? ordered.filter(candle => !hasFormationTime || rawTextPacketTimestamp(candle.t ?? candle.time ?? candle.timestamp) > formationMs)
        : ordered.slice(formationEnd);
    let preEntryMaxHigh = null;
    let preEntryMinLow = null;
    for (const candle of subsequent) {
        const high = Number(candle?.h);
        const low = Number(candle?.l);
        if (!Number.isFinite(high) || !Number.isFinite(low)) continue;
        const entryTouched = fvg.type === 'BULLISH'
            ? low <= Number(candidate.entry)
            : high >= Number(candidate.entry);
        if (entryTouched) {
            assessment.entry_state = 'ENTRY_TOUCHED';
            assessment.recommendation_eligible = false;
            break;
        }
        if (fvg.type === 'BULLISH') preEntryMaxHigh = preEntryMaxHigh == null ? high : Math.max(preEntryMaxHigh, high);
        else preEntryMinLow = preEntryMinLow == null ? low : Math.min(preEntryMinLow, low);
    }
    assessment.pre_entry_max_high = preEntryMaxHigh;
    assessment.pre_entry_min_low = preEntryMinLow;
    if (assessment.entry_state === 'PENDING_UNFILLED' || assessment.entry_state === 'ENTRY_TOUCHED') {
        if (fvg.type === 'BULLISH') {
            if (preEntryMaxHigh != null && preEntryMaxHigh >= candidate.tp3) assessment.delivery_status = 'EXPIRED_TP3';
            else if (preEntryMaxHigh != null && preEntryMaxHigh >= candidate.tp2) assessment.delivery_status = 'STALE_TP2';
            else if (preEntryMaxHigh != null && preEntryMaxHigh >= candidate.tp1) assessment.delivery_status = 'DELIVERED_TP1';
        } else if (preEntryMinLow != null) {
            if (preEntryMinLow <= candidate.tp3) assessment.delivery_status = 'EXPIRED_TP3';
            else if (preEntryMinLow <= candidate.tp2) assessment.delivery_status = 'STALE_TP2';
            else if (preEntryMinLow <= candidate.tp1) assessment.delivery_status = 'DELIVERED_TP1';
        }
        if (['STALE_TP2', 'EXPIRED_TP3'].includes(assessment.delivery_status)) assessment.recommendation_eligible = false;
    }
    const price = Number(currentPrice);
    const path = fvg.type === 'BULLISH'
        ? Number(candidate.tp3) - Number(candidate.entry)
        : Number(candidate.entry) - Number(candidate.tp3);
    const directionalProgress = fvg.type === 'BULLISH'
        ? price - Number(candidate.entry)
        : Number(candidate.entry) - price;
    if (Number.isFinite(price) && path > 0 && Number.isFinite(directionalProgress)) {
        assessment.pre_entry_progress = rawTextPacketRoundPrice(Math.min(100, Math.max(0, (directionalProgress / path) * 100)), 2);
    }
    return assessment;
}

const RAW_TEXT_CURRENT_OPPORTUNITY_ATR_THRESHOLDS = Object.freeze({ NEAR: 0.75, REACHABLE: 1.5, FAR: 2.0 });

function rawTextDistanceToInterval(price, low, high) {
    const value = Number(price);
    const lower = Number(low);
    const upper = Number(high);
    if (![value, lower, upper].every(Number.isFinite)) return null;
    if (value < lower) return lower - value;
    if (value > upper) return value - upper;
    return 0;
}

function rawTextPrimaryApproachState(fvg, blocks = [], asOfMs = null, precision = 2) {
    const primaryLow = fvg?.status === 'PARTIAL' ? Number(fvg.remaining_lower) : Number(fvg?.lower);
    const primaryHigh = fvg?.status === 'PARTIAL' ? Number(fvg.remaining_upper) : Number(fvg?.upper);
    const formationMs = rawTextPacketTimestamp(fvg?.c3);
    const candles = blocks.filter(block => ['15M', '5M'].includes(String(block.timeframe).toUpperCase()))
        .flatMap(block => (block.candles || []).filter(candle => {
            const timestamp = rawTextPacketTimestamp(candle?.t ?? candle?.time ?? candle?.timestamp);
            return candle && candle.is_forming !== true && candle.forming !== true && candle.is_closed !== false && candle.closed !== false
                && Number.isFinite(Number(candle.c))
                && Number.isFinite(timestamp)
                && (!Number.isFinite(formationMs) || timestamp > formationMs)
                && (!Number.isFinite(asOfMs) || timestamp <= asOfMs);
        }))
        .sort((left, right) => rawTextPacketTimestamp(left.t ?? left.time ?? left.timestamp) - rawTextPacketTimestamp(right.t ?? right.time ?? right.timestamp))
        .slice(-8);
    if (candles.length < 4) return 'NEUTRAL';
    const distances = candles.map(candle => rawTextDistanceToInterval(candle.c, primaryLow, primaryHigh)).filter(Number.isFinite);
    if (distances.length < 4) return 'NEUTRAL';
    const split = Math.floor(distances.length / 2);
    const earlier = distances.slice(0, split).reduce((sum, value) => sum + value, 0) / split;
    const later = distances.slice(split).reduce((sum, value) => sum + value, 0) / (distances.length - split);
    const tolerance = 10 ** -precision;
    if (later < earlier - tolerance) return 'APPROACHING';
    if (later > earlier + tolerance) return 'MOVING_AWAY';
    return 'NEUTRAL';
}

function buildRawTextCurrentOpportunityAssessment(record = {}, blocks = [], currentPrice = null, marketContext = {}, asOfMs = null, precision = 2) {
    const { fvg, candidate, delivery, block } = record;
    const direction = candidate?.action === 'BUY_LIMIT' ? 'BUY' : 'SELL';
    const primaryAtr = Number(block?.timeframe === '4H' ? marketContext.atr_4h : marketContext.atr_1h);
    const entryDistance = Math.abs(Number(candidate?.entry) - Number(currentPrice));
    const entryDistanceAtr = primaryAtr > 0 ? entryDistance / primaryAtr : null;
    const distanceClass = entryDistanceAtr == null
        ? 'UNKNOWN'
        : entryDistanceAtr <= RAW_TEXT_CURRENT_OPPORTUNITY_ATR_THRESHOLDS.NEAR ? 'NEAR'
            : entryDistanceAtr <= RAW_TEXT_CURRENT_OPPORTUNITY_ATR_THRESHOLDS.REACHABLE ? 'REACHABLE'
                : entryDistanceAtr <= RAW_TEXT_CURRENT_OPPORTUNITY_ATR_THRESHOLDS.FAR ? 'FAR' : 'TOO_FAR';
    const approachState = rawTextPrimaryApproachState(fvg, blocks, asOfMs, precision);
    const formationMs = rawTextPacketTimestamp(fvg?.c3);
    const latestTimestamp = Number.isFinite(asOfMs) ? asOfMs : Math.max(...blocks.flatMap(item => (item.candles || []).map(candle => rawTextPacketTimestamp(candle.t ?? candle.time ?? candle.timestamp))).filter(Number.isFinite));
    const primaryBarHours = block?.timeframe === '4H' ? 4 : 1;
    const ageHours = Number.isFinite(formationMs) && Number.isFinite(latestTimestamp) ? Math.max(0, (latestTimestamp - formationMs) / 3600000) : null;
    const ageBars = ageHours == null ? null : ageHours / primaryBarHours;
    const sessionKnown = Number.isFinite(asOfMs);
    const session = sessionKnown ? getSession(new Date(asOfMs)) : null;
    const sessionActive = !session || session.session !== 'OFF-HOURS';
    const ageIsVeryOld = Number.isFinite(ageBars) && ageBars > 24;
    const oldFarWithoutApproach = ageIsVeryOld && distanceClass === 'FAR' && approachState !== 'APPROACHING';
    let opportunityStatus = 'ACTIVE';
    if (delivery?.entry_state === 'ENTRY_TOUCHED') opportunityStatus = 'ENTRY_TOUCHED';
    else if (delivery?.delivery_status === 'EXPIRED_TP3') opportunityStatus = 'EXPIRED_TP3_BEFORE_ENTRY';
    else if (delivery?.delivery_status === 'STALE_TP2') opportunityStatus = 'STALE_TP2_BEFORE_ENTRY';
    else if (delivery?.delivery_status === 'DELIVERED_TP1') opportunityStatus = 'DELIVERED_TP1_BEFORE_ENTRY';
    else if (distanceClass === 'TOO_FAR' || oldFarWithoutApproach) opportunityStatus = 'TOO_FAR';
    else if (distanceClass === 'FAR') opportunityStatus = 'FAR_PENDING';
    else if (distanceClass === 'REACHABLE') opportunityStatus = 'REACHABLE_PENDING';
    else if (approachState === 'APPROACHING') opportunityStatus = 'PENDING_TODAY';
    else opportunityStatus = 'ACTIVE_PENDING';
    const currentOpportunity = ['PENDING_TODAY', 'ACTIVE_PENDING', 'REACHABLE_PENDING', 'FAR_PENDING'].includes(opportunityStatus)
        && ['NEAR', 'REACHABLE', 'FAR'].includes(distanceClass)
        && delivery?.entry_state === 'PENDING_UNFILLED'
        && !['STALE_TP2', 'EXPIRED_TP3', 'DELIVERED_TP1'].includes(delivery?.delivery_status);
    const currentness = !currentOpportunity ? 0
        : approachState === 'APPROACHING' && ['NEAR', 'REACHABLE'].includes(distanceClass) ? 7
            : distanceClass === 'NEAR' ? 10
                : distanceClass === 'REACHABLE' ? 4
                    : 1;
    const distancePenalty = distanceClass === 'NEAR' ? 0 : distanceClass === 'REACHABLE' ? -2 : distanceClass === 'FAR' ? -6 : 0;
    return {
        structurally_valid: true,
        current_opportunity: currentOpportunity,
        opportunity_status: opportunityStatus,
        entry_distance: rawTextPacketRoundPrice(entryDistance, precision),
        entry_distance_atr: entryDistanceAtr == null ? null : rawTextPacketRoundPrice(entryDistanceAtr, 2),
        distance_class: distanceClass,
        approach_state: approachState,
        formation_age_hours: ageHours == null ? null : rawTextPacketRoundPrice(ageHours, 2),
        formation_age_primary_bars: ageBars == null ? null : rawTextPacketRoundPrice(ageBars, 2),
        currentness,
        distance_penalty: distancePenalty,
        direction,
        session: session?.session || null,
        session_active: sessionActive,
        today_opportunity: currentOpportunity
    };
}

function rawTextFvgCurrentPriceRelation(fvg, currentPrice) {
    const price = Number(currentPrice);
    if (!Number.isFinite(price)) return 'UNKNOWN';
    const lower = fvg.status === 'PARTIAL' ? fvg.remaining_lower : fvg.lower;
    const upper = fvg.status === 'PARTIAL' ? fvg.remaining_upper : fvg.upper;
    const suffix = fvg.status === 'PARTIAL' ? '_REMAINING_ZONE' : '_ZONE';
    if (price > upper) return 'ABOVE' + suffix;
    if (price < lower) return 'BELOW' + suffix;
    return 'INSIDE' + suffix;
}

const RAW_TEXT_HP_QUALITY_THRESHOLDS = Object.freeze({ A_PLUS: 85, A: 75, B: 65 });
const RAW_TEXT_HP_SCORE_WEIGHTS = Object.freeze({
    DAILY: 10,
    PRIMARY: 8,
    CRT: 11,
    MSNR: 11,
    OB: 4,
    FVG: 10,
    FRESH: 10,
    SUPPLY_DEMAND: 8,
    EXEC: 6,
    LIQUIDITY: 5,
    VOL: 4,
    PREMIUM_DISCOUNT: 6,
    EMA: 4,
    RSI: 3
});

function calculateRawTextAtr(candles = [], period = 14) {
    const ordered = [...candles]
        .filter(candle => candle && [candle.h, candle.l, candle.c].every(value => Number.isFinite(Number(value))))
        .sort((left, right) => rawTextPacketTimestamp(left.t ?? left.time ?? left.timestamp) - rawTextPacketTimestamp(right.t ?? right.time ?? right.timestamp));
    if (!Number.isInteger(period) || period <= 0 || ordered.length < period + 1) return null;
    const trueRanges = ordered.map((candle, index) => {
        if (index === 0) return Number(candle.h) - Number(candle.l);
        const previousClose = Number(ordered[index - 1].c);
        return Math.max(
            Number(candle.h) - Number(candle.l),
            Math.abs(Number(candle.h) - previousClose),
            Math.abs(Number(candle.l) - previousClose)
        );
    });
    const values = trueRanges.slice(-period);
    return values.every(Number.isFinite) ? values.reduce((sum, value) => sum + value, 0) / period : null;
}

function rawTextUtcDayKey(value) {
    const timestamp = rawTextPacketTimestamp(value);
    return Number.isFinite(timestamp) ? new Date(timestamp).toISOString().slice(0, 10) : null;
}

function rawTextUtcWeekKey(value) {
    const timestamp = rawTextPacketTimestamp(value);
    if (!Number.isFinite(timestamp)) return null;
    const date = new Date(timestamp);
    date.setUTCDate(date.getUTCDate() - ((date.getUTCDay() + 6) % 7));
    return date.toISOString().slice(0, 10);
}

function rawTextPeriodGroups(candles = [], keyFn = rawTextUtcDayKey, asOfMs = null) {
    const groups = new Map();
    for (const candle of [...candles].sort((left, right) => rawTextPacketTimestamp(left.t ?? left.time ?? left.timestamp) - rawTextPacketTimestamp(right.t ?? right.time ?? right.timestamp))) {
        const timestamp = rawTextPacketTimestamp(candle?.t ?? candle?.time ?? candle?.timestamp);
        if (!Number.isFinite(timestamp) || (Number.isFinite(asOfMs) && timestamp > asOfMs)) continue;
        const key = keyFn(timestamp);
        if (!key) continue;
        if (!groups.has(key)) groups.set(key, []);
        groups.get(key).push(candle);
    }
    return groups;
}

function rawTextPeriodStats(candles = []) {
    if (!candles.length) return null;
    const high = Math.max(...candles.map(candle => Number(candle.h)));
    const low = Math.min(...candles.map(candle => Number(candle.l)));
    return {
        high: Number.isFinite(high) ? high : null,
        low: Number.isFinite(low) ? low : null,
        open: Number.isFinite(Number(candles[0]?.o)) ? Number(candles[0].o) : null
    };
}

function rawTextContextRelation(level, currentPrice, precision = 2) {
    if (level == null || level === '' || currentPrice == null || currentPrice === '') return 'UNKNOWN';
    const target = Number(level);
    const price = Number(currentPrice);
    if (![target, price].every(Number.isFinite)) return 'UNKNOWN';
    if (Math.abs(target - price) <= (10 ** -precision) / 2) return 'AT';
    return price > target ? 'ABOVE' : 'BELOW';
}

function rawTextContextValue(value, precision = 2) {
    if (value == null || value === '') return 'NA';
    return Number.isFinite(Number(value)) ? rawTextPacketFormatNumber(value, precision) : 'NA';
}

function buildRawTextSessionLevels(candles = [], asOfMs = null, precision = 2) {
    const definitions = {
        'ASIA KZ': { key: 'ASIA', start: 0, end: 4 },
        'LONDON KZ': { key: 'LONDON', start: 7, end: 10 },
        'NEW_YORK KZ': { key: 'NY', start: 12, end: 15 }
    };
    const groups = new Map();
    for (const candle of candles) {
        const timestamp = rawTextPacketTimestamp(candle?.t ?? candle?.time ?? candle?.timestamp);
        if (!Number.isFinite(timestamp) || (Number.isFinite(asOfMs) && timestamp > asOfMs)) continue;
        const date = new Date(timestamp);
        const definition = definitions[getSession(date).session];
        if (!definition) continue;
        const day = date.toISOString().slice(0, 10);
        const end = Date.parse(day + 'T' + String(definition.end).padStart(2, '0') + ':00:00.000Z');
        if (Number.isFinite(asOfMs) && end > asOfMs) continue;
        const groupKey = day + ':' + definition.key;
        if (!groups.has(groupKey)) groups.set(groupKey, { definition, day, candles: [] });
        groups.get(groupKey).candles.push(candle);
    }
    const result = {};
    for (const definition of Object.values(definitions)) {
        const completed = [...groups.values()]
            .filter(group => group.definition.key === definition.key)
            .sort((left, right) => left.day.localeCompare(right.day));
        const latest = completed.at(-1);
        const stats = rawTextPeriodStats(latest?.candles || []);
        result[definition.key] = {
            high: stats?.high ?? null,
            low: stats?.low ?? null,
            high_text: rawTextContextValue(stats?.high, precision),
            low_text: rawTextContextValue(stats?.low, precision),
            day: latest?.day || null
        };
    }
    return result;
}

function rawTextOrderedClosedCandles(candles = [], asOfMs = null) {
    return [...candles]
        .filter(candle => candle && candle.is_closed !== false && candle.closed !== false && [candle.h, candle.l, candle.c].every(value => Number.isFinite(Number(value))))
        .filter(candle => {
            const timestamp = rawTextPacketTimestamp(candle.t ?? candle.time ?? candle.timestamp);
            return Number.isFinite(timestamp) && (!Number.isFinite(asOfMs) || timestamp <= asOfMs);
        })
        .sort((left, right) => rawTextPacketTimestamp(left.t ?? left.time ?? left.timestamp) - rawTextPacketTimestamp(right.t ?? right.time ?? right.timestamp));
}

function buildRawTextStructuralDealingRange(blocks = [], currentPrice = null, precision = 2, asOfMs = null) {
    const candidates = [];
    for (const timeframe of ['1D', '4H', '1H']) {
        const block = blocks.find(item => item.timeframe === timeframe);
        const candles = rawTextOrderedClosedCandles(block?.candles || [], asOfMs);
        if (candles.length < 8) continue;
        const structural = confirmedStructuralState(candles, 2);
        const swings = structural.swings || { H: [], L: [] };
        const pairs = [];
        if (structural.state === 'BULLISH') {
            for (const low of swings.L || []) for (const high of swings.H || []) {
                if (low.i >= high.i || !(Number(high.p) > Number(low.p))) continue;
                const firstKnowable = Math.max(
                    rawTextPacketTimestamp(low.first_knowable_time),
                    rawTextPacketTimestamp(high.first_knowable_time)
                );
                if (Number.isFinite(firstKnowable)) pairs.push({ direction: 'BULLISH', low, high, firstKnowable });
            }
        } else if (structural.state === 'BEARISH') {
            for (const high of swings.H || []) for (const low of swings.L || []) {
                if (high.i >= low.i || !(Number(high.p) > Number(low.p))) continue;
                const firstKnowable = Math.max(
                    rawTextPacketTimestamp(high.first_knowable_time),
                    rawTextPacketTimestamp(low.first_knowable_time)
                );
                if (Number.isFinite(firstKnowable)) pairs.push({ direction: 'BEARISH', low, high, firstKnowable });
            }
        }
        const selected = pairs.sort((left, right) => right.firstKnowable - left.firstKnowable).at(0);
        if (!selected) continue;
        const low = Number(selected.low.p);
        const high = Number(selected.high.p);
        const equilibrium = (low + high) / 2;
        const increment = 10 ** -precision;
        const price = Number(currentPrice);
        const location = Number.isFinite(price)
            ? Math.abs(price - equilibrium) <= increment / 2 ? 'EQUILIBRIUM' : price < equilibrium ? 'DISCOUNT' : 'PREMIUM'
            : 'UNKNOWN';
        candidates.push({
            timeframe,
            direction: selected.direction,
            low,
            high,
            equilibrium,
            first_knowable_ms: selected.firstKnowable,
            first_knowable: new Date(selected.firstKnowable).toISOString(),
            status: 'VALID',
            location
        });
    }
    return candidates.sort((left, right) => right.first_knowable_ms - left.first_knowable_ms)[0] || null;
}

function calculateRawTextEma(candles = [], period = 20, asOfMs = null) {
    const ordered = rawTextOrderedClosedCandles(candles, asOfMs);
    if (!Number.isInteger(period) || period <= 0 || ordered.length < period) return null;
    const closes = ordered.map(candle => Number(candle.c));
    let value = closes.slice(0, period).reduce((sum, close) => sum + close, 0) / period;
    const multiplier = 2 / (period + 1);
    for (const close of closes.slice(period)) value = (close - value) * multiplier + value;
    return Number.isFinite(value) ? value : null;
}

function rawTextIndicatorState(values = {}) {
    const { ema20, ema50, ema200 } = values;
    if (![ema20, ema50, ema200].every(Number.isFinite)) return 'MIXED';
    if (ema20 > ema50 && ema50 > ema200) return 'BULLISH';
    if (ema20 < ema50 && ema50 < ema200) return 'BEARISH';
    return 'MIXED';
}

function rawTextPriceVs(value, price) {
    if (![value, price].every(Number.isFinite)) return 'UNKNOWN';
    if (price === value) return 'AT';
    return price > value ? 'ABOVE' : 'BELOW';
}

function buildRawTextEmaContext(blocks = [], currentPrice = null, asOfMs = null) {
    const values = {};
    for (const timeframe of ['1D', '4H', '1H']) {
        const block = blocks.find(item => item.timeframe === timeframe);
        const emaValues = {
            ema20: calculateRawTextEma(block?.candles || [], 20, asOfMs),
            ema50: calculateRawTextEma(block?.candles || [], 50, asOfMs),
            ema200: calculateRawTextEma(block?.candles || [], 200, asOfMs)
        };
        values[timeframe] = { ...emaValues, state: rawTextIndicatorState(emaValues) };
        for (const period of [20, 50, 200]) values[timeframe]['price_vs_' + period] = rawTextPriceVs(emaValues['ema' + period], Number(currentPrice));
    }
    return values;
}

function rawTextRsiState(value) {
    if (!Number.isFinite(value)) return 'NA';
    if (value >= 70) return 'OVERBOUGHT';
    if (value <= 30) return 'OVERSOLD';
    return 'NEUTRAL';
}

function calculateRawTextRsi(candles = [], period = 14, asOfMs = null) {
    const ordered = rawTextOrderedClosedCandles(candles, asOfMs);
    const value = computeRSI(ordered.map(candle => Number(candle.c)), period);
    return Number.isFinite(value) ? value : null;
}

function buildRawTextRsiContext(blocks = [], asOfMs = null) {
    const values = {};
    for (const timeframe of ['1D', '4H', '1H']) {
        const value = calculateRawTextRsi(blocks.find(item => item.timeframe === timeframe)?.candles || [], 14, asOfMs);
        values[timeframe] = { value, state: rawTextRsiState(value) };
    }
    return values;
}

function buildRawTextSupplyDemandAudit(blocks = [], precision = 2, asOfMs = null) {
    const records = [];
    for (const block of blocks.filter(item => ['4H', '1H'].includes(item.timeframe))) {
        const candles = rawTextOrderedClosedCandles(block.candles || [], asOfMs);
        for (const direction of ['BUY', 'SELL']) {
            for (const ob of detectOrderBlocks(candles, direction)) {
                const departureIndex = Number(ob.formation_index);
                const departure = candles[departureIndex];
                if (!departure || departureIndex < 1) continue;
                const displacement = isDirectionalDisplacement(
                    departure,
                    direction,
                    calculateRawTextAtr(candles.slice(0, departureIndex + 1), 14)
                );
                if (!displacement) continue;
                const low = Number(ob.low);
                const high = Number(ob.high);
                if (!(Number.isFinite(low) && Number.isFinite(high) && high >= low)) continue;
                const sourceTime = rawTextPacketTimestamp(ob.first_knowable_time ?? ob.confirmation_time);
                if (!Number.isFinite(sourceTime)) continue;
                const touches = checkZoneFreshness(candles, {
                    low, high, source_candle_index: ob.origin_index,
                    source_time: ob.first_knowable_time
                }, direction);
                const invalidated = candles.slice(departureIndex + 1).some(candle => direction === 'BUY'
                    ? Number(candle.c) < low
                    : Number(candle.c) > high);
                const status = invalidated ? 'INVALIDATED' : touches.used ? 'MITIGATED' : touches.partiallyUsed ? 'TESTED' : 'FRESH';
                records.push({
                    type: direction === 'BUY' ? 'DEMAND' : 'SUPPLY',
                    direction,
                    timeframe: block.timeframe,
                    low,
                    high,
                    status,
                    first_knowable_ms: sourceTime,
                    first_knowable: new Date(sourceTime).toISOString(),
                    departure: 'STRONG',
                    ref: (direction === 'BUY' ? 'DEMAND:' : 'SUPPLY:') + block.timeframe + ':' + sourceTime + ':' + rawTextPacketFormatNumber(low, precision) + '-' + rawTextPacketFormatNumber(high, precision)
                });
            }
        }
    }
    const unique = new Map(records.map(record => [record.ref, record]));
    return [...unique.values()].sort((left, right) => right.first_knowable_ms - left.first_knowable_ms);
}

function buildRawTextSupplyDemandLines(records = [], precision = 2) {
    if (!records.length) return ['NONE'];
    return records.slice(0, 12).map(record => [
        record.type + ': TF=' + record.timeframe.toLowerCase(),
        'ZONE=' + rawTextPacketFormatNumber(record.low, precision) + '-' + rawTextPacketFormatNumber(record.high, precision),
        'STATUS=' + record.status,
        'FIRST_KNOWABLE=' + record.first_knowable,
        'DEPARTURE=' + record.departure,
        'REF=' + record.ref
    ].join(' '));
}

function buildRawTextMarketContext(blocks = [], currentPrice = null, precision = 2, asOfMs = null, dailyBias = 'NEUTRAL', biasLabel = 'DAILY_BIAS') {
    const findBlock = timeframe => blocks.find(block => block.timeframe === timeframe);
    const atr4h = calculateRawTextAtr(findBlock('4H')?.candles || [], 14);
    const atr1h = calculateRawTextAtr(findBlock('1H')?.candles || [], 14);
    const intraday = findBlock('1H') || findBlock('15M') || findBlock('5M') || findBlock('4H');
    const weekly = findBlock('4H') || intraday;
    const dayGroups = rawTextPeriodGroups(intraday?.candles || [], rawTextUtcDayKey, asOfMs);
    const weekGroups = rawTextPeriodGroups(weekly?.candles || [], rawTextUtcWeekKey, asOfMs);
    const dayKeys = [...dayGroups.keys()].sort();
    const weekKeys = [...weekGroups.keys()].sort();
    const previousDayStats = rawTextPeriodStats(dayGroups.get(dayKeys.at(-2)) || []);
    const previousWeekStats = rawTextPeriodStats(weekGroups.get(weekKeys.at(-2)) || []);
    const currentDayStats = rawTextPeriodStats(dayGroups.get(dayKeys.at(-1)) || []);
    const currentWeekStats = rawTextPeriodStats(weekGroups.get(weekKeys.at(-1)) || []);
    const sessionLevels = buildRawTextSessionLevels(intraday?.candles || [], asOfMs, precision);
    const dealingRange = buildRawTextStructuralDealingRange(blocks, currentPrice, precision, asOfMs);
    const ema = buildRawTextEmaContext(blocks, currentPrice, asOfMs);
    const rsi = buildRawTextRsiContext(blocks, asOfMs);
    const context = {
        precision,
        as_of_ms: asOfMs,
        daily_bias: ['BULLISH', 'BEARISH'].includes(dailyBias) ? dailyBias : 'NEUTRAL',
        atr_4h: atr4h,
        atr_1h: atr1h,
        pdh: previousDayStats?.high ?? null,
        pdl: previousDayStats?.low ?? null,
        pwh: previousWeekStats?.high ?? null,
        pwl: previousWeekStats?.low ?? null,
        daily_open: currentDayStats?.open ?? null,
        weekly_open: currentWeekStats?.open ?? null,
        session_levels: sessionLevels,
        dealing_range: dealingRange,
        ema,
        rsi
    };
    return {
        context,
        lines: [
            '=== MARKET CONTEXT ===',
            [
                biasLabel + '=' + context.daily_bias,
                'ATR_4H=' + rawTextContextValue(context.atr_4h, precision),
                'ATR_1H=' + rawTextContextValue(context.atr_1h, precision),
                'PDH=' + rawTextContextValue(context.pdh, precision),
                'PDL=' + rawTextContextValue(context.pdl, precision),
                'PWH=' + rawTextContextValue(context.pwh, precision),
                'PWL=' + rawTextContextValue(context.pwl, precision)
            ].join(' '),
            [
                'PDH_RELATION=' + rawTextContextRelation(context.pdh, currentPrice, precision),
                'PDL_RELATION=' + rawTextContextRelation(context.pdl, currentPrice, precision),
                'DAILY_OPEN=' + rawTextContextValue(context.daily_open, precision),
                'DAILY_OPEN_RELATION=' + rawTextContextRelation(context.daily_open, currentPrice, precision),
                'WEEKLY_OPEN=' + rawTextContextValue(context.weekly_open, precision),
                'WEEKLY_OPEN_RELATION=' + rawTextContextRelation(context.weekly_open, currentPrice, precision)
            ].join(' '),
            [
                'ASIA_HIGH=' + sessionLevels.ASIA.high_text,
                'ASIA_LOW=' + sessionLevels.ASIA.low_text,
                'LONDON_HIGH=' + sessionLevels.LONDON.high_text,
                'LONDON_LOW=' + sessionLevels.LONDON.low_text,
                'NY_HIGH=' + sessionLevels.NY.high_text,
                'NY_LOW=' + sessionLevels.NY.low_text
            ].join(' '),
            dealingRange
                ? [
                    'DEALING_RANGE_TF=' + dealingRange.timeframe.toLowerCase(),
                    'DR_LOW=' + rawTextPacketFormatNumber(dealingRange.low, precision),
                    'DR_HIGH=' + rawTextPacketFormatNumber(dealingRange.high, precision),
                    'DR_EQ=' + rawTextPacketFormatNumber(dealingRange.equilibrium, precision),
                    'PREMIUM_DISCOUNT=' + dealingRange.location,
                    'LOCATION=' + dealingRange.location,
                    'DR_DIR=' + dealingRange.direction,
                    'DR_FIRST_KNOWABLE=' + dealingRange.first_knowable,
                    'DR_STATUS=' + dealingRange.status
                ].join(' ')
                : 'PREMIUM_DISCOUNT=NOT_EMITTED_NO_ACCEPTED_STRUCTURAL_DEALING_RANGE',
            ['EMA_1D_20', 'EMA_1D_50', 'EMA_1D_200', 'EMA_4H_20', 'EMA_4H_50', 'EMA_4H_200', 'EMA_1H_20', 'EMA_1H_50', 'EMA_1H_200']
                .map(key => {
                    const timeframe = key.slice(4, 6);
                    const period = key.slice(7);
                    return key + '=' + rawTextContextValue(ema[timeframe]?.['ema' + period], precision);
                }).join(' '),
            ['1D', '4H', '1H'].map(timeframe => 'EMA_STRUCTURE_' + timeframe + '=' + (ema[timeframe]?.state || 'MIXED')).join(' '),
            ['RSI_1D_14', 'RSI_4H_14', 'RSI_1H_14'].map(key => {
                const timeframe = key.slice(4, 6);
                return key + '=' + rawTextContextValue(rsi[timeframe]?.value, 2) + ' RSI_' + timeframe + '_STATE=' + (rsi[timeframe]?.state || 'NA');
            }).join(' ')
        ]
    };
}

function rawTextDisplacementAssessment(block, fvg, direction) {
    const formationIndex = Number.isInteger(fvg?.formation_index) ? fvg.formation_index + 2 : -1;
    const candles = block?.candles || [];
    if (formationIndex < 0 || formationIndex >= candles.length) return { label: 'WEAK', score: 0, metrics: null };
    const metrics = getDisplacementMetricsAtIndex(candles, formationIndex, direction);
    if (!metrics) return { label: 'WEAK', score: 0, metrics: null };
    if (metrics.detected) return { label: 'STRONG', score: 5, metrics };
    if (metrics.body_ratio >= 1.5 && metrics.close_quality >= 0.6) return { label: 'MODERATE', score: 3, metrics };
    return { label: 'WEAK', score: 0, metrics };
}

function rawTextExecutionSupport(candidateRecord, blocks = [], crtRecords = [], msnrRecords = []) {
    const support = {};
    let score = 0;
    const primaryLow = Number(candidateRecord.fvg.status === 'PARTIAL' ? candidateRecord.fvg.remaining_lower : candidateRecord.fvg.lower);
    const primaryHigh = Number(candidateRecord.fvg.status === 'PARTIAL' ? candidateRecord.fvg.remaining_upper : candidateRecord.fvg.upper);
    const direction = candidateRecord.candidate.action === 'BUY_LIMIT' ? 'BUY' : 'SELL';
    for (const timeframe of ['15M', '5M']) {
        const block = blocks.find(item => item.timeframe === timeframe);
        const lowerFvgs = block ? detectRawTextFvgs(block.candles, timeframe) : [];
        const alignedFvg = lowerFvgs.some(fvg => fvg.type === (direction === 'BUY' ? 'BULLISH' : 'BEARISH')
            && fvg.status !== 'FULLY_TRAVERSED'
            && rawTextIntervalsOverlap(primaryLow, primaryHigh, Number(fvg.lower), Number(fvg.upper)));
        const alignedStructure = [...crtRecords, ...msnrRecords].some(record => record.timeframe === timeframe
            && record.status === 'VALID'
            && record.direction === direction
            && rawTextIntervalsOverlap(primaryLow, primaryHigh, Number(record.range_low ?? record.zone_low), Number(record.range_high ?? record.zone_high)));
        const opposingFvg = lowerFvgs.some(fvg => fvg.type === (direction === 'BUY' ? 'BEARISH' : 'BULLISH')
            && fvg.status !== 'FULLY_TRAVERSED'
            && rawTextIntervalsOverlap(primaryLow, primaryHigh, Number(fvg.lower), Number(fvg.upper)));
        const state = alignedFvg || alignedStructure ? 'CONFIRMED' : opposingFvg ? 'CONFLICTING' : 'NONE';
        support[timeframe === '15M' ? 'exec_15m' : 'exec_5m'] = state;
        if (state === 'CONFIRMED') score += Math.floor(RAW_TEXT_HP_SCORE_WEIGHTS.EXEC / 2);
    }
    return { ...support, score };
}

// ---------------------------------------------------------------------------
// V2 model router
// ---------------------------------------------------------------------------
// The public methodology used here is intentionally explicit about its
// assumptions.  CRT means a closed-candle range followed by a boundary raid
// and a close-back.  TBS means a failed breakout/reclaim of a known reference.
// MSNR is a location/role-transition fact.  None of those facts is allowed to
// authorize a trade by itself.  A model must first be complete, then an
// execution zone created after that model's confirmation may be admitted.
// This is a V2 authority layer, not a new strategy or a score replacement.

function normalizeStrategyMode(value) {
    const mode = String(value || '').toUpperCase();
    if (mode === 'MODEL_ROUTER' || mode === 'MODEL_ROUTER_LEGACY') return 'MODEL_ROUTER';
    if (mode === 'MARKET_MECHANICS' || mode === 'DETERMINISTIC') return 'MARKET_MECHANICS';
    return STRATEGY_MODE;
}

function configuredStrategyMode() {
    const value = (typeof window !== 'undefined' ? window.__V2_STRATEGY_MODE__ : null)
        || (typeof globalThis !== 'undefined' ? globalThis.__V2_STRATEGY_MODE__ : null)
        || STRATEGY_MODE;
    return normalizeStrategyMode(value);
}

function rawTextV2StrategyMode(strategyAudits = {}) {
    return normalizeStrategyMode(strategyAudits.strategy_mode
        || strategyAudits.strategyMode
        || configuredStrategyMode());
}

function isRawCandleAiMode(source = {}) {
    const mode = source.strategy_mode
        || source.strategyMode
        || source.AUTHORITY_MODE
        || source.market_context?.strategy_mode
        || source.market_mechanics?.authority_mode
        || configuredStrategyMode();
    return normalizeStrategyMode(mode) === STRATEGY_MODE;
}

function rawTextModelEventTime(record = {}) {
    return rawTextPacketTimestamp(record.first_knowable_ms
        ?? record.first_knowable_time
        ?? record.confirmation_time
        ?? record.reclaim_time
        ?? record.event_time
        ?? record.source_time);
}

function rawTextModelDirection(record = {}) {
    const value = String(record.direction || record.type || record.action || '').toUpperCase();
    if (value.includes('BUY') || value.includes('BULL')) return 'BUY';
    if (value.includes('SELL') || value.includes('BEAR')) return 'SELL';
    return null;
}

function rawTextModelRange(record = {}) {
    const low = Number(record.range_low ?? record.zone_low ?? record.low);
    const high = Number(record.range_high ?? record.zone_high ?? record.high);
    return Number.isFinite(low) && Number.isFinite(high) && high >= low ? { low, high } : null;
}

function rawTextModelStableId(prefix, parts = []) {
    return [prefix, ...parts.map(value => String(value ?? 'NA'))].join(':');
}

function buildRawTextDeterministicTbsAudit(blocks = [], pairLocal = pair, symbolMetadata = {}, precision = 2) {
    const records = [];
    for (const block of blocks) {
        const events = detectTurtleSoupEvents(block.candles, block.timeframe, pairLocal, symbolMetadata);
        for (const event of events) {
            const firstKnowableMs = rawTextPacketTimestamp(event.first_knowable_time ?? event.reclaim_time ?? event.event_time);
            const direction = rawTextModelDirection(event);
            if (!direction || !Number.isFinite(firstKnowableMs)) continue;
            const ref = rawTextModelStableId('TBS', [String(block.timeframe).toUpperCase(), direction, firstKnowableMs, event.reference_bar_index]);
            records.push({
                ref,
                tbs_id: ref,
                timeframe: String(block.timeframe).toUpperCase(),
                direction,
                liquidity_ref: rawTextModelStableId('LIQUIDITY', [event.reference_type, event.keyLevel, event.reference_bar_index]),
                reference_price: Number(event.keyLevel),
                break_time_ms: rawTextPacketTimestamp(event.sweep_time),
                sweep_time_ms: rawTextPacketTimestamp(event.sweep_time),
                sweep_extreme: Number(event.sweep_extreme),
                reclaim_time_ms: rawTextPacketTimestamp(event.reclaim_time),
                confirmation_time_ms: firstKnowableMs,
                first_knowable_ms: firstKnowableMs,
                status: event.invalidated ? 'EXPIRED' : event.reclaim_confirmed ? 'CONFIRMED' : 'SWEPT',
                subtype: event.reference_type === 'CRT_BOUNDARY' ? 'TURTLE_SOUP_RECLAIM' : 'FAILED_BREAKOUT',
                event
            });
        }
    }
    const lines = records.map(record => [
        'TBS: TF=' + record.timeframe.toLowerCase(),
        'DIRECTION=' + record.direction,
        'REFERENCE=' + rawTextPacketFormatNumber(record.reference_price, precision),
        'SWEEP=' + rawTextPacketFormatNumber(record.sweep_extreme, precision),
        'RECLAIM=' + (record.reclaim_time_ms ? new Date(record.reclaim_time_ms).toISOString() : 'NONE'),
        'STATUS=' + record.status,
        'SUBTYPE=' + record.subtype,
        'TBS_REF=' + record.ref
    ].join(' '));
    return { records, lines: lines.length ? lines : ['NONE'] };
}

function rawTextModelStructureEvents(blocks = [], direction, minimumTime = 0, asOfMs = null, performanceCache = null) {
    const result = [];
    for (const block of blocks) {
        const timeframe = String(block.timeframe || '').toUpperCase();
        if (!['1H', '15M', '5M'].includes(timeframe)) continue;
        const last = block.candles?.at(-1);
        const cacheKey = `${timeframe}:${block.candles?.length || 0}:${last?.t || last?.timestamp || ''}:${direction}`;
        const cache = performanceCache?.modelStructureEvents;
        let event = cache?.get(cacheKey);
        if (cache && cache.has(cacheKey)) event = cache.get(cacheKey);
        else {
            event = detectConfirmedStructuralBreak(block.candles, direction, timeframe, 2);
            // The public model permits a close-back/continuation displacement
            // to be the directional confirmation even when the stricter
            // confirmed-pivot compiler has not emitted a new break on the
            // latest candle.  This fallback still uses only closed candles
            // and requires both a directional structure read and displacement.
            if (!event) {
                const closed = closedStructureCandles(block.candles);
                const mss = detectMSS(closed);
                const latestIndex = closed.length - 1;
                const displacement = getDisplacementMetricsAtIndex(closed, latestIndex, direction);
                const mssDirection = mss?.type === 'BULL' ? 'BUY' : mss?.type === 'BEAR' ? 'SELL' : null;
                if (mssDirection === direction && displacement?.detected) {
                    event = {
                        event_type: 'MSS',
                        direction,
                        index: latestIndex,
                        timeframe,
                        level: Number(mss.level),
                        confirmation_time: candleTimestamp(closed[latestIndex], latestIndex, timeframe),
                        first_knowable_time: candleTimestamp(closed[latestIndex], latestIndex, timeframe),
                        event_time: candleTimestamp(closed[latestIndex], latestIndex, timeframe),
                        displacement_confirmed: true,
                        displacement_id: rawTextModelStableId('DISPLACEMENT', [timeframe, latestIndex, direction])
                    };
                }
            }
            if (cache) cache.set(cacheKey, event || null);
        }
        if (!event || !event.displacement_confirmed) continue;
        const eventTime = rawTextPacketTimestamp(event.first_knowable_time || event.event_time);
        if (!Number.isFinite(eventTime) || eventTime < minimumTime || (Number.isFinite(asOfMs) && eventTime > asOfMs)) continue;
        result.push({
            structure_event_id: rawTextModelStableId('STRUCTURE', [timeframe, direction, eventTime, event.level]),
            type: event.event_type === 'MSS' ? 'MSS' : 'BOS',
            direction,
            timeframe,
            first_knowable_ms: eventTime,
            break_price: Number(event.level),
            displacement_ref: event.displacement_id,
            event
        });
    }
    return result.sort((left, right) => right.first_knowable_ms - left.first_knowable_ms);
}

function rawTextModelLocationContext(blocks = [], direction, crtRecords = [], msnrRecords = [], supplyDemandRecords = [], marketContext = {}, asOfMs = null) {
    const validAt = record => {
        const time = rawTextModelEventTime(record);
        return (!Number.isFinite(time) || !Number.isFinite(asOfMs) || time <= asOfMs)
            && String(record.status || '').toUpperCase() !== 'INVALIDATED'
            && String(record.status || '').toUpperCase() !== 'EXPIRED';
    };
    const msnr = msnrRecords.filter(record => validAt(record) && rawTextModelDirection(record) === direction);
    const crt = crtRecords.filter(record => validAt(record) && rawTextModelDirection(record) === direction && record.detected !== false);
    const supportingType = direction === 'BUY' ? 'DEMAND' : 'SUPPLY';
    const locationRecords = [
        ...msnr.map(record => ({ source: 'MSNR', ref: record.ref, record })),
        ...supplyDemandRecords
            .filter(record => validAt(record) && rawTextModelDirection(record) === direction && String(record.type || '').toUpperCase() === supportingType)
            .map(record => ({ source: 'SUPPLY_DEMAND', ref: record.ref || record.id, record })),
        ...crt.map(record => ({ source: 'CRT', ref: record.ref, record }))
    ];
    const htfBlocks = blocks.filter(block => ['4H', '1H'].includes(String(block.timeframe).toUpperCase()));
    const states = htfBlocks.map(block => ({
        timeframe: String(block.timeframe).toUpperCase(),
        state: confirmedStructuralState(block.candles, 2).state
    }));
    const alignedState = states.some(item => item.state === (direction === 'BUY' ? 'BULLISH' : 'BEARISH'));
    const dailyBias = String(marketContext.daily_bias || '').toUpperCase();
    const alignedDaily = dailyBias === (direction === 'BUY' ? 'BULLISH' : 'BEARISH');
    const reversalLocation = locationRecords.length > 0;
    const contextType = alignedState || alignedDaily
        ? (direction === 'BUY' ? 'BULLISH_CONTINUATION' : 'BEARISH_CONTINUATION')
        : reversalLocation
            ? (direction === 'BUY' ? 'BULLISH_REVERSAL_LOCATION' : 'BEARISH_REVERSAL_LOCATION')
            : 'NEUTRAL';
    return {
        direction,
        context_type: contextType,
        aligned_state: alignedState,
        aligned_daily: alignedDaily,
        location_records: locationRecords,
        primary_location: locationRecords[0] || null,
        states,
        valid: alignedState || alignedDaily || reversalLocation
    };
}

function rawTextModelEventsMatch(left = {}, right = {}, maxAgeMs = 12 * 60 * 60 * 1000) {
    const leftTime = rawTextModelEventTime(left);
    const rightTime = rawTextModelEventTime(right);
    if (!Number.isFinite(leftTime) || !Number.isFinite(rightTime) || Math.abs(leftTime - rightTime) > maxAgeMs) return false;
    const leftRange = rawTextModelRange(left);
    const rightRange = rawTextModelRange(right);
    if (!leftRange || !rightRange) return false;
    return rawTextIntervalsOverlap(leftRange.low, leftRange.high, rightRange.low, rightRange.high)
        || Math.abs(Number(left.sweep_extreme ?? left.reference_price) - Number(right.sweep_extreme ?? right.reference_price)) <= Math.max(Math.abs(leftRange.high - leftRange.low), Math.abs(rightRange.high - rightRange.low));
}

function rawTextModelFindZone(executionRecords = [], direction, confirmationTime, asOfMs, context = {}, performanceCache = null) {
    const action = direction === 'BUY' ? 'BUY_LIMIT' : 'SELL_LIMIT';
    const eligible = executionRecords.filter(record => {
        const recordDirection = record.candidate?.action === 'BUY_LIMIT' ? 'BUY' : record.candidate?.action === 'SELL_LIMIT' ? 'SELL' : null;
        const formationTime = rawTextPacketTimestamp(record.fvg?.c3);
        return recordDirection === direction
            && Number.isFinite(formationTime)
            && formationTime >= confirmationTime
            && formationTime <= asOfMs
            && record.fvg?.status !== 'FULLY_TRAVERSED'
            && !['STALE_TP2_BEFORE_ENTRY', 'EXPIRED_TP3_BEFORE_ENTRY', 'DELIVERED_TP1_BEFORE_ENTRY', 'TOO_FAR'].includes(record.current?.opportunity_status)
            && record.delivery?.entry_state === 'PENDING_UNFILLED';
    }).sort((left, right) => rawTextPacketTimestamp(left.fvg.c3) - rawTextPacketTimestamp(right.fvg.c3) || String(left.fvg.c1).localeCompare(String(right.fvg.c1)));
    for (const record of eligible) {
        const block = record.block;
        const zoneLow = Number(record.fvg.status === 'PARTIAL' ? record.fvg.remaining_lower : record.fvg.lower);
        const zoneHigh = Number(record.fvg.status === 'PARTIAL' ? record.fvg.remaining_upper : record.fvg.upper);
        const candles = block?.candles || [];
        const last = candles.at(-1);
        const obKey = `${String(block?.timeframe || '').toUpperCase()}:${candles.length}:${last?.t || last?.timestamp || ''}:${direction}`;
        const obCache = performanceCache?.modelOrderBlocks;
        let detectedOrderBlocks = obCache?.get(obKey);
        if (obCache && obCache.has(obKey)) detectedOrderBlocks = obCache.get(obKey);
        else {
            detectedOrderBlocks = detectOrderBlocks(candles, direction);
            if (obCache) obCache.set(obKey, detectedOrderBlocks);
        }
        const orderBlocks = detectedOrderBlocks.filter(ob => {
            const formation = rawTextPacketTimestamp(ob.first_knowable_time || ob.formation_time);
            return Number.isFinite(formation)
                && formation >= confirmationTime
                && formation <= rawTextPacketTimestamp(record.fvg.c3)
                && rawTextIntervalsOverlap(zoneLow, zoneHigh, Number(ob.low), Number(ob.high));
        });
        const zone = {
            entry_zone_id: rawTextModelStableId('ENTRY_ZONE', [direction, record.fvg.timeframe, record.fvg.c1, record.fvg.c3]),
            type: orderBlocks.length ? 'OB+FVG' : 'FVG',
            fvg_ref: rawTextModelStableId('FVG', [record.fvg.timeframe, record.fvg.c1, record.fvg.c2, record.fvg.c3]),
            ob: orderBlocks[0] || null,
            low: zoneLow,
            high: zoneHigh,
            formation_time: rawTextPacketTimestamp(record.fvg.c3),
            first_retrace: record.delivery?.entry_state === 'PENDING_UNFILLED',
            freshness: record.delivery?.delivery_status || record.fvg.status
        };
        if (!zone.first_retrace) continue;
        return { record, zone };
    }
    return null;
}

function rawTextModelObjective(direction, entry, model, blocks = [], marketContext = {}) {
    const values = [];
    if (model.crt?.event) {
        const range = rawTextModelRange(model.crt);
        if (range) values.push({ price: direction === 'BUY' ? range.high : range.low, type: 'CRT_OPPOSITE_RANGE', ref: model.crt.ref });
    }
    const fourH = blocks.find(block => String(block.timeframe).toUpperCase() === '4H');
    if (fourH) {
        const swings = findSwings(fourH.candles, 2);
        const levels = direction === 'BUY' ? swings.H || [] : swings.L || [];
        for (const swing of levels.slice().reverse()) values.push({ price: Number(swing.p), type: 'HTF_SWING', ref: rawTextModelStableId('SWING', [fourH.timeframe, direction, swing.i, swing.p]) });
    }
    const sessionLevels = Object.values(marketContext.session_levels || {});
    for (const level of sessionLevels) values.push({ price: Number(direction === 'BUY' ? level.high : level.low), type: 'SESSION_LIQUIDITY', ref: level.ref || 'SESSION' });
    values.push(
        { price: Number(direction === 'BUY' ? marketContext.pdh : marketContext.pdl), type: direction === 'BUY' ? 'PDH' : 'PDL', ref: direction === 'BUY' ? 'PDH' : 'PDL' },
        { price: Number(direction === 'BUY' ? marketContext.pwh : marketContext.pwl), type: direction === 'BUY' ? 'PWH' : 'PWL', ref: direction === 'BUY' ? 'PWH' : 'PWL' }
    );
    const valid = values.filter(item => Number.isFinite(item.price) && (direction === 'BUY' ? item.price > entry : item.price < entry));
    valid.sort((left, right) => Math.abs(left.price - entry) - Math.abs(right.price - entry) || String(left.ref).localeCompare(String(right.ref)));
    return valid[0] || null;
}

function rawTextModelGeometry(candidate, direction, objective) {
    const entry = Number(candidate.entry);
    const stop = Number(candidate.stop_loss);
    const targets = [candidate.tp1, candidate.tp2, candidate.tp3].map(Number).filter(Number.isFinite);
    if (!Number.isFinite(entry) || !Number.isFinite(stop) || !objective || !Number.isFinite(Number(objective.price))) return { valid: false, reason: 'INVALID_TARGET_DIRECTION' };
    const validStop = direction === 'BUY' ? stop < entry : stop > entry;
    const validTargets = targets.filter(target => direction === 'BUY' ? target > entry : target < entry);
    const validObjective = direction === 'BUY' ? objective.price > entry : objective.price < entry;
    if (!validStop || !validObjective || validTargets.length === 0) return { valid: false, reason: 'INVALID_TARGET_DIRECTION' };
    return { valid: true, risk: Math.abs(entry - stop), validTargets };
}

function rawTextModelBuildCandidate(model, zoneMatch, direction, blocks, marketContext, precision, pathRecords, asOfMs) {
    const base = zoneMatch.record.candidate;
    const increment = 10 ** -precision;
    const sweepExtreme = Number(model.tbs?.sweep_extreme ?? model.crt?.event?.sweep_extreme ?? model.msnr?.level?.structural_invalidation);
    const candidate = { ...base };
    if (Number.isFinite(sweepExtreme)) candidate.stop_loss = rawTextPacketRoundPrice(direction === 'BUY' ? sweepExtreme - increment : sweepExtreme + increment, precision);
    const objective = rawTextModelObjective(direction, Number(candidate.entry), model, blocks, marketContext);
    if (!objective) return { valid: false, reason: 'NO_VALID_OBJECTIVE' };
    const baseTargets = [base.tp1, base.tp2, base.tp3].map(Number).filter(Number.isFinite);
    const structuralIntermediates = [model.crt?.event ? Number(model.crt.event.range_mid) : NaN]
        .filter(value => Number.isFinite(value) && (direction === 'BUY' ? value > candidate.entry && value < objective.price : value < candidate.entry && value > objective.price));
    const pathCompatibleFallbacks = baseTargets.filter(value => direction === 'BUY'
        ? value > candidate.entry && value < objective.price
        : value < candidate.entry && value > objective.price);
    const intermediates = [...new Set([...pathCompatibleFallbacks, ...structuralIntermediates])]
        .sort((left, right) => direction === 'BUY' ? left - right : right - left);
    // The model objective is always the final target used.  Fixed-R levels
    // can survive only as deterministic interim targets on the path to it.
    const targetValues = [...intermediates.slice(0, 2), objective.price];
    if (targetValues.length === 0) return { valid: false, reason: 'INVALID_TARGET_DIRECTION' };
    candidate.tp1 = rawTextPacketRoundPrice(targetValues[0], precision);
    candidate.tp2 = targetValues[1] == null ? null : rawTextPacketRoundPrice(targetValues[1], precision);
    candidate.tp3 = targetValues[2] == null ? null : rawTextPacketRoundPrice(targetValues[2], precision);
    candidate.final_target_used = candidate.tp3 ?? candidate.tp2 ?? candidate.tp1;
    candidate.structural_objective = objective;
    const geometry = rawTextModelGeometry(candidate, direction, objective);
    if (!geometry.valid) return geometry;
    const path = build4HPathQualityAudit({ direction, entry: candidate.entry, stop_loss: candidate.stop_loss, tp1: candidate.tp1 }, pathRecords, asOfMs);
    if (!path.trade_qualified) return { valid: false, reason: 'ENTRY_INSIDE_OPPOSING_4H', path };
    Object.assign(candidate, {
        path_quality: path,
        path_evaluated: path.path_evaluated,
        path_status: path.path_status,
        path_quality_result: path.path_quality_result,
        clear_path_to_tp1: path.clear_path_to_tp1,
        path_quality_penalty: path.path_quality_penalty,
        qualification_blockers: path.qualification_blockers
    });
    const routed = {
        ...zoneMatch.record,
        candidate,
        path_quality: path,
        strategy_model: model.strategy_model,
        setup_class: model.setup_class,
        model_router: {
            qualified: true,
            strategy_model: model.strategy_model,
            setup_class: model.setup_class,
            htf_context: model.htf_context,
            msnr_ref: model.msnr?.ref || null,
            crt_ref: model.crt?.ref || null,
            tbs_ref: model.tbs?.ref || null,
            liquidity_ref: model.tbs?.liquidity_ref || model.crt?.ref || null,
            structure_ref: model.structure?.structure_event_id || null,
            displacement_ref: model.structure?.displacement_ref || null,
            entry_zone_ref: zoneMatch.zone.entry_zone_id,
            first_retrace: 'YES',
            objective_ref: objective.ref,
            objective_type: objective.type,
            objective_price: objective.price,
            blockers: [],
            chronology: model.chronology
        }
    };
    routed.current = buildRawTextCurrentOpportunityAssessment(routed, blocks, marketContext.current_price, marketContext, asOfMs, precision);
    routed.current_score = (Number(routed.score) || 0) + (routed.current.currentness || 0) + (routed.current.distance_penalty || 0);
    return { valid: true, record: routed };
}

function buildV2ModelRouter({ blocks = [], currentPrice = null, precision = 2, strategyAudits = {}, marketContext = {}, executionRecords = [], performanceCache = null } = {}) {
    const asOfMs = Number(strategyAudits.as_of_ms ?? marketContext.as_of_ms);
    const crtRecords = strategyAudits.crt_records || [];
    const tbsRecords = strategyAudits.tbs_records || [];
    const msnrRecords = strategyAudits.msnr_records || [];
    const supplyDemandRecords = strategyAudits.supply_demand_records || [];
    const pathRecords = [...supplyDemandRecords, ...msnrRecords, ...(strategyAudits.path_records || [])];
    const locationContexts = new Map();
    const diagnostics = {
        strategy_mode: 'MODEL_ROUTER',
        active_models: [],
        candidates_examined: executionRecords.length,
        qualified_candidates: 0,
        rejection_reasons: {},
        stage_counts: { contexts: 0, locations: 0, crt: 0, tbs: 0, msnr: 0, confirmations: 0, zones: 0, retracements: 0, candidates: 0 },
        models: {}
    };
    const reject = reason => { diagnostics.rejection_reasons[reason] = (diagnostics.rejection_reasons[reason] || 0) + 1; };
    const addModel = (model, direction, triggerTime) => {
        let htfContext = locationContexts.get(direction);
        if (!htfContext) {
            htfContext = rawTextModelLocationContext(blocks, direction, crtRecords, msnrRecords, supplyDemandRecords, marketContext, asOfMs);
            locationContexts.set(direction, htfContext);
        }
        diagnostics.stage_counts.contexts += htfContext.valid ? 1 : 0;
        diagnostics.stage_counts.locations += htfContext.location_records.length > 0 ? 1 : 0;
        if (!htfContext.valid) { reject('NO_HTF_CONTEXT'); return; }
        let structure = rawTextModelStructureEvents(blocks, direction, triggerTime, asOfMs, performanceCache).find(event => event.timeframe === '15M' || event.timeframe === '1H');
        // A CRT close-back is itself a deterministic confirmation candle when
        // the existing detector records that the post-reclaim move delivered
        // displacement/MSS.  Likewise, a confirmed TBS reclaim can be the
        // trigger for a later execution zone.  These are explicit model
        // confirmations; they are not a generic score bypass.
        if (!structure && model.crt?.event?.reclaim_time) {
            structure = {
                structure_event_id: rawTextModelStableId('CRT_CONFIRMATION', [model.crt.ref, direction]),
                type: 'CRT_RECLAIM',
                direction,
                timeframe: model.crt.timeframe,
                first_knowable_ms: triggerTime,
                break_price: Number(model.crt.event.reclaim_level),
                displacement_ref: null
            };
        }
        if (!structure && model.tbs?.status === 'CONFIRMED') {
            structure = {
                structure_event_id: rawTextModelStableId('TBS_CONFIRMATION', [model.tbs.ref, direction]),
                type: 'TBS_RECLAIM',
                direction,
                timeframe: model.tbs.timeframe,
                first_knowable_ms: triggerTime,
                break_price: Number(model.tbs.reference_price),
                displacement_ref: null
            };
        }
        if (!structure) { reject('NO_DIRECTIONAL_CONFIRMATION'); return; }
        diagnostics.stage_counts.confirmations += 1;
        const confirmationTime = Math.max(triggerTime, structure.first_knowable_ms);
        const zoneMatch = rawTextModelFindZone(executionRecords, direction, confirmationTime, asOfMs, htfContext, performanceCache);
        if (!zoneMatch) { reject('NO_CAUSAL_EXECUTION_ZONE'); return; }
        diagnostics.stage_counts.zones += 1;
        diagnostics.stage_counts.retracements += 1;
        const enriched = rawTextModelBuildCandidate({
            ...model,
            direction,
            structure,
            htf_context: htfContext.context_type,
            chronology: { trigger_time: triggerTime, confirmation_time: confirmationTime, zone_time: zoneMatch.zone.formation_time }
        }, zoneMatch, direction, blocks, { ...marketContext, current_price: currentPrice }, precision, pathRecords, asOfMs);
        if (!enriched.valid) { reject(enriched.reason || 'MODEL_CANDIDATE_INVALID'); return; }
        diagnostics.stage_counts.candidates += 1;
        diagnostics.models[model.strategy_model] = (diagnostics.models[model.strategy_model] || 0) + 1;
        return enriched.record;
    };
    const routed = [];
    const validCrt = crtRecords.filter(record => record.status === 'VALID' && record.detected !== false && rawTextModelDirection(record) && rawTextModelEventTime(record) <= asOfMs);
    const validTbs = tbsRecords.filter(record => record.status === 'CONFIRMED' && rawTextModelEventTime(record) <= asOfMs);
    const validMsnr = msnrRecords.filter(record => ['VALID', 'TESTED', 'FRESH'].includes(String(record.status).toUpperCase()) && rawTextModelDirection(record) && rawTextModelEventTime(record) <= asOfMs);
    diagnostics.stage_counts.crt = validCrt.length;
    diagnostics.stage_counts.tbs = validTbs.length;
    diagnostics.stage_counts.msnr = validMsnr.length;
    for (const crt of validCrt) {
        const direction = rawTextModelDirection(crt);
        const relatedTbs = validTbs.find(tbs => rawTextModelDirection(tbs) === direction && rawTextModelEventsMatch(crt, tbs));
        const triggerTime = rawTextModelEventTime(relatedTbs || crt);
        const common = { crt, tbs: relatedTbs || { ...crt.event, reference_type: 'CRT_BOUNDARY', sweep_extreme: crt.event?.sweep_extreme, liquidity_ref: crt.ref } };
        const first = addModel({ strategy_model: 'CRT_TBS', setup_class: 'CRT+TBS+EXECUTION_ZONE', ...common }, direction, triggerTime);
        if (first) routed.push(first);
        const second = addModel({ strategy_model: 'CRT_LTF_CONFIRMATION', setup_class: 'CRT+EXECUTION_ZONE', crt }, direction, triggerTime);
        if (second) routed.push(second);
    }
    for (const msnr of validMsnr) {
        const direction = rawTextModelDirection(msnr);
        const relatedTbs = validTbs.find(tbs => rawTextModelDirection(tbs) === direction && rawTextModelEventsMatch(msnr, tbs));
        const relatedCrt = validCrt.find(crt => rawTextModelDirection(crt) === direction && rawTextModelEventsMatch(msnr, crt));
        if (relatedCrt) {
            const record = addModel({ strategy_model: 'MSNR_CRT', setup_class: 'MSNR+CRT+EXECUTION_ZONE', msnr, crt: relatedCrt, tbs: null }, direction, Math.max(rawTextModelEventTime(msnr), rawTextModelEventTime(relatedCrt)));
            if (record) routed.push(record);
        }
        if (relatedTbs) {
            const record = addModel({ strategy_model: 'MSNR_TBS', setup_class: 'MSNR+TBS+EXECUTION_ZONE', msnr, tbs: relatedTbs }, direction, Math.max(rawTextModelEventTime(msnr), rawTextModelEventTime(relatedTbs)));
            if (record) routed.push(record);
        }
        const reaction = Number(msnr.level?.reaction_count ?? msnr.level?.reaction_strength ?? 0) > 0;
        if (reaction) {
            const record = addModel({ strategy_model: 'MSNR_REACTION', setup_class: 'MSNR+REACTION+EXECUTION_ZONE', msnr }, direction, rawTextModelEventTime(msnr));
            if (record) routed.push(record);
        }
        const confirmedRoleReversal = msnr.level?.flipped === true && msnr.level?.role_reversal_quality === 'CONFIRMED_RETEST';
        if (confirmedRoleReversal) {
            const record = addModel({ strategy_model: 'FLIP_BREAKER', setup_class: 'FLIP/BREAKER+EXECUTION_ZONE', msnr }, direction, rawTextModelEventTime(msnr));
            if (record) routed.push(record);
        }
        const single = relatedTbs ? null : addModel({ strategy_model: 'MSNR_SINGLE_MOVE', setup_class: 'MSNR+LIQUIDITY+EXECUTION_ZONE', msnr, tbs: relatedTbs }, direction, rawTextModelEventTime(msnr));
        if (single) routed.push(single);
    }
    const deduped = new Map();
    for (const record of routed) {
        const key = `${record.candidate.action}:${record.fvg?.c1}:${record.fvg?.c3}`;
        const previous = deduped.get(key);
        if (!previous || (record.current_score || 0) > (previous.current_score || 0) || String(record.strategy_model).localeCompare(String(previous.strategy_model)) < 0) deduped.set(key, record);
    }
    const records = [...deduped.values()].sort((left, right) => (right.current_score || 0) - (left.current_score || 0) || String(left.strategy_model).localeCompare(String(right.strategy_model)));
    diagnostics.qualified_candidates = records.length;
    diagnostics.active_models = [...new Set(records.map(record => record.strategy_model))].sort();
    if (records.length === 0) reject('NO_COMPLETE_MODEL');
    return { records, diagnostics };
}

function rawTextSupplyDemandConfluence(fvg, candidate, records = []) {
    const direction = candidate.action === 'BUY_LIMIT' ? 'BUY' : 'SELL';
    const lower = fvg.status === 'PARTIAL' ? Number(fvg.remaining_lower) : Number(fvg.lower);
    const upper = fvg.status === 'PARTIAL' ? Number(fvg.remaining_upper) : Number(fvg.upper);
    const eligible = records.filter(record => record.direction === direction
        && record.status !== 'INVALIDATED'
        && rawTextPacketTimestamp(record.first_knowable_ms) <= rawTextPacketTimestamp(fvg.c3)
        && rawTextIntervalsOverlap(lower, upper, Number(record.low), Number(record.high)));
    const supportingType = direction === 'BUY' ? 'DEMAND' : 'SUPPLY';
    const opposingType = direction === 'BUY' ? 'SUPPLY' : 'DEMAND';
    const supporting = eligible.filter(record => record.type === supportingType);
    const opposing = records.filter(record => record.type === opposingType
        && record.status !== 'INVALIDATED'
        && rawTextIntervalsOverlap(lower, upper, Number(record.low), Number(record.high)));
    const best = supporting.sort((left, right) => ({ FRESH: 3, TESTED: 2, MITIGATED: 1 }[right.status] || 0) - ({ FRESH: 3, TESTED: 2, MITIGATED: 1 }[left.status] || 0))[0] || null;
    const score = best ? best.status === 'FRESH' ? RAW_TEXT_HP_SCORE_WEIGHTS.SUPPLY_DEMAND : best.status === 'TESTED' ? Math.floor(RAW_TEXT_HP_SCORE_WEIGHTS.SUPPLY_DEMAND * 0.625) : Math.floor(RAW_TEXT_HP_SCORE_WEIGHTS.SUPPLY_DEMAND * 0.25) : 0;
    return { supporting, opposing, best, score, supporting_type: supportingType };
}

function rawTextPremiumDiscountScore(candidate, marketContext = {}) {
    const range = marketContext.dealing_range;
    if (!range || range.status !== 'VALID') return { score: 0, location: 'UNKNOWN' };
    const direction = candidate.action === 'BUY_LIMIT' ? 'BUY' : 'SELL';
    const increment = 10 ** -Number(marketContext.precision || 2);
    const location = Math.abs(Number(candidate.entry) - Number(range.equilibrium)) <= increment / 2
        ? 'EQUILIBRIUM'
        : Number(candidate.entry) < Number(range.equilibrium) ? 'DISCOUNT' : 'PREMIUM';
    const favorable = direction === 'BUY' ? location === 'DISCOUNT' : location === 'PREMIUM';
    return { score: location === 'EQUILIBRIUM' ? Math.floor(RAW_TEXT_HP_SCORE_WEIGHTS.PREMIUM_DISCOUNT / 3) : favorable ? RAW_TEXT_HP_SCORE_WEIGHTS.PREMIUM_DISCOUNT : 0, location };
}

function rawTextEmaScore(candidate, block, marketContext = {}) {
    const direction = candidate.action === 'BUY_LIMIT' ? 'BUY' : 'SELL';
    const expected = direction === 'BUY' ? 'BULLISH' : 'BEARISH';
    const state = marketContext.ema?.[block.timeframe]?.state;
    if (state === expected) return { score: RAW_TEXT_HP_SCORE_WEIGHTS.EMA, alignment: 'YES' };
    if (state && state !== 'MIXED' && state !== 'NA') return { score: Math.floor(RAW_TEXT_HP_SCORE_WEIGHTS.EMA / 2), alignment: 'PARTIAL' };
    return { score: 0, alignment: 'NO' };
}

function rawTextRsiScore(candidate, block, marketContext = {}) {
    const direction = candidate.action === 'BUY_LIMIT' ? 'BUY' : 'SELL';
    const value = Number(marketContext.rsi?.[block.timeframe]?.value);
    if (!Number.isFinite(value)) return { score: 0, context: 'UNKNOWN' };
    const directional = direction === 'BUY' ? value > 50 : value < 50;
    return { score: directional ? RAW_TEXT_HP_SCORE_WEIGHTS.RSI : 0, context: directional ? (direction === 'BUY' ? 'BULLISH' : 'BEARISH') : 'NEUTRAL' };
}

function rawTextScoreQuality(score) {
    if (score >= RAW_TEXT_HP_QUALITY_THRESHOLDS.A_PLUS) return 'A_PLUS';
    if (score >= RAW_TEXT_HP_QUALITY_THRESHOLDS.A) return 'A';
    if (score >= RAW_TEXT_HP_QUALITY_THRESHOLDS.B) return 'B';
    return 'LOW';
}

// 4H path quality is deliberately a small deterministic layer. It consumes
// only already-detected, closed-candle structure records; it does not create
// a second structure detector or reinterpret ordinary 1H/entry-timeframe
// opposition as a hard trade veto.
const FOUR_H_PATH_PENALTIES = Object.freeze({
    '0.00_0.25': -15,
    '0.25_0.50': -10,
    '0.50_0.75': -5,
    '0.75_1.00': -2,
    '1.00_PLUS': 0
});

function fourHPathRecordType(record = {}) {
    return String(record.type || record.zone_type || record.source_type || '').toUpperCase();
}

function fourHPathRecordTimeframe(record = {}) {
    return String(record.timeframe || record.zone_timeframe || record.setup_timeframe || '').toUpperCase();
}

function fourHPathRecordRef(record = {}) {
    return record.ref || record.id || record.location_id || record.evidence_id || null;
}

function fourHPathRecordActive(record = {}, asOfMs = null) {
    if (!record || fourHPathRecordTimeframe(record) !== '4H') return false;
    if (record.invalidated === true || record.consumed === true || record.expired === true || record.superseded === true) return false;
    const state = String(record.status || record.freshness || record.lifecycle_state || record.state || '').toUpperCase();
    if (['INVALIDATED', 'CONSUMED', 'SUPERSEDED', 'EXPIRED', 'USED'].includes(state)) return false;
    const firstKnowable = rawTextPacketTimestamp(record.first_knowable_ms ?? record.first_knowable_time ?? record.created_time ?? record.source_time ?? record.event_time);
    return !Number.isFinite(asOfMs) || !Number.isFinite(firstKnowable) || firstKnowable <= asOfMs;
}

function fourHPathZone(record = {}) {
    const low = Number(record.low ?? record.zone_low ?? record.range_low ?? record.entry_region_low);
    const high = Number(record.high ?? record.zone_high ?? record.range_high ?? record.entry_region_high);
    return Number.isFinite(low) && Number.isFinite(high) && high >= low ? { low, high } : null;
}

function fourHPathPenalty(distanceR, entryInside) {
    if (entryInside || !Number.isFinite(distanceR) || distanceR >= 1) return 0;
    if (distanceR <= 0.25) return FOUR_H_PATH_PENALTIES['0.00_0.25'];
    if (distanceR <= 0.5) return FOUR_H_PATH_PENALTIES['0.25_0.50'];
    if (distanceR <= 0.75) return FOUR_H_PATH_PENALTIES['0.50_0.75'];
    return FOUR_H_PATH_PENALTIES['0.75_1.00'];
}

function fourHPathDistanceBin(distanceR, entryInside) {
    if (entryInside) return 'ENTRY_INSIDE';
    if (!Number.isFinite(distanceR) || distanceR >= 1) return 'NO_BARRIER_OR_>=1R';
    if (distanceR <= 0.25) return '0-0.25R';
    if (distanceR <= 0.5) return '0.25-0.50R';
    if (distanceR <= 0.75) return '0.50-0.75R';
    return '0.75-1.00R';
}

function build4HPathQualityAudit(candidate = {}, structureRecords = [], asOfMs = null) {
    const direction = String(candidate.direction || (candidate.action === 'BUY_LIMIT' ? 'BUY' : candidate.action === 'SELL_LIMIT' ? 'SELL' : '')).toUpperCase();
    const entry = Number(candidate.entry);
    const stop = Number(candidate.stop_loss ?? candidate.stopLoss);
    const tp1 = Number(candidate.tp1 ?? candidate.take_profit_1);
    const risk = Math.abs(entry - stop);
    const opposingType = direction === 'BUY' ? 'SUPPLY' : direction === 'SELL' ? 'DEMAND' : null;
    const opposingDirection = direction === 'BUY' ? 'SELL' : direction === 'SELL' ? 'BUY' : null;
    const eligibleTypes = new Set([opposingType, 'MSNR', 'OB', 'BREAKER', 'FLIP'].filter(Boolean));
    const pathLow = Math.min(entry, tp1);
    const pathHigh = Math.max(entry, tp1);
    const records = [];
    const seen = new Set();
    for (const record of Array.isArray(structureRecords) ? structureRecords : []) {
        const type = fourHPathRecordType(record);
        if (!eligibleTypes.has(type) || !fourHPathRecordActive(record, asOfMs)) continue;
        if (type === 'MSNR' || ['OB', 'BREAKER', 'FLIP'].includes(type)) {
            if (opposingDirection && String(record.direction || '').toUpperCase() !== opposingDirection) continue;
        } else if (type === opposingType && record.direction && String(record.direction).toUpperCase() === direction) {
            continue;
        }
        const zone = fourHPathZone(record);
        if (!zone || zone.high < pathLow || zone.low > pathHigh) continue;
        const ref = fourHPathRecordRef(record) || `${type}:4H:${zone.low}-${zone.high}`;
        if (seen.has(ref)) continue;
        seen.add(ref);
        const entryInside = entry >= zone.low && entry <= zone.high;
        const firstEdge = entryInside
            ? entry
            : direction === 'BUY' ? zone.low : zone.high;
        const beforeTp1 = direction === 'BUY' ? firstEdge < tp1 : firstEdge > tp1;
        if (!entryInside && !beforeTp1) continue;
        const distance = entryInside ? 0 : Math.abs(firstEdge - entry);
        records.push({ record, type, ref, zone, entry_inside: entryInside, first_edge: firstEdge, distance });
    }
    records.sort((left, right) => left.distance - right.distance || String(left.ref).localeCompare(String(right.ref)));
    const nearest = records[0] || null;
    const entryInside = records.some(item => item.entry_inside);
    const barrierBeforeTp1 = records.length > 0;
    const distanceR = nearest && !entryInside && risk > 0 ? nearest.distance / risk : nearest && entryInside ? 0 : null;
    const penalty = fourHPathPenalty(distanceR, entryInside);
    const blockers = entryInside ? ['ENTRY_INSIDE_OPPOSING_4H'] : [];
    const pathEvaluated = Number.isFinite(entry) && Number.isFinite(stop) && Number.isFinite(tp1) && risk > 0;
    const pathStatus = !pathEvaluated ? 'INCOMPLETE' : entryInside ? 'BLOCKED' : barrierBeforeTp1 ? 'CONSTRAINED' : 'CLEAR';
    const pathQualityResult = !pathEvaluated ? 'INCOMPLETE' : entryInside ? 'FAIL' : barrierBeforeTp1 ? 'PASS_WITH_PENALTY' : 'PASS';
    return {
        entry_inside_opposing_4h: entryInside ? 'YES' : 'NO',
        opposing_4h_barrier_before_tp1: barrierBeforeTp1 ? 'YES' : 'NO',
        nearest_opposing_4h_ref: nearest?.ref || 'NONE',
        nearest_opposing_4h_type: nearest?.type || 'NONE',
        nearest_opposing_4h_zone: nearest ? `${nearest.zone.low}-${nearest.zone.high}` : 'NONE',
        barrier_distance_r: Number.isFinite(distanceR) ? Number(distanceR.toFixed(4)) : null,
        clear_path_to_tp1: barrierBeforeTp1 ? 'NO' : 'YES',
        path_evaluated: pathEvaluated ? 'YES' : 'NO',
        path_status: pathStatus,
        path_quality_result: pathQualityResult,
        path_quality_penalty: penalty,
        path_quality_distance_bin: fourHPathDistanceBin(distanceR, entryInside),
        trade_qualified: blockers.length === 0,
        qualification_blockers: blockers,
        risk: Number.isFinite(risk) ? risk : null
    };
}

function apply4HPathQualityToCandidate(candidate = {}, structureRecords = [], asOfMs = null) {
    const path = build4HPathQualityAudit(candidate, structureRecords, asOfMs);
    const existingBlockers = Array.isArray(candidate.qualification_blockers) ? candidate.qualification_blockers : [];
    const blockers = [...new Set([...existingBlockers, ...path.qualification_blockers])];
    const baseScore = Number(candidate.score);
    const nextScore = Number.isFinite(baseScore) ? Math.max(0, baseScore + path.path_quality_penalty) : candidate.score;
    return {
        ...candidate,
        entry_inside_opposing_4h: path.entry_inside_opposing_4h,
        opposing_4h_barrier_before_tp1: path.opposing_4h_barrier_before_tp1,
        nearest_opposing_4h_ref: path.nearest_opposing_4h_ref,
        nearest_opposing_4h_type: path.nearest_opposing_4h_type,
        nearest_opposing_4h_zone: path.nearest_opposing_4h_zone,
        barrier_distance_r: path.barrier_distance_r,
        clear_path_to_tp1: path.clear_path_to_tp1,
        path_evaluated: path.path_evaluated,
        path_status: path.path_status,
        path_quality_result: path.path_quality_result,
        path_quality_penalty: path.path_quality_penalty,
        trade_qualified: path.trade_qualified && candidate.trade_qualified !== false,
        qualification_blockers: blockers,
        score: Number.isFinite(nextScore) ? ictRound(nextScore, 2) : candidate.score,
        path_quality: path
    };
}

function buildRawTextHighProbabilityZones(blocks = [], currentPrice = null, precision = 2, strategyAudits = {}, marketContext = {}, roleAudit = {}, performanceCache = null) {
    const crtRecords = strategyAudits.crt_records || [];
    const msnrRecords = strategyAudits.msnr_records || [];
    const supplyDemandRecords = strategyAudits.supply_demand_records || [];
    const primaryBlocks = blocks.filter(block => RAW_TEXT_PRIMARY_SETUP_TIMEFRAMES.includes(block.timeframe));
    const blockKey = block => {
        const last = block?.candles?.at(-1);
        return `${block?.timeframe || ''}:${block?.candles?.length || 0}:${last?.t || last?.timestamp || ''}`;
    };
    const fvgCache = performanceCache?.fvgByBlock || null;
    const orderBlockCache = performanceCache?.orderBlocksByBlock || null;
    const staticRecordCache = performanceCache?.staticZoneRecords || null;
    const getFvgs = block => {
        const key = blockKey(block);
        if (fvgCache?.has(key)) return fvgCache.get(key);
        const value = detectRawTextFvgs(block.candles, block.timeframe);
        if (fvgCache) fvgCache.set(key, value);
        return value;
    };
    const getOrderBlocks = (block, direction) => {
        const key = `${blockKey(block)}:${direction}`;
        if (orderBlockCache?.has(key)) return orderBlockCache.get(key);
        const value = detectOrderBlocks(block.candles, direction);
        if (orderBlockCache) orderBlockCache.set(key, value);
        return value;
    };
    const allFvgs = blocks.flatMap(block => getFvgs(block).map(fvg => ({ fvg, block })));
    const records = [];
    for (const block of primaryBlocks) {
        for (const fvg of getFvgs(block)) {
            const staticKey = `${blockKey(block)}|${fvg.type}|${fvg.c1}|${fvg.c2}|${fvg.c3}|${fvg.lower}|${fvg.upper}|${fvg.status}|${fvg.remaining_lower}|${fvg.remaining_upper}`;
            let staticParts = staticRecordCache?.get(staticKey);
            if (!staticParts) {
                const zoneLow = fvg.status === 'PARTIAL' ? Number(fvg.remaining_lower) : Number(fvg.lower);
                const zoneHigh = fvg.status === 'PARTIAL' ? Number(fvg.remaining_upper) : Number(fvg.upper);
                const sentinel = fvg.type === 'BULLISH'
                    ? zoneHigh + Math.max(1, Math.abs(zoneHigh)) * 1000000
                    : zoneLow - Math.max(1, Math.abs(zoneLow)) * 1000000;
                const staticCandidate = buildRawTextFvgPendingCandidate(fvg, sentinel, precision);
                if (!staticCandidate) continue;
                const direction = staticCandidate.action === 'BUY_LIMIT' ? 'BUY' : 'SELL';
                const confluence = rawTextFvgConfluence(fvg, staticCandidate, crtRecords, msnrRecords);
                const obEvidence = (getOrderBlocks(block, direction) || []).filter(ob => {
                    const firstKnowableMs = rawTextPacketTimestamp(ob.first_knowable_time ?? ob.confirmation_time ?? ob.formation_time);
                    const fvgKnowableMs = rawTextPacketTimestamp(fvg.c3);
                    const lifecycle = checkZoneFreshness(block.candles, {
                        low: Number(ob.low), high: Number(ob.high), source_candle_index: ob.formation_index,
                        source_time: ob.first_knowable_time
                    }, direction);
                    return Number.isFinite(firstKnowableMs) && Number.isFinite(fvgKnowableMs)
                        && firstKnowableMs <= fvgKnowableMs
                        && rawTextIntervalsOverlap(zoneLow, zoneHigh, Number(ob.low), Number(ob.high))
                        && lifecycle.fresh;
                });
                const displacement = rawTextDisplacementAssessment(block, fvg, direction);
                const supplyDemand = rawTextSupplyDemandConfluence(fvg, staticCandidate, supplyDemandRecords);
                const pathQuality = build4HPathQualityAudit({ direction, entry: staticCandidate.entry, stop_loss: staticCandidate.stop_loss, tp1: staticCandidate.tp1 }, [
                    ...supplyDemandRecords,
                    ...msnrRecords,
                    ...(strategyAudits.path_records || [])
                ], marketContext.as_of_ms);
                const opposingFvg = allFvgs.some(item => item.fvg !== fvg
                    && item.fvg.status !== 'FULLY_TRAVERSED'
                    && item.fvg.type !== fvg.type
                    && rawTextIntervalsOverlap(zoneLow, zoneHigh, Number(item.fvg.lower), Number(item.fvg.upper)));
                const opposingStructure = [...crtRecords, ...msnrRecords].some(record => record.status === 'VALID'
                    && record.direction !== direction
                    && rawTextIntervalsOverlap(zoneLow, zoneHigh, Number(record.range_low ?? record.zone_low), Number(record.range_high ?? record.zone_high)));
                staticParts = { candidate: staticCandidate, confluence, obEvidence, displacement, supplyDemand, pathQuality, opposingFvg, opposingStructure };
                if (staticRecordCache) staticRecordCache.set(staticKey, staticParts);
            }
            const candidate = (fvg.type === 'BULLISH' ? Number(currentPrice) > Number(fvg.status === 'PARTIAL' ? fvg.remaining_upper : fvg.upper) : Number(currentPrice) < Number(fvg.status === 'PARTIAL' ? fvg.remaining_lower : fvg.lower))
                ? staticParts.candidate : null;
            if (!candidate) continue;
            const deliveryCandles = buildRawTextCrossTimeframeDeliveryCandles(fvg, block, blocks, marketContext.as_of_ms);
            const delivery = buildRawTextFvgDeliveryAssessment(fvg, candidate, block.candles, currentPrice, precision, deliveryCandles.length ? deliveryCandles : null);
            const confluence = staticParts.confluence;
            const direction = candidate.action === 'BUY_LIMIT' ? 'BUY' : 'SELL';
            const obEvidence = staticParts.obEvidence;
            const dailyBias = ['BULLISH', 'BEARISH'].includes(roleAudit.daily_bias || marketContext.daily_bias)
                ? (roleAudit.daily_bias || marketContext.daily_bias) : 'NEUTRAL';
            const daily = dailyBias === 'NEUTRAL' ? RAW_TEXT_HP_SCORE_WEIGHTS.DAILY / 2 : dailyBias === (direction === 'BUY' ? 'BULLISH' : 'BEARISH') ? RAW_TEXT_HP_SCORE_WEIGHTS.DAILY : 0;
            const primary = block.timeframe === '4H' ? RAW_TEXT_HP_SCORE_WEIGHTS.PRIMARY : Math.floor(RAW_TEXT_HP_SCORE_WEIGHTS.PRIMARY * 0.75);
            const crt = confluence.crt.length ? RAW_TEXT_HP_SCORE_WEIGHTS.CRT : 0;
            const msnr = confluence.msnr.length ? RAW_TEXT_HP_SCORE_WEIGHTS.MSNR : 0;
            const ob = obEvidence.length ? RAW_TEXT_HP_SCORE_WEIGHTS.OB : 0;
            const displacement = staticParts.displacement;
            const fvgScore = (fvg.status === 'UNTOUCHED' ? RAW_TEXT_HP_SCORE_WEIGHTS.FVG - 2 : RAW_TEXT_HP_SCORE_WEIGHTS.FVG - 4) + (displacement.score >= 5 ? 2 : displacement.score >= 3 ? 1 : 0);
            const freshness = delivery.delivery_status === 'FRESH' ? RAW_TEXT_HP_SCORE_WEIGHTS.FRESH : delivery.delivery_status === 'DELIVERED_TP1' ? Math.floor(RAW_TEXT_HP_SCORE_WEIGHTS.FRESH * 0.4) : 0;
            const execution = rawTextExecutionSupport({ fvg, candidate }, blocks, crtRecords, msnrRecords);
            const atrValue = block.timeframe === '4H' ? Number(marketContext.atr_4h) : Number(marketContext.atr_1h);
            const riskToAtr = atrValue > 0 ? Number(candidate.risk) / atrValue : null;
            const volatility = riskToAtr == null ? 0 : riskToAtr >= 0.5 ? RAW_TEXT_HP_SCORE_WEIGHTS.VOL : riskToAtr >= 0.25 ? Math.floor(RAW_TEXT_HP_SCORE_WEIGHTS.VOL / 2) : 0;
            const sessionLiquidity = Object.values(marketContext.session_levels || {}).map(level => direction === 'BUY' ? level.high : level.low);
            const levelForLiquidity = direction === 'BUY'
                ? [marketContext.pdh, marketContext.pwh, ...sessionLiquidity]
                : [marketContext.pdl, marketContext.pwl, ...sessionLiquidity];
            const liquidity = levelForLiquidity.some(level => Number.isFinite(Number(level)) && (direction === 'BUY' ? Number(level) > candidate.entry : Number(level) < candidate.entry)) ? 5 : 0;
            const supplyDemand = staticParts.supplyDemand;
            const premiumDiscount = rawTextPremiumDiscountScore(candidate, marketContext);
            const emaContext = rawTextEmaScore(candidate, block, marketContext);
            const rsiContext = rawTextRsiScore(candidate, block, marketContext);
            const candidateLow = fvg.status === 'PARTIAL' ? Number(fvg.remaining_lower) : Number(fvg.lower);
            const candidateHigh = fvg.status === 'PARTIAL' ? Number(fvg.remaining_upper) : Number(fvg.upper);
            const opposingFvg = staticParts.opposingFvg;
            const opposingStructure = staticParts.opposingStructure;
            const opposingZone = supplyDemand.opposing.length > 0;
            const conflict = (opposingFvg ? -5 : 0) + (opposingStructure ? -5 : 0) + (opposingZone ? -5 : 0);
            const breakdown = {
                DAILY: daily, PRIMARY: primary, CRT: crt, MSNR: msnr, OB: ob, FVG: fvgScore,
                FRESH: freshness, SUPPLY_DEMAND: supplyDemand.score, EXEC: execution.score,
                LIQUIDITY: liquidity, VOL: volatility, PREMIUM_DISCOUNT: premiumDiscount.score,
                EMA: emaContext.score, RSI: rsiContext.score, CONFLICT: conflict
            };
            const total = Object.values(breakdown).reduce((sum, value) => sum + value, 0);
            const pathQuality = staticParts.pathQuality;
            const pathBreakdown = { ...breakdown, PATH_QUALITY: pathQuality.path_quality_penalty };
            const score = Math.max(0, Math.min(100, Math.round(total + pathQuality.path_quality_penalty)));
            const record = { fvg, block, candidate, delivery, confluence, obEvidence, supplyDemand, execution, displacement, premiumDiscount, emaContext, rsiContext, score, raw_score: total + pathQuality.path_quality_penalty, quality: rawTextScoreQuality(score), breakdown: pathBreakdown, path_quality: pathQuality,
                daily_aligned: dailyBias === 'NEUTRAL' ? 'NEUTRAL' : dailyBias === (direction === 'BUY' ? 'BULLISH' : 'BEARISH') ? 'YES' : 'NO' };
            record.current = buildRawTextCurrentOpportunityAssessment(record, blocks, currentPrice, marketContext, marketContext.as_of_ms, precision);
            record.current_score = Math.max(0, Math.min(100, Math.round(score + record.current.currentness + record.current.distance_penalty)));
            records.push(record);
        }
    }
    const legacyRecords = records.slice();
    let modelRouterDiagnostics = null;
    if (rawTextV2StrategyMode(strategyAudits) === 'MODEL_ROUTER') {
        const routed = buildV2ModelRouter({
            blocks,
            currentPrice,
            precision,
            strategyAudits,
            marketContext,
            executionRecords: legacyRecords,
            performanceCache
        });
        modelRouterDiagnostics = routed.diagnostics;
        records.splice(0, records.length, ...routed.records);
    }
    records.sort((left, right) => right.score - left.score || (right.confluence.crt.length + right.confluence.msnr.length) - (left.confluence.crt.length + left.confluence.msnr.length));
    const ranked = records.slice(0, 3).map((record, index) => ({ ...record, rank: index + 1 }));
    const lines = ranked.length ? ranked.map(record => {
        const { fvg, candidate, block, delivery, confluence, obEvidence, supplyDemand, execution, displacement, premiumDiscount, emaContext, rsiContext, score, quality, breakdown } = record;
        const zoneLow = fvg.status === 'PARTIAL' ? fvg.remaining_lower : fvg.lower;
        const zoneHigh = fvg.status === 'PARTIAL' ? fvg.remaining_upper : fvg.upper;
        const breakdownText = Object.entries(breakdown).map(([key, value]) => key + ':' + value).join(',');
        return [
            'HP_ZONE: RANK=' + record.rank,
            'SIDE=' + (candidate.action === 'BUY_LIMIT' ? 'BUY' : 'SELL'),
            'PRIMARY_TF=' + block.timeframe.toLowerCase(),
            'ZONE=' + rawTextPacketFormatNumber(zoneLow, precision) + '-' + rawTextPacketFormatNumber(zoneHigh, precision),
            'ENTRY=' + rawTextPacketFormatNumber(candidate.entry, precision),
            'STOP=' + rawTextPacketFormatNumber(candidate.stop_loss, precision),
            'TP1=' + rawTextPacketFormatNumber(candidate.tp1, precision),
            'TP2=' + rawTextPacketFormatNumber(candidate.tp2, precision),
            'TP3=' + rawTextPacketFormatNumber(candidate.tp3, precision),
            'FVG_C1=' + fvg.c1,
            'FVG_C2=' + fvg.c2,
            'FVG_C3=' + fvg.c3,
            'FVG_ZONE=' + rawTextPacketFormatNumber(zoneLow, precision) + '-' + rawTextPacketFormatNumber(zoneHigh, precision),
            'SCORE=' + score,
            'QUALITY=' + quality,
            'STRUCTURALLY_VALID=YES',
            'TRADE_QUALIFIED=' + (record.path_quality.trade_qualified ? 'YES' : 'NO'),
            'ENTRY_INSIDE_OPPOSING_4H=' + record.path_quality.entry_inside_opposing_4h,
            'OPPOSING_4H_BARRIER_BEFORE_TP1=' + record.path_quality.opposing_4h_barrier_before_tp1,
            'NEAREST_OPPOSING_4H_REF=' + record.path_quality.nearest_opposing_4h_ref,
            'NEAREST_OPPOSING_4H_TYPE=' + record.path_quality.nearest_opposing_4h_type,
            'NEAREST_OPPOSING_4H_ZONE=' + record.path_quality.nearest_opposing_4h_zone,
            'BARRIER_DISTANCE_R=' + rawTextPacketFormatNumber(record.path_quality.barrier_distance_r, 4),
            'CLEAR_PATH_TO_TP1=' + record.path_quality.clear_path_to_tp1,
            'PATH_QUALITY_PENALTY=' + record.path_quality.path_quality_penalty,
            'QUALIFICATION_BLOCKERS=' + (record.path_quality.qualification_blockers.join('|') || 'NONE'),
            'CURRENT_OPPORTUNITY=' + (record.current.current_opportunity ? 'YES' : 'NO'),
            'TODAY_OPPORTUNITY=' + (record.current.today_opportunity ? 'YES' : 'NO'),
            'OPPORTUNITY_STATUS=' + record.current.opportunity_status,
            'ENTRY_DISTANCE=' + rawTextPacketFormatNumber(record.current.entry_distance, precision),
            'ENTRY_DISTANCE_ATR=' + rawTextPacketFormatNumber(record.current.entry_distance_atr, 2),
            'APPROACH_STATE=' + record.current.approach_state,
            'FORMATION_AGE_HOURS=' + rawTextPacketFormatNumber(record.current.formation_age_hours, 2),
            'FORMATION_AGE_PRIMARY_BARS=' + rawTextPacketFormatNumber(record.current.formation_age_primary_bars, 2),
            'STATUS=STRUCTURAL_CANDIDATE',
            'STRATEGY_MODEL=' + (record.strategy_model || 'LEGACY_FVG'),
            'SETUP_CLASS=' + (record.setup_class || 'FVG'),
            'MODEL_QUALIFIED=' + (record.model_router?.qualified ? 'YES' : 'NO'),
            'DAILY_ALIGN=' + record.daily_aligned,
            'CRT=' + (confluence.crt.length ? 'YES' : 'NO'),
            'MSNR=' + (confluence.msnr.length ? 'YES' : 'NO'),
            ...(confluence.crt.length ? ['CRT_TF=' + confluence.crt[0].timeframe.toLowerCase(), 'CRT_REF=' + confluence.crt[0].ref] : []),
            ...(confluence.msnr.length ? ['MSNR_TF=' + confluence.msnr[0].timeframe.toLowerCase(), 'MSNR_REF=' + confluence.msnr[0].ref] : []),
            'OB=' + (obEvidence.length ? 'YES' : 'NO'),
            'SUPPLY=' + (supplyDemand.supporting_type === 'SUPPLY' && supplyDemand.best ? 'YES' : 'NO'),
            'DEMAND=' + (supplyDemand.supporting_type === 'DEMAND' && supplyDemand.best ? 'YES' : 'NO'),
            'PREMIUM_DISCOUNT=' + premiumDiscount.location,
            'EMA_ALIGN=' + emaContext.alignment,
            'RSI_CONTEXT=' + rsiContext.context,
            'FVG=YES',
            'EXEC_15M=' + execution.exec_15m,
            'EXEC_5M=' + execution.exec_5m,
            'FRESHNESS=' + delivery.delivery_status,
            'DISPLACEMENT=' + displacement.label,
            'SCORE_BREAKDOWN=' + breakdownText + ' RAW_TOTAL=' + rawTextPacketFormatNumber(record.raw_score, 0)
        ].join(' ');
    }) : ['NONE'];
    const currentRecords = records
        .filter(record => record.current.current_opportunity && record.path_quality.trade_qualified)
        .sort((left, right) => right.current_score - left.current_score || right.score - left.score)
        .slice(0, 3)
        .map((record, index) => ({ ...record, current_rank: index + 1 }));
    const currentLines = currentRecords.length ? currentRecords.map(record => [
        'CURRENT_OPPORTUNITY: RANK=' + record.current_rank,
        'SIDE=' + (record.candidate.action === 'BUY_LIMIT' ? 'BUY' : 'SELL'),
        'PRIMARY_TF=' + record.block.timeframe.toLowerCase(),
        'FVG_C1=' + record.fvg.c1,
        'FVG_C2=' + record.fvg.c2,
        'FVG_C3=' + record.fvg.c3,
        'FVG_ZONE=' + rawTextPacketFormatNumber(record.fvg.status === 'PARTIAL' ? record.fvg.remaining_lower : record.fvg.lower, precision) + '-' + rawTextPacketFormatNumber(record.fvg.status === 'PARTIAL' ? record.fvg.remaining_upper : record.fvg.upper, precision),
        'ENTRY=' + rawTextPacketFormatNumber(record.candidate.entry, precision),
        'STOP=' + rawTextPacketFormatNumber(record.candidate.stop_loss, precision),
        'TP1=' + rawTextPacketFormatNumber(record.candidate.tp1, precision),
        'TP2=' + rawTextPacketFormatNumber(record.candidate.tp2, precision),
        'TP3=' + rawTextPacketFormatNumber(record.candidate.tp3, precision),
        'SCORE=' + record.current_score,
        'QUALITY=' + rawTextScoreQuality(record.current_score),
        'TRADE_QUALIFIED=' + (record.path_quality.trade_qualified ? 'YES' : 'NO'),
        'ENTRY_INSIDE_OPPOSING_4H=' + record.path_quality.entry_inside_opposing_4h,
        'OPPOSING_4H_BARRIER_BEFORE_TP1=' + record.path_quality.opposing_4h_barrier_before_tp1,
        'NEAREST_OPPOSING_4H_REF=' + record.path_quality.nearest_opposing_4h_ref,
        'NEAREST_OPPOSING_4H_TYPE=' + record.path_quality.nearest_opposing_4h_type,
        'NEAREST_OPPOSING_4H_ZONE=' + record.path_quality.nearest_opposing_4h_zone,
        'BARRIER_DISTANCE_R=' + rawTextPacketFormatNumber(record.path_quality.barrier_distance_r, 4),
        'CLEAR_PATH_TO_TP1=' + record.path_quality.clear_path_to_tp1,
        'PATH_QUALITY_PENALTY=' + record.path_quality.path_quality_penalty,
        'QUALIFICATION_BLOCKERS=' + (record.path_quality.qualification_blockers.join('|') || 'NONE'),
        'CURRENT_STATUS=' + record.current.opportunity_status,
        'TODAY_OPPORTUNITY=YES',
        'CRT_CONFLUENCE=' + (record.confluence.crt.length ? 'YES' : 'NO'),
        ...(record.confluence.crt.length ? ['CRT_TF=' + record.confluence.crt[0].timeframe.toLowerCase(), 'CRT_REF=' + record.confluence.crt[0].ref] : []),
        'MSNR_CONFLUENCE=' + (record.confluence.msnr.length ? 'YES' : 'NO'),
        ...(record.confluence.msnr.length ? ['MSNR_TF=' + record.confluence.msnr[0].timeframe.toLowerCase(), 'MSNR_REF=' + record.confluence.msnr[0].ref] : []),
        'ENTRY_DISTANCE=' + rawTextPacketFormatNumber(record.current.entry_distance, precision),
        'ENTRY_DISTANCE_ATR=' + rawTextPacketFormatNumber(record.current.entry_distance_atr, 2),
        'APPROACH_STATE=' + record.current.approach_state,
        'FRESHNESS=' + record.delivery.delivery_status
        , 'STRATEGY_MODEL=' + (record.strategy_model || 'LEGACY_FVG')
        , 'SETUP_CLASS=' + (record.setup_class || 'FVG')
        , 'MODEL_QUALIFIED=' + (record.model_router?.qualified ? 'YES' : 'NO')
    ].join(' ')) : ['CURRENT_OPPORTUNITIES=NONE'];
    // Keep the compact live output capped at three zones, while exposing the
    // same deterministic records to internal research consumers. This does
    // not change packet rendering or candidate selection.
    const allRecords = rawTextV2StrategyMode(strategyAudits) === 'MODEL_ROUTER'
        ? legacyRecords.map(record => ({ ...record, model_router: record.model_router || { qualified: false, blockers: ['NO_COMPLETE_MODEL'] } }))
        : records;
    return {
        records: ranked,
        all_records: allRecords,
        current_records: currentRecords,
        lines,
        current_lines: currentLines,
        strategy_mode: rawTextV2StrategyMode(strategyAudits),
        model_router: modelRouterDiagnostics
    };
}

function buildRawTextFvgAudit(blocks = [], currentPrice = null, precision = 2, strategyAudits = {}) {
    const records = [];
    const crtRecords = strategyAudits.crt_records || [];
    const msnrRecords = strategyAudits.msnr_records || [];
    for (const block of blocks) {
        const fvgs = detectRawTextFvgs(block.candles, block.timeframe);
        const recentFullCutoff = Math.max(0, block.candles.length - 13);
        for (const fvg of fvgs) {
            if (fvg.status === 'FULLY_TRAVERSED' && fvg.formation_index < recentFullCutoff) continue;
            const candidate = buildRawTextFvgPendingCandidate(fvg, currentPrice, precision);
            const parts = [
                'FVG: TF=' + fvg.timeframe.toLowerCase(),
                'TYPE=' + fvg.type,
                'C1=' + new Date(rawTextPacketTimestamp(fvg.c1)).toISOString(),
                'C2=' + new Date(rawTextPacketTimestamp(fvg.c2)).toISOString(),
                'C3=' + new Date(rawTextPacketTimestamp(fvg.c3)).toISOString(),
                'ZONE=' + rawTextPacketFormatNumber(fvg.lower, precision) + '-' + rawTextPacketFormatNumber(fvg.upper, precision),
                'STATUS=' + fvg.status
            ];
            if (fvg.type === 'BULLISH' && fvg.min_later_low != null) {
                parts.push('MIN_LATER_LOW=' + rawTextPacketFormatNumber(fvg.min_later_low, precision));
            }
            if (fvg.type === 'BEARISH' && fvg.max_later_high != null) {
                parts.push('MAX_LATER_HIGH=' + rawTextPacketFormatNumber(fvg.max_later_high, precision));
            }
            if (fvg.status === 'PARTIAL') {
                parts.push('GEOMETRIC_REMAINING_ZONE=' + rawTextPacketFormatNumber(fvg.remaining_lower, precision) + '-' + rawTextPacketFormatNumber(fvg.remaining_upper, precision));
            }
            if (candidate) {
                const deliveryCandles = buildRawTextCrossTimeframeDeliveryCandles(fvg, block, blocks, strategyAudits.as_of_ms);
                const delivery = buildRawTextFvgDeliveryAssessment(fvg, candidate, block.candles, currentPrice, precision, deliveryCandles.length ? deliveryCandles : null);
                const primarySetupTimeframe = RAW_TEXT_PRIMARY_SETUP_TIMEFRAMES.includes(block.timeframe);
                parts.push(
                    'ENTRY_STATE=' + delivery.entry_state,
                    'DELIVERY_STATUS=' + delivery.delivery_status,
                    'PRE_ENTRY_PROGRESS=' + (delivery.pre_entry_progress == null ? '' : rawTextPacketFormatNumber(delivery.pre_entry_progress, 2)) + '%',
                    'PRIMARY_SETUP_TF=' + (primarySetupTimeframe ? 'YES' : 'NO')
                );
                if (fvg.type === 'BULLISH' && delivery.pre_entry_max_high != null) {
                    parts.push('PRE_ENTRY_MAX_HIGH=' + rawTextPacketFormatNumber(delivery.pre_entry_max_high, precision));
                }
                if (fvg.type === 'BEARISH' && delivery.pre_entry_min_low != null) {
                    parts.push('PRE_ENTRY_MIN_LOW=' + rawTextPacketFormatNumber(delivery.pre_entry_min_low, precision));
                }
                const confluence = rawTextFvgConfluence(fvg, candidate, crtRecords, msnrRecords);
                parts.push('CRT_CONFLUENCE=' + (confluence.crt.length ? 'YES' : 'NO'));
                if (confluence.crt.length) {
                    parts.push('CRT_TF=' + confluence.crt[0].timeframe.toLowerCase(), 'CRT_REF=' + confluence.crt[0].ref);
                }
                parts.push('MSNR_CONFLUENCE=' + (confluence.msnr.length ? 'YES' : 'NO'));
                if (confluence.msnr.length) {
                    parts.push('MSNR_TF=' + confluence.msnr[0].timeframe.toLowerCase(), 'MSNR_REF=' + confluence.msnr[0].ref);
                }
                if (delivery.recommendation_eligible && primarySetupTimeframe) {
                    parts.push(
                        'PENDING_CANDIDATE=' + candidate.action,
                        'ENTRY=' + rawTextPacketFormatNumber(candidate.entry, precision),
                        'STOP_LOSS=' + rawTextPacketFormatNumber(candidate.stop_loss, precision),
                        'TP1=' + rawTextPacketFormatNumber(candidate.tp1, precision),
                        'TP2=' + rawTextPacketFormatNumber(candidate.tp2, precision),
                        'TP3=' + rawTextPacketFormatNumber(candidate.tp3, precision),
                        'R=' + rawTextPacketFormatNumber(candidate.risk, precision)
                    );
                } else {
                    parts.push('PENDING_CANDIDATE=' + (primarySetupTimeframe ? 'NOT_SELECTABLE' : 'NOT_PRIMARY_SELECTABLE'));
                }
            }
            parts.push(
                'CURRENT_PRICE=' + rawTextPacketFormatNumber(currentPrice, precision),
                'CURRENT_PRICE_RELATION=' + rawTextFvgCurrentPriceRelation(fvg, currentPrice)
            );
            records.push(parts.join(' '));
        }
    }
    return records;
}

function buildRawCandleAiDailyBias(candles = []) {
    const last = candles.at(-1) || null;
    const previous = candles.at(-2) || null;
    const third = candles.at(-3) || null;
    const reason = 'LAST_3_CLOSED_DAILY_STRUCTURE_SEE_SECTION_L';
    if (!last || !previous || !third) {
        return { bias: 'NEUTRAL', reason, last, previous, third };
    }
    const high1 = Number(last.h);
    const high3 = Number(third.h);
    const low1 = Number(last.l);
    const low3 = Number(third.l);
    let bias = 'NEUTRAL';
    if ([high1, high3, low1, low3].every(Number.isFinite)) {
        if (high1 > high3 && low1 > low3) bias = 'BULLISH';
        else if (high1 < high3 && low1 < low3) bias = 'BEARISH';
    }
    return { bias, reason, last, previous, third };
}

function rawCandleAiCandleLimit(timeframe) {
    return RAW_CANDLE_AI_CANDLE_LIMITS[timeframe] || 50;
}

function rawCandleAiLimitSummary() {
    return RAW_CANDLE_AI_TIMEFRAMES
        .map(timeframe => timeframe + ':' + rawCandleAiCandleLimit(timeframe))
        .join(',');
}

function rawCandleAiLevel(value) {
    const number = Number(value);
    return Number.isFinite(number) ? number : null;
}

function buildRawCandleAiMacroLevels(source = {}, asOfMs = Date.now()) {
    const daily = rawTextPacketClosedCandles(source, '1D', asOfMs);
    const hourly = rawTextPacketClosedCandles(source, '1H', asOfMs);
    const previousDay = daily.at(-1) || null;
    let previousDayHigh = rawCandleAiLevel(previousDay?.h);
    let previousDayLow = rawCandleAiLevel(previousDay?.l);
    let previousDaySource = previousDayHigh != null && previousDayLow != null ? 'CLOSED_1D' : 'UNAVAILABLE';
    if (previousDayHigh == null || previousDayLow == null) {
        const groups = rawTextPeriodGroups(hourly, rawTextUtcDayKey, asOfMs);
        const currentDay = rawTextUtcDayKey(asOfMs);
        const completedDays = [...groups.keys()].filter(day => day && day < currentDay).sort();
        const stats = rawTextPeriodStats(groups.get(completedDays.at(-1)) || []);
        previousDayHigh = rawCandleAiLevel(stats?.high);
        previousDayLow = rawCandleAiLevel(stats?.low);
        previousDaySource = previousDayHigh != null && previousDayLow != null ? 'CLOSED_1H_DAY_GROUPS' : 'UNAVAILABLE';
    }
    const sessions = buildRawTextSessionLevels(hourly, asOfMs, 2);
    return {
        previous_day_high: previousDayHigh,
        previous_day_low: previousDayLow,
        asia_high: rawCandleAiLevel(sessions.ASIA?.high),
        asia_low: rawCandleAiLevel(sessions.ASIA?.low),
        london_high: rawCandleAiLevel(sessions.LONDON?.high),
        london_low: rawCandleAiLevel(sessions.LONDON?.low),
        new_york_high: rawCandleAiLevel(sessions.NY?.high),
        new_york_low: rawCandleAiLevel(sessions.NY?.low),
        previous_day_source: previousDaySource
    };
}

function buildRawCandleAiCsvLines(source = {}, timeframe, asOfMs = Date.now(), precision = 2) {
    const limit = rawCandleAiCandleLimit(timeframe);
    const candles = rawTextPacketClosedCandles(source, timeframe, asOfMs).slice(-limit);
    const lines = [
        '======== TIMEFRAME: ' + timeframe.toLowerCase() + ' ========',
        'CANDLE_COUNT=' + String(candles.length),
        'CANDLE_LIMIT=' + String(limit),
        'CANDLE_POLICY=CLOSED_ONLY',
        'FORMAT: time,open,high,low,close,volume'
    ];
    for (const candle of candles) {
        const timestamp = rawTextPacketTimestamp(candle.t ?? candle.time ?? candle.timestamp);
        const volumeValue = Number(candle.v ?? candle.volume);
        lines.push([
            Number.isFinite(timestamp) ? new Date(timestamp).toISOString() : '',
            rawTextPacketFormatNumber(candle.o, precision),
            rawTextPacketFormatNumber(candle.h, precision),
            rawTextPacketFormatNumber(candle.l, precision),
            rawTextPacketFormatNumber(candle.c, precision),
            Number.isFinite(volumeValue) ? String(volumeValue) : ''
        ].join(','));
    }
    lines.push('======== END ' + timeframe.toLowerCase() + ' ========');
    return lines;
}

function buildRawCandleAiGhostRules() {
    return `=== GHOST MACHINE STRATEGY RULES === V2.7.1 (DEEPSEEK JSON)
You are the Ghost Machine. Read the raw closed candles yourself. No deterministic POI, FVG, order-block, MSNR, supply/demand zone or candidate list is supplied or authoritative. Deterministic macro liquidity levels are supplied only as context.
UNIVERSE: use only the CSV candles in this packet. Never invent a candle, price, timestamp, volume or level.
MACRO CONTEXT: DAILY_BIAS, daily OHLC, PDH/PDL and completed session highs/lows are context only. The raw 1D/4H candles own higher-timeframe structure; 1H/15M/5M own intraday formation and execution.

=== DEEPSEEK REASONING PROTOCOL (READ FIRST) ===
You are running in THINK MODE. Follow this exact sequence:

STEP 1. Derive the Section L bias from the last three contiguous closed 1D candles.
STEP 2. Identify the last completed 4H MSS.
STEP 3. Scan all five timeframes for BOTH bullish and bearish sweeps.
STEP 4. Separate BREAKDOWNS, BREAKOUTS, FAILED BREAKDOWNS, FAILED BREAKOUTS from the sweep list.
STEP 5. Compute the killzone from SERVER_TIME_UTC. IF THE KILLZONE IS OUTSIDE (NONE), YOU MUST RETURN NO_TRADE. No Asian session trades.
STEP 6. READ THE CURRENT INTRADAY CONTEXT: Look at the most recent 1H and 15M candles. Is price currently TRENDING, RANGING, or CONSOLIDATING?
STEP 7. Construct the candidate for TODAY'S session: OB body, entry, stop, TP1/TP2/TP3.
        You MUST align this setup with the current context from STEP 6.
        HIGH-PROBABILITY FILTER: Prioritize zones where the HTF Candle Range (CRT)
        sweep, the MSNR retail trap, and the 1H/15M Order Block all overlap.
        Focus on capturing the immediate intraday liquidity pools (session highs/lows, PDH/PDL). Do not force a multi-day target if a 1H/15M pool is closer.
STEP 8. VERIFY ARITHMETIC TWICE. Relocate TP1 if body-broken. RR must be >= 2.00.
STEP 9. Emit the JSON object.

The JSON object is the only permitted output.

=== SECTION L: DAILY BIAS ===
The 1D block is ordered oldest-to-newest. D1 = the LAST row. D2 = the row
immediately above D1. D3 = the row immediately above D2. D1, D2, D3 are
CONTIGUOUS - no rows between them may be skipped.

  BULLISH  iff  D1.high > D3.high AND D1.low > D3.low
  BEARISH  iff  D1.high < D3.high AND D1.low < D3.low
  RANGE    otherwise

4H MSS tiebreaker: identify the last completed 4H body-close break of a named
4H swing high or low. If that MSS agrees with Section L, the bias is
CONFIRMED. If it disagrees, treat as RANGE unless the MSS occurred within the
last 3 closed 4H candles in the direction of Section L.
RANGE = no directional trade unless a named 4H MSS supplies direction.
The packet's DAILY_BIAS label is advisory. If Section L disagrees, use Section L.

=== SECTION M: SWEEP SCAN ===
Scan all five timeframes (1D, 4H, 1H, 15M, 5M) for liquidity sweeps. A sweep
= a closed candle whose wick exceeded a named prior swing, equal-high/equal-
low cluster, or session/PDH/PDL level by >= 1 increment AND closed back inside
prior structure.

Direction semantics:
  LOW sweep  (wick below level, close ABOVE) = BULLISH signal (sell-side grab)
  HIGH sweep (wick above level, close BELOW) = BEARISH signal (buy-side grab)

Candle wicks beyond a level AND closes beyond the same side = BREAKDOWN or
BREAKOUT, not a sweep. List separately. A FAILED BREAKDOWN is a low wick
below a level + a later candle body-closing back above (bullish trap reversal).
A FAILED BREAKOUT is the mirror (bearish trap reversal).

Tier classification:
  TIER_1:  completed ASIA/LONDON/NEW_YORK high or low, or PDH/PDL
  TIER_2:  named 4H or 1H swing high/low
  TIER_3:  unclassified intraday swing (15M/5M only)

MANDATORY per-timeframe enumeration: for EACH timeframe, list BOTH the most
recent BULLISH sweep and the most recent BEARISH sweep (or NONE). Skipping
either direction on any timeframe is a contract violation.

Directional priority:
  - A TIER_1 sweep in the direction of the confirmed bias is the primary thesis.
  - A counter-bias TIER_1 sweep is DISCARDED unless a named 4H MSS exists in
    that sweep's direction.
  - If no sweep exists on any timeframe, return NO_TRADE.

=== SECTION N: KILLZONE ===
Compute from SERVER_TIME_UTC using fixed UTC windows. No DST adjustments.
  LONDON:            07:00-11:00 UTC
  LONDON/NY OVERLAP: 11:00-12:00 UTC   (highest liquidity - INSIDE)
  NEW YORK:          12:00-15:00 UTC

CRITICAL RULE: If the computed window is "NONE" (Outside Killzone), you are strictly FORBIDDEN from returning a trade. You must return action "NO_TRADE". Do not trade the Asian session. The thin liquidity causes unpredictable stop hunts.
The packet's KILLZONE_STATUS label is advisory; recompute from UTC.

=== SETUP CONSTRUCTION ===

=== CURRENT OPPORTUNITY & SNIPER ENTRY ===
1. AGGRESSIVE DISPLACEMENT: The leg leaving the Order Block must be violent. If the market slowly grinded out, do not trade it.
2. PROXIMAL EDGE OR FVG: If current price is ABOVE the zone, place the entry at the proximal edge (top of Bullish OB).
   HOWEVER, if current price is ALREADY INSIDE the Order Block, do NOT return NO_TRADE. Find the nearest FVG (Fair Value Gap) or imbalance inside or just below current price, and place the limit order there.
3. NO CHASING: If current price is already more than 2.0 points (XAU) away from the zone in the wrong direction, return NO_TRADE.

=== MARKET CONTEXT & REACTION ===
=== CRT & MSNR LOGIC ===
1. CRT (Candle Range Theory): Look for price sweeping the high/low of the
   previous Daily or 4H candle range. When the 15M or 1H chart sweeps that HTF
   extreme and immediately reverses, this is a CRT play.
2. MSNR (Market Structure Neo-Retail): Identify exactly where retail traders
   are trapped. A high-probability zone is one where the sweep clearly grabbed
   retail stop-losses before the displacement leg.
3. TBS (Time-Based Supply): Only trade these zones when the session timing
   aligns (London or NY Killzones).

ORDER BLOCK:
The OB is the last opposite-direction candle before the displacement leg.
  - Bullish OB: the last BEARISH candle (close < open) before the up leg.
  - Bearish OB: the last BULLISH candle (close > open) before the down leg.
The OB zone is that candle's BODY (open-to-close). The wick is never the OB.
Using the sweep candle itself as the OB is a contract violation.

STOP LOSS (DYNAMIC & VOLATILITY-AWARE):
Place stop_loss at the NEAREST structural invalidation based on the MARKET CONTEXT:
- If TRENDING_BULLISH / TRENDING_BEARISH: Place the stop BEYOND the recent
  structural swing low/high that caused the displacement.
- If RANGING / CONSOLIDATING: Place the stop at the OB far edge + standard buffer.

CRITICAL XAU/USD STOP LOSS RULE: For Gold (XAU/USD), the stop loss must ALWAYS be placed safely BEYOND the actual structural sweep wick with a minimum 0.50 buffer.
- DO NOT place the stop loss INSIDE the sweep wick.
- The absolute minimum risk distance is 4.50 points. If the structural wick is closer than 4.50 points, you MUST widen the stop to 4.50 points.
- If the structural wick is further than 4.50 points, you MUST place the stop beyond the wick (e.g., if the wick is 6.0 points away, the stop must be at 6.5 points).

Never widen the stop to swallow distant HTF swing highs/lows, PDH/PDL, or
round numbers unless that level IS the immediate structural invalidation.

TAKE PROFIT:
TP1 = the NEAREST opposing 1H/4H pool that has NOT been body-closed through
in the direction of the trade. "Unused" means no closed candle body-closed
beyond the level. WICK-TAPS do NOT disqualify a pool.
If the nearest candidate TP1 IS body-broken, DO NOT reject the trade -
relocate TP1 to the next unused pool above (BUY) or below (SELL) and
recompute RR. Only if RR still < 2.00 after relocation does the setup fail.
TP2 and TP3 extend to the next unused pools. Never inflate TP to improve RR.

RISK/REWARD:
  RISK = |entry - stop_loss|
  REWARD = |tp1 - entry|
  RR_TP1 = REWARD / RISK (two decimals, verify)
RR_TP1 must be >= 2.00. Below 2.00 = NO_TRADE. Never fabricate a target or tighten the stop past a valid invalidation to fix RR.

=== WORKED ACCEPTANCE EXAMPLE ===
BULLISH Section L bias. London-low TIER_1 bullish sweep at 1H 2026-10-28T06:00
(wick 4028.19 below LONDON_LOW 4028.20, close 4030.82 above).
Bullish OB at 1H 2026-10-28T05:00 (body 4030.37-4036.68).

TP1 candidates above entry (BUY):
  NY_HIGH 4054.53 - body-broken on 1H 2026-10-27T15:00 - USED.
  LONDON_HIGH 4058.30 - wick-tapped but never body-broken - UNUSED.
  PDH 4065.70 - wick-tapped twice but NEVER body-closed above - UNUSED, MAJOR.

Correct TP1: 4065.70 (nearest unused MAJOR pool).
Result: ENTRY=4034.00  SL=4027.50  TP1=4065.70
        RISK=6.50  REWARD=31.70  RR=4.88`.split('\n');
}

