function rawPacketDiagnosticEnabled() {
    return typeof window !== 'undefined' && window.__RAW_PACKET_DIAGNOSTIC__ === true;
}

function RAW_PACKET_DIAGNOSTIC(enabled) {
    if (typeof enabled === 'boolean' && typeof window !== 'undefined') {
        window.__RAW_PACKET_DIAGNOSTIC__ = enabled;
        console.log('RAW_PACKET_DIAGNOSTIC', enabled
            ? 'ENABLED - the next packet build will print its context summary'
            : 'DISABLED');
    }
    if (enabled === false) return false;
    if (lastRawPacketDiagnostic) {
        console.log('RAW_PACKET_DIAGNOSTIC', lastRawPacketDiagnostic);
        return lastRawPacketDiagnostic;
    }
    console.log('RAW_PACKET_DIAGNOSTIC', 'NO_PACKET_BUILT_YET');
    return null;
}

function buildRawCandleAiPacket({ source = {}, symbol, price, precision = 2, asOfMs = Date.now(), quote = {} } = {}) {
    const dailyCandles = rawTextPacketClosedCandles(source, '1D', asOfMs);
    const dailyBias = buildRawCandleAiDailyBias(dailyCandles);
    const daily = dailyBias.last;
    const macroLevels = buildRawCandleAiMacroLevels(source, asOfMs);
    const ghostRules = buildRawCandleAiGhostRules();
    const serverClock = rawCandleAiServerClock(asOfMs);
    const candleCounts = Object.fromEntries(RAW_CANDLE_AI_TIMEFRAMES.map(timeframe => [
        timeframe,
        rawTextPacketClosedCandles(source, timeframe, asOfMs).slice(-rawCandleAiCandleLimit(timeframe)).length
    ]));
    const levelValue = value => value == null ? 'NONE' : rawTextPacketFormatNumber(value, precision);
    const macroContextLevels = [
        { name: 'PREVIOUS_DAY_HIGH', value: macroLevels.previous_day_high },
        { name: 'PREVIOUS_DAY_LOW', value: macroLevels.previous_day_low },
        { name: 'ASIA_HIGH', value: macroLevels.asia_high },
        { name: 'ASIA_LOW', value: macroLevels.asia_low },
        { name: 'LONDON_HIGH', value: macroLevels.london_high },
        { name: 'LONDON_LOW', value: macroLevels.london_low },
        { name: 'NEW_YORK_HIGH', value: macroLevels.new_york_high },
        { name: 'NEW_YORK_LOW', value: macroLevels.new_york_low }
    ];
    const lines = [
        '=== AI TRADING PACKET: RAW CANDLE AI ===',
        ...(serverClock.outside_killzone ? ['WARNING: OUTSIDE_KILLZONE'] : []),
        'PROMPT_CONTRACT_VERSION=RAW_CANDLE_AI_V2.7.1',
        'V2_STRATEGY_MODE=' + STRATEGY_MODE_RAW_CANDLE_AI,
        'AUTHORITY_MODE=' + STRATEGY_MODE_RAW_CANDLE_AI,
        'DETERMINISTIC_POI_ENGINE=DISABLED',
        'DETERMINISTIC_FVG_ENGINE=DISABLED',
        'DETERMINISTIC_ZONE_ENGINE=DISABLED',
        'CANDIDATE_LIST_ENGINE=DISABLED',
        'SYMBOL: ' + symbol,
        'CURRENT PRICE: ' + rawTextPacketFormatNumber(price, precision),
        'QUOTE TIME: ' + String(quote.quote_time || quote.current_price_time || 'UNKNOWN'),
        'AS OF: ' + new Date(asOfMs).toISOString(),
        'SERVER_TIME_UTC: ' + serverClock.utc,
        'SERVER_TIME_EST: ' + serverClock.est,
        'KILLZONE_STATUS=' + (serverClock.inside_killzone ? serverClock.killzone : 'OUTSIDE'),
        'LAST CLOSED CANDLE TIME: ' + (daily ? new Date(rawTextPacketTimestamp(daily.t)).toISOString() : ''),
        'GENERATED AT: ' + new Date().toISOString(),
        '',
        '=== MACRO CONTEXT ===',
        'DAILY_BIAS=' + dailyBias.bias,
        'DAILY_BIAS_METHOD=' + dailyBias.reason,
        'DAILY_LAST_OPEN=' + (daily ? rawTextPacketFormatNumber(daily.o, precision) : 'NONE'),
        'DAILY_LAST_HIGH=' + (daily ? rawTextPacketFormatNumber(daily.h, precision) : 'NONE'),
        'DAILY_LAST_LOW=' + (daily ? rawTextPacketFormatNumber(daily.l, precision) : 'NONE'),
        'DAILY_LAST_CLOSE=' + (daily ? rawTextPacketFormatNumber(daily.c, precision) : 'NONE'),
        'CURRENT_PRICE=' + rawTextPacketFormatNumber(price, precision),
        'MACRO_LEVELS_SOURCE=' + macroLevels.previous_day_source,
        ...macroContextLevels.map(level => level.name + '=' + levelValue(level.value)),
        'RAW_TIMEFRAMES=' + RAW_CANDLE_AI_TIMEFRAMES.join(','),
        'CANDLE_LIMIT_PER_TIMEFRAME=' + rawCandleAiLimitSummary(),
        ''
    ];
    for (const timeframe of RAW_CANDLE_AI_TIMEFRAMES) {
        lines.push(...buildRawCandleAiCsvLines(source, timeframe, asOfMs, precision), '');
    }
    lines.push(...ghostRules, '');
    lines.push(...buildRawCandleAiInstruction(), '');
    lines.push(RAW_CANDLE_AI_OUTPUT_CONTRACT);
    const packetText = lines.join('\n');
    lastRawPacketDiagnostic = {
        packet: 'RAW_PACKET_DIAGNOSTIC',
        symbol,
        as_of: new Date(asOfMs).toISOString(),
        candle_counts: candleCounts,
        candle_limits: { ...RAW_CANDLE_AI_CANDLE_LIMITS },
        total_candles: Object.values(candleCounts).reduce((sum, count) => sum + count, 0),
        packet_characters: packetText.length,
        estimated_tokens: Math.ceil(packetText.length / 4),
        macro_context_levels: macroContextLevels,
        macro_levels_source: macroLevels.previous_day_source,
        killzone: {
            server_time_utc: serverClock.utc,
            server_time_est: serverClock.est,
            active: serverClock.killzone,
            inside_killzone: serverClock.inside_killzone,
            outside_killzone: serverClock.outside_killzone,
            warning_injected: serverClock.outside_killzone
        },
        ghost_rules: {
            version: 'V2.7.1',
            output_format: 'JSON',
            reasoning_protocol_included: ghostRules.some(rule => rule.startsWith('=== DEEPSEEK REASONING PROTOCOL (READ FIRST) ===')),
            daily_bias_included: ghostRules.some(rule => rule.startsWith('=== SECTION L: DAILY BIAS ===')),
            mandatory_sweep_scan_included: ghostRules.some(rule => rule.startsWith('=== SECTION M: SWEEP SCAN ===')),
            utc_killzone_rule_included: ghostRules.some(rule => rule.startsWith('=== SECTION N: KILLZONE ===')),
            no_asia_session_rule_included: ghostRules.some(rule => rule.includes('No Asian session trades.')),
            killzone_none_forces_no_trade_included: ghostRules.some(rule => rule.includes('strictly FORBIDDEN from returning a trade')),
            setup_construction_included: ghostRules.some(rule => rule.startsWith('=== SETUP CONSTRUCTION ===')),
            sniper_entry_rule_included: ghostRules.some(rule => rule.includes('ALREADY INSIDE the Order Block')),
            proximal_edge_rule_included: ghostRules.some(rule => rule.includes('PROXIMAL EDGE OR FVG:')),
            no_chasing_rule_included: ghostRules.some(rule => rule.includes('NO CHASING:')),
            market_context_rule_included: ghostRules.some(rule => rule.startsWith('=== MARKET CONTEXT & REACTION ===')),
            crt_msnr_logic_included: ghostRules.some(rule => rule.startsWith('=== CRT & MSNR LOGIC ===')),
            order_block_rule_included: ghostRules.some(rule => rule.startsWith('ORDER BLOCK:')),
            nearest_invalidation_rule_included: ghostRules.some(rule => rule.startsWith('STOP LOSS')),
            dynamic_stop_rule_included: ghostRules.some(rule => rule.startsWith('STOP LOSS (DYNAMIC & VOLATILITY-AWARE):')),
            gold_minimum_stop_included: ghostRules.some(rule => rule.includes('absolute minimum risk distance is 4.50 points')),
            target_relocation_rule_included: ghostRules.some(rule => rule.includes('relocate TP1 to the next unused pool')),
            hard_rr_gate_included: ghostRules.some(rule => rule.includes('RR_TP1 must be >= 2.00')),
            worked_acceptance_example_included: ghostRules.some(rule => rule.startsWith('=== WORKED ACCEPTANCE EXAMPLE ===')),
            strict_json_schema_included: ghostRules.some(rule => rule.includes('The JSON object is the only permitted output.'))
        }
    };
    if (rawPacketDiagnosticEnabled()) console.log('RAW_PACKET_DIAGNOSTIC', lastRawPacketDiagnostic);
    return packetText;
}

function buildRawTextMarketAnalysisPacket({ signal = {}, replay = null } = {}) {
    const source = replay || {};
    const symbol = normalizeCanonicalMarketSymbol(source.pair || signal.pair || pair);
    const metadata = source.quote?.symbol_metadata || source.runtime_state?.quote_snapshot?.symbol_metadata || source.symbol_metadata || {};
    const asOfMs = rawTextPacketTimestamp(source.scan_as_of || source.quote?.quote_time) || Date.now();
    const quote = rawMarketAnalysisQuote(source);
    const latestClosed = RAW_CANDLE_AI_TIMEFRAMES
        .flatMap(timeframe => rawTextPacketClosedCandles(source, timeframe, asOfMs))
        .sort((left, right) => rawTextPacketTimestamp(right.t) - rawTextPacketTimestamp(left.t))[0] || null;
    const price = Number.isFinite(Number(quote.current_price)) ? Number(quote.current_price) : latestClosed?.c;
    const precision = rawTextPacketPrecision(symbol, metadata, price);
    return buildRawCandleAiPacket({ source, symbol, price, precision, asOfMs, quote });
}

function fallbackCopyPlainText(packetText) {
    if (typeof document === 'undefined' || typeof document.createElement !== 'function') return false;
    const textarea = document.createElement('textarea');
    textarea.value = String(packetText ?? '');
    textarea.setAttribute('readonly', '');
    textarea.style.position = 'fixed';
    textarea.style.opacity = '0';
    textarea.style.pointerEvents = 'none';
    document.body?.appendChild(textarea);
    textarea.select();
    let copied = false;
    try {
        copied = typeof document.execCommand === 'function' && document.execCommand('copy');
    } catch (_) {
        copied = false;
    } finally {
        textarea.remove();
    }
    return copied;
}

async function writePlainTextToClipboard(packetText) {
    try {
        if (typeof navigator !== 'undefined' && navigator.clipboard?.writeText) {
            await navigator.clipboard.writeText(packetText);
            return true;
        }
    } catch (_) {
        // Continue to the hidden textarea fallback.
    }
    return fallbackCopyPlainText(packetText);
}

function copyRawMarketAnalysisPacket() {
    if (scanInProgress) {
        showNotif('Analysis is still finishing; wait for Scan complete', 'warning');
        return;
    }
    let artifact = currentScanArtifact;
    const activePair = normalizeCanonicalMarketSymbol(pair);
    let artifactPair = normalizeCanonicalMarketSymbol(artifact?.symbol || artifact?.replay?.pair || '');
    // Recover only from the exact current scan/symbol.  This handles a
    // production replay-capture failure without ever inheriting another
    // symbol's packet or reconstructing authority from the displayed UI.
    if (artifact?.signal && !artifact?.replay && lastLiveMarketContextForReplay
        && normalizeCanonicalMarketSymbol(lastLiveMarketContextForReplay.pair) === activePair) {
        try {
            const recoveredReplay = createScanReplay(lastLiveMarketContextForReplay, { trade_signal: artifact.signal });
            artifact = publishCurrentScanArtifact({ signal: artifact.signal, replay: recoveredReplay });
            window.__ICT_LAST_SCAN_REPLAY__ = recoveredReplay;
            lastLiveMarketContextForReplay = null;
            artifactPair = normalizeCanonicalMarketSymbol(artifact?.symbol || recoveredReplay.pair || '');
        } catch (error) {
            console.error('[COPY] current scan replay recovery failed', error);
        }
    }
    if (artifact?.signal && !artifact?.replay && window.__ICT_LAST_SCAN_REPLAY__) {
        const retainedReplay = window.__ICT_LAST_SCAN_REPLAY__;
        const retainedPair = normalizeCanonicalMarketSymbol(retainedReplay.pair || '');
        const signalSnapshot = artifact.signal.snapshot_id || null;
        if (retainedPair === activePair && signalSnapshot && retainedReplay.snapshot_id === signalSnapshot) {
            artifact = publishCurrentScanArtifact({ signal: artifact.signal, replay: retainedReplay });
            artifactPair = retainedPair;
        }
    }
    if (!artifact?.replay || !artifactPair || !activePair || artifactPair !== activePair) {
        showNotif('Run a current-symbol analysis first', 'warning');
        return;
    }
    const textPacket = buildRawTextMarketAnalysisPacket({ signal: artifact.signal, replay: artifact.replay });
    writePlainTextToClipboard(textPacket).then(copied => {
        if (!copied) {
            showNotif('Clipboard unavailable', 'error');
            return;
        }
        if (typeof window !== 'undefined') {
            window.Telegram?.WebApp?.HapticFeedback?.notificationOccurred?.('success');
        }
        showToast('Copied to clipboard');
    });
}

function buildCurrentCanonicalMarketSnapshotJson() {
    const replay = currentScanArtifact?.replay;
    if (!replay || replay.snapshot_contract_version !== 'CANONICAL_MARKET_SNAPSHOT_V1') {
        throw new Error('Run a new completed analysis before exporting the canonical snapshot');
    }
    assertScanReplaySafe(replay);
    return JSON.stringify(replay, null, 2);
}

async function copyCurrentCanonicalMarketSnapshot() {
    try {
        const copied = await writePlainTextToClipboard(buildCurrentCanonicalMarketSnapshotJson());
        if (!copied) throw new Error('Clipboard unavailable');
        showToast('Canonical market snapshot copied');
        return true;
    } catch (error) {
        showNotif(error?.message || 'Canonical snapshot unavailable', 'warning');
        return false;
    }
}

if (typeof window !== 'undefined') {
    window.buildRawTextMarketAnalysisPacket = buildRawTextMarketAnalysisPacket;
    window.parseRawCandleAIActionResponse = parseRawCandleAIActionResponse;
    window.normalizePendingLimitTargetOrder = normalizePendingLimitTargetOrder;
    window.RAW_PACKET_DIAGNOSTIC = RAW_PACKET_DIAGNOSTIC;
    window.setRawPacketDiagnostic = RAW_PACKET_DIAGNOSTIC;
    window.buildManualMarketMechanicsOpportunityShortlist = buildManualMarketMechanicsOpportunityShortlist;
    window.validateManualMarketMechanicsDecision = validateManualMarketMechanicsDecision;
    window.copyRawMarketAnalysisPacket = copyRawMarketAnalysisPacket;
    window.buildCurrentCanonicalMarketSnapshotJson = buildCurrentCanonicalMarketSnapshotJson;
    window.copyCurrentCanonicalMarketSnapshot = copyCurrentCanonicalMarketSnapshot;
}

function aiUtf8ByteLength(value) {
    const text = String(value ?? '');
    return typeof TextEncoder === 'function' ? new TextEncoder().encode(text).byteLength : text.length;
}

function compactEvidenceNumber(...values) {
    const value = values.find(candidate => candidate !== null && candidate !== undefined && candidate !== '');
    if (value === undefined) return null;
    const number = Number(value);
    return Number.isFinite(number) ? number : null;
}

// Manual packet normalization accepts the timestamp aliases used by the
// deterministic detectors and strategy-event adapters.  This is a
// presentation-boundary helper only; it does not alter detector chronology.
function manualPacketTimestampValue(item = {}) {
    if (!item || typeof item !== 'object') return null;
    return item.event_time ?? item.formation_time ?? item.created_time
        ?? item.source_time ?? item.reclaim_time ?? item.time ?? item.timestamp ?? null;
}

// Existing location records use id/evidence_id as their canonical identity.
// event_id is an accepted fallback for event-shaped records; it must not
// displace an already supplied canonical location id.
function manualPacketCanonicalId(item = {}) {
    if (!item || typeof item !== 'object') return null;
    return item.id || item.evidence_id || item.event_id || null;
}

function compactAiEvidenceItem(item = {}, fallbackType = null, fallbackTimeframe = null) {
    if (item == null || typeof item !== 'object') return null;
    const id = manualPacketCanonicalId(item);
    const level = compactEvidenceNumber(item.level, item.price);
    const low = compactEvidenceNumber(item.low, item.zone?.low, item.zone_low);
    const high = compactEvidenceNumber(item.high, item.zone?.high, item.zone_high);
    const midpointValue = item.midpoint ?? item.mid ?? item.price ?? item.zone?.midpoint;
    const midpoint = compactEvidenceNumber(midpointValue);
    const invalidation = item.structural_invalidation && typeof item.structural_invalidation === 'object'
        ? item.structural_invalidation
        : item.structural_invalidation_detail && typeof item.structural_invalidation_detail === 'object'
            ? item.structural_invalidation_detail : null;
    const sourceRecord = item.source && typeof item.source === 'object' ? item.source : null;
    const sourceInvalidation = sourceRecord?.structural_invalidation_detail && typeof sourceRecord.structural_invalidation_detail === 'object'
        ? sourceRecord.structural_invalidation_detail
        : sourceRecord?.structural_invalidation && typeof sourceRecord.structural_invalidation === 'object'
            ? sourceRecord.structural_invalidation : null;
    const sourceLocationId = item.source_location_id
        || invalidation?.source_location_id
        || sourceInvalidation?.source_location_id
        || item.location_id
        || item.zone_id
        || sourceRecord?.execution_zone?.id
        || sourceRecord?.execution_zone?.location_id
        || null;
    const sourceModel = item.source_model
        || invalidation?.source_model
        || sourceInvalidation?.source_model
        || (invalidation?.source ? canonicalModelToken(invalidation.source) : null)
        || (sourceInvalidation?.source ? canonicalModelToken(sourceInvalidation.source) : null)
        || sourceRecord?.primary
        || null;
    const invalidationLevel = Number.isFinite(Number(invalidation?.level ?? item.structural_invalidation_level ?? item.invalidation_level ?? item.invalidation))
        ? Number(invalidation?.level ?? item.structural_invalidation_level ?? item.invalidation_level ?? item.invalidation) : null;
    const formationTime = manualPacketTimestampValue(item);
    const postFormationDelivery = Number.isFinite(Number(item.post_formation_delivery_progress ?? item.delivery_progress_since_formation))
        ? Number(item.post_formation_delivery_progress ?? item.delivery_progress_since_formation) : null;
    const deliveryAfterFormation = typeof item.delivery_after_formation === 'boolean' ? item.delivery_after_formation : null;
    return {
        id,
        type: item.type || item.event_type || item.kind || item.source_type || fallbackType,
        source: item.source || item.primary_target_source || item.origin || null,
        direction: item.direction || null,
        timeframe: item.timeframe || fallbackTimeframe || null,
        level,
        price: level,
        low,
        high,
        midpoint,
        event_time: formationTime,
        freshness: item.freshness || item.freshness_state || null,
        mitigation_state: item.mitigation_state || item.mitigation || null,
        lifecycle_state: item.lifecycle_state || item.target_lifecycle_state || null,
        state: item.lifecycle_state || item.target_lifecycle_state || item.freshness || item.state || null,
        ...(item.opportunity_freshness || item.opportunity_lifecycle_state || Number.isFinite(Number(item.delivery_fraction))
            || Number.isFinite(Number(item.remaining_reward_fraction ?? item.remaining_reward_fraction_at_scan)) ? {
            opportunity_freshness: item.opportunity_freshness || item.opportunity_lifecycle_state || null,
            delivery_fraction: Number.isFinite(Number(item.delivery_fraction)) ? Number(item.delivery_fraction) : null,
            remaining_reward_fraction: Number.isFinite(Number(item.remaining_reward_fraction ?? item.remaining_reward_fraction_at_scan))
                ? Number(item.remaining_reward_fraction ?? item.remaining_reward_fraction_at_scan) : null
        } : {}),
        invalidated: item.invalidated === true,
        consumed: item.consumed === true || item.entry_consumed === true,
        structural_invalidation: invalidationLevel == null ? null : {
            level: invalidationLevel,
            source: invalidation?.source || item.structural_invalidation_source || null,
            evidence_id: id
        },
        ...(sourceLocationId ? { source_location_id: sourceLocationId } : {}),
        ...(sourceModel ? {
            source_model: sourceModel
        } : {}),
        ...(item.source_event_id || invalidation?.source_event_id || sourceInvalidation?.source_event_id || sourceRecord?.id ? {
            source_event_id: item.source_event_id || invalidation?.source_event_id || sourceInvalidation?.source_event_id || sourceRecord?.id || null
        } : {}),
        ...(item.invalidation_basis || invalidation?.invalidation_basis || invalidation?.basis || sourceInvalidation?.invalidation_basis || sourceInvalidation?.basis ? {
            invalidation_basis: item.invalidation_basis || invalidation?.invalidation_basis || invalidation?.basis || sourceInvalidation?.invalidation_basis || sourceInvalidation?.basis || null
        } : {}),
        ...(item.confirmation_mode || invalidation?.confirmation_mode || sourceInvalidation?.confirmation_mode ? {
            confirmation_mode: item.confirmation_mode || invalidation?.confirmation_mode || sourceInvalidation?.confirmation_mode || null
        } : {}),
        evidence_ids: Array.isArray(item.evidence_ids || item.supporting_evidence_ids)
            ? [...new Set([
                ...(item.evidence_ids || item.supporting_evidence_ids),
                ...(item.event_id ? [item.event_id] : [])
            ].filter(value => typeof value === 'string'))].slice(0, 12) : (item.event_id ? [item.event_id] : []),
        ...(postFormationDelivery != null || deliveryAfterFormation != null ? {
            formation_time: formationTime,
            delivery_since_formation: {
                progress: postFormationDelivery,
                delivered: deliveryAfterFormation
            }
        } : {})
    };
}

function compactAiStructuralInvalidation(item = {}, fallbackTimeframe = null) {
    const compact = compactAiEvidenceItem(item, item?.type || item?.kind || 'STRUCTURAL_LOCATION', fallbackTimeframe);
    if (!compact?.id || !compact.structural_invalidation) return null;
    const model = canonicalModelToken(item.model_family || item.model_semantics_id || item.type || item.strategy || compact.type);
    const invalidationBasis = item.invalidation_basis
        || item.structural_invalidation_basis
        || item.structural_invalidation?.basis
        || item.structural_invalidation_detail?.basis
        || deriveInvalidationBasis(item, model);
    const confirmationMode = item.invalidation_confirmation_mode
        || item.confirmation_mode
        || item.structural_invalidation?.confirmation_mode
        || item.structural_invalidation_detail?.confirmation_mode
        || null;
    return {
        invalidation_id: item.invalidation_id || item.invalidation?.id || compact.id,
        evidence_id: compact.id,
        type: compact.type,
        direction: compact.direction,
        timeframe: compact.timeframe,
        event_time: compact.event_time,
        invalidation: compact.structural_invalidation,
        source_location_id: item.source_location_id || item.location_id || item.zone_id || compact.id,
        source_model: model,
        source_timeframe: item.source_timeframe || item.timeframe || fallbackTimeframe || null,
        source_event_id: item.source_event_id || item.event_id || item.setup_id || null,
        source_price: item.source_price ?? item.level ?? item.price ?? compact.structural_invalidation.level,
        invalidation_basis: invalidationBasis,
        confirmation_mode: confirmationMode,
        lifecycle_invalidation: item.lifecycle_invalidation || null,
        execution_invalidation: item.execution_invalidation || {
            level: compact.structural_invalidation.level,
            basis: invalidationBasis,
            confirmation_mode: confirmationMode
        },
        invalidated: compact.invalidated,
        consumed: compact.consumed,
        evidence_ids: compact.evidence_ids || []
    };
}

// Manual packets are a presentation boundary.  These helpers deliberately do
// not change canonical evidence, lifecycle decisions, or automatic selection.
// Relevance is based on market-state properties only; direction is never used
// as a preference signal.
const MANUAL_PACKET_RELEVANCE_BARS = 24;
const MANUAL_PACKET_MAX_LOCATIONS_PER_TIMEFRAME = 32;
const MANUAL_PACKET_MAX_EVENTS_PER_TIMEFRAME = 28;
const MANUAL_PACKET_MAX_INSTITUTIONAL_RECORDS_PER_TIMEFRAME = 12;
const MANUAL_RECENT_CANDLES_PER_TIMEFRAME = 20;
const MANUAL_MARKET_PHASES = Object.freeze([
    'ORIGINAL_SETUP', 'EARLY_DELIVERY', 'EXPANSION', 'RETRACEMENT',
    'CONTINUATION_READY', 'LATE_DELIVERY', 'TRANSITION_WAIT'
]);
const MANUAL_SETUP_TOKENS = Object.freeze([
    'ICT', 'CURRENT_STRUCTURE', 'FVG', 'OB', 'CRT', 'TBS', 'MSNR',
    'FLIP', 'SUPPLY', 'DEMAND', 'ORDER_BLOCK', 'FAIR_VALUE_GAP'
]);

// Raw candles are an observation layer for the manual external-AI packet.
// They must come from the already-built canonical snapshot; this helper never
// fetches data or recomputes strategy facts.
function compactManualClosedCandle(candle = {}, timeframe = null, canonicalLastTime = null) {
    if (!candle || typeof candle !== 'object' || candle.is_closed === false) return null;
    const timestamp = normalizeTimestampUTC(candle.t ?? candle.time);
    const open = Number(candle.o ?? candle.open);
    const high = Number(candle.h ?? candle.high);
    const low = Number(candle.l ?? candle.low);
    const close = Number(candle.c ?? candle.close);
    if (!Number.isFinite(timestamp) || !Number.isFinite(open) || !Number.isFinite(high)
        || !Number.isFinite(low) || !Number.isFinite(close)) return null;
    if (Number.isFinite(canonicalLastTime) && timestamp > canonicalLastTime) return null;
    if (high < Math.max(open, close, low) || low > Math.min(open, close, high) || high < low) return null;
    return {
        time: new Date(timestamp).toISOString(),
        open,
        high,
        low,
        close,
        _timeframe: timeframe
    };
}

function buildManualRecentClosedCandles(timeframe, source = {}, referenceTime = null) {
    const raw = Array.isArray(source.raw_closed_candles)
        ? source.raw_closed_candles
        : (Array.isArray(source.recent_closed_candles) ? source.recent_closed_candles : []);
    const sourceLastTime = normalizeTimestampUTC(source.last_closed_time || source.last_closed_candle_time);
    const fallbackLastTime = raw.map(candle => normalizeTimestampUTC(candle?.t)).filter(Number.isFinite).at(-1);
    const canonicalLastTime = Number.isFinite(sourceLastTime)
        ? sourceLastTime
        : (Number.isFinite(fallbackLastTime) ? fallbackLastTime : normalizeTimestampUTC(referenceTime));
    const unique = new Map();
    for (const candle of raw) {
        const compact = compactManualClosedCandle(candle, timeframe, canonicalLastTime);
        if (compact) unique.set(compact.time, compact);
    }
    return [...unique.values()]
        .sort((left, right) => left.time.localeCompare(right.time))
        .slice(-MANUAL_RECENT_CANDLES_PER_TIMEFRAME)
        .map(({ _timeframe, ...candle }) => candle);
}

function buildManualRecentPriceAction(semantic = {}) {
    const records = Object.fromEntries(AI_SEMANTIC_TIMEFRAMES.map(timeframe => {
        const source = semantic.timeframes?.[timeframe] || {};
        return [timeframe, buildManualRecentClosedCandles(timeframe, source, semantic.snapshot?.as_of)];
    }));
    const missingTimeframes = AI_SEMANTIC_TIMEFRAMES.filter(timeframe => records[timeframe].length !== MANUAL_RECENT_CANDLES_PER_TIMEFRAME);
    return {
        complete: missingTimeframes.length === 0,
        missing_timeframes: missingTimeframes,
        candles_per_timeframe: MANUAL_RECENT_CANDLES_PER_TIMEFRAME,
        timeframes: records
    };
}

function buildManualCurrentMarketContext(semantic = {}, pair = null) {
    const snapshot = semantic.snapshot || {};
    const timeframes = semantic.timeframes || {};
    const volatilityFacts = snapshot.volatility || {};
    const session = snapshot.session || null;
    const sessionContext = session ? {
        session: session.name || session.session || null,
        is_killzone: session.is_killzone ?? session.isKillzone ?? null,
        is_silver_bullet: session.is_silver_bullet ?? session.isSilverBullet ?? null
    } : null;
    const volatility = Object.fromEntries(AI_SEMANTIC_TIMEFRAMES.map(timeframe => [timeframe, {
        atr: timeframes[timeframe]?.atr
            ?? ({ '1D': volatilityFacts.atr_1d, '4H': volatilityFacts.atr_4h, '1H': volatilityFacts.atr_1h, '15M': volatilityFacts.atr_15m, '5M': volatilityFacts.atr_5m }[timeframe] ?? null)
    }]));
    const dealingContext = Object.fromEntries(AI_SEMANTIC_TIMEFRAMES.map(timeframe => {
        const value = timeframes[timeframe] || {};
        const range = value.dealing_range || {};
        const premiumDiscount = value.premium_discount || {};
        const high = compactEvidenceNumber(range.high, range.range_high);
        const low = compactEvidenceNumber(range.low, range.range_low);
        const current = compactEvidenceNumber(snapshot.current_price, value.current_closed_price);
        const equilibrium = high != null && low != null && high >= low ? (high + low) / 2 : null;
        const span = high != null && low != null ? high - low : null;
        const normalized = span > 0 && current != null ? (current - low) / span : null;
        const tolerance = span > 0 ? Math.max(1e-9, span * 1e-6) : 1e-9;
        const position = current == null || equilibrium == null ? null
            : Math.abs(current - equilibrium) <= tolerance ? 'EQUILIBRIUM'
                : current > equilibrium ? 'PREMIUM' : 'DISCOUNT';
        return [timeframe, {
            range_high: high,
            equilibrium,
            range_low: low,
            position: position || premiumDiscount.zone || premiumDiscount.classification || null,
            normalized_position: normalized,
            distance_from_equilibrium: current != null && equilibrium != null ? current - equilibrium : null,
            current_price: current
        }];
    }));
    return {
        snapshot_time: snapshot.as_of || null,
        current_price: snapshot.current_price ?? null,
        asset_class: snapshot.asset_class || getAssetClass(pair || snapshot.pair),
        session_context: sessionContext,
        volatility_context: { regime: volatilityFacts.regime || null, by_timeframe: volatility },
        dealing_context: dealingContext
    };
}

function manualLocationStateIsStructurallyExecutable(item = {}) {
    const lifecycle = String(item.lifecycle_state || item.state || '').toUpperCase();
    const freshness = String(item.freshness || item.freshness_state || '').toUpperCase();
    if (item.consumed === true || item.invalidated === true) return false;
    if (lifecycle === 'CONSUMED' || lifecycle === 'INVALIDATED' || lifecycle === 'EXPIRED') return false;
    if (freshness === 'CONSUMED' || freshness === 'INVALIDATED' || freshness === 'EXPIRED') return false;
    const low = compactEvidenceNumber(item.low, item.zone?.low, item.zone_low);
    const high = compactEvidenceNumber(item.high, item.zone?.high, item.zone_high);
    const level = compactEvidenceNumber(item.level, item.price, item.midpoint, item.zone?.midpoint);
    return (low != null && high != null && high >= low) || level != null;
}

function manualRelativePosition(level, currentPrice) {
    const value = compactEvidenceNumber(level);
    const current = compactEvidenceNumber(currentPrice);
    if (value == null || current == null) return null;
    return value > current ? 'ABOVE' : value < current ? 'BELOW' : 'AT_PRICE';
}

function buildManualObjectiveSemanticState(objectives = {}, currentPrice = null) {
    const all = [...(objectives.above_current_price || []), ...(objectives.below_current_price || [])]
        .map(item => compactManualPacketValue({
            ...item,
            objective_class: item.objective_class || item.type || item.source || 'STRUCTURAL_OBJECTIVE',
            liquidity_side: deriveObjectiveLiquiditySide(item),
            source_relation_at_detection: deriveObjectiveSourceRelation(item),
            source_orientation_if_factual: item.source_orientation_if_factual || item.direction || null,
            relative_to_current_price: manualRelativePosition(item.level, currentPrice),
            evidence_ids: Array.isArray(item.evidence_ids) ? item.evidence_ids : []
        }))
        .filter(Boolean)
        .sort((a, b) => String(a.objective_id).localeCompare(String(b.objective_id)));
    const clusters = [];
    const byLevel = new Map();
    for (const item of all) {
        const key = Number.isFinite(Number(item.level)) ? String(Number(item.level)) : item.objective_id;
        if (!byLevel.has(key)) byLevel.set(key, []);
        byLevel.get(key).push(item);
    }
    for (const [key, members] of byLevel) {
        if (members.length < 2) continue;
        clusters.push({
            objective_cluster_id: `OBJECTIVE_CLUSTER:${key}`,
            cluster_level: Number.isFinite(Number(key)) ? Number(key) : null,
            member_objective_ids: members.map(item => item.objective_id),
            member_sources: [...new Set(members.map(item => item.source || item.type).filter(Boolean))],
            highest_timeframe: members.map(item => item.timeframe).find(Boolean) || null
        });
    }
    const clusterByObjectiveId = new Map();
    for (const cluster of clusters) for (const objectiveId of cluster.member_objective_ids) clusterByObjectiveId.set(objectiveId, cluster);
    for (const item of all) {
        const cluster = clusterByObjectiveId.get(item.objective_id);
        if (cluster) {
            item.objective_cluster_id = cluster.objective_cluster_id;
            item.cluster_level = cluster.cluster_level;
            item.cluster_member_count = cluster.member_objective_ids.length;
        }
    }
    return {
        all,
        above_current_price: all.filter(item => item.relative_to_current_price === 'ABOVE'),
        below_current_price: all.filter(item => item.relative_to_current_price === 'BELOW'),
        clusters
    };
}

function buildManualTimeframeState(semantic = {}, chronology = {}, currentContext = {}) {
    return Object.fromEntries(AI_SEMANTIC_TIMEFRAMES.map(timeframe => {
        const value = semantic.timeframes?.[timeframe] || {};
        const summary = currentContext.dealing_context?.[timeframe] || {};
        const structure = value.structure || {};
        const rangeHigh = compactEvidenceNumber(summary.range_high, value.dealing_range?.high);
        const rangeLow = compactEvidenceNumber(summary.range_low, value.dealing_range?.low);
        const rangePrice = compactEvidenceNumber(summary.current_price, value.current_closed_price, semantic.snapshot?.current_price);
        const rangeValid = rangeHigh != null && rangeLow != null && rangeHigh > rangeLow;
        const equilibrium = rangeValid ? (rangeHigh + rangeLow) / 2 : null;
        const normalizedPosition = rangeValid && rangePrice != null ? (rangePrice - rangeLow) / (rangeHigh - rangeLow) : null;
        const position = !rangeValid || rangePrice == null ? null
            : Math.abs(rangePrice - equilibrium) <= Math.max(1e-10, (rangeHigh - rangeLow) * 1e-9) ? 'EQUILIBRIUM'
                : rangePrice > equilibrium ? 'PREMIUM' : 'DISCOUNT';
        const events = (chronology.events || []).filter(event => event.timeframe === timeframe);
        const latest = (type, direction = null) => {
            const candidates = events.filter(event => String(event.event_type || '').toUpperCase().includes(type)
                && (!direction || String(event.direction || '').toUpperCase() === direction));
            return candidates.at(-1) || null;
        };
        const bos = latest('BOS');
        const mss = latest('MSS') || latest('CHOCH');
        const choch = latest('CHOCH');
        const displacement = latest('DISPLACEMENT');
        const liquidity = events.filter(event => /LIQUIDITY|SWEEP|RAID/.test(String(event.event_type || '').toUpperCase())).at(-1) || null;
        const latestIds = [bos, mss, choch, displacement, liquidity].map(event => event?.event_id).filter(Boolean);
        return [timeframe, compactManualPacketValue({
            timeframe,
            role: value.role || null,
            last_closed_time: value.last_closed_time || null,
            last_closed_price: value.current_closed_price ?? null,
            structure: {
                swing_sequence: structure.sequence || structure.structure_sequence || [],
                structural_trend: structure.structural_trend || structure.trend || 'NEUTRAL',
                momentum_trend: structure.momentum_trend || 'NEUTRAL',
                effective_trend: structure.effective_trend || structure.trend || 'NEUTRAL',
                latest_bos_direction: bos?.direction || structure.latest_bos_direction || null,
                latest_bos_time: bos?.time || structure.latest_bos_time || null,
                latest_mss_direction: mss?.direction || structure.latest_mss_direction || null,
                latest_mss_time: mss?.time || structure.latest_mss_time || null,
                latest_choch_direction: choch?.direction || structure.latest_choch_direction || null,
                latest_choch_time: choch?.time || structure.latest_choch_time || null
            },
            delivery: {
                latest_displacement_direction: displacement?.direction || null,
                latest_displacement_time: displacement?.time || null,
                latest_liquidity_event_type: liquidity?.event_type || null,
                latest_liquidity_event_direction: liquidity?.direction || null,
                latest_liquidity_event_time: liquidity?.time || null
            },
            range: {
                high: rangeHigh,
                low: rangeLow,
                equilibrium,
                current_price: rangePrice,
                current_position: position,
                distance_from_equilibrium: equilibrium != null && rangePrice != null ? rangePrice - equilibrium : null,
                normalized_position: normalizedPosition
            },
            volatility: { atr: value.atr ?? currentContext.volatility_context?.by_timeframe?.[timeframe]?.atr ?? null, current_range_vs_atr: value.current_range_vs_atr ?? null },
            latest_structural_event_ids: latestIds,
            model_evidence_ids: events.map(event => event.event_id).filter(Boolean).slice(-24),
            latest_meaningful_event_ids: events.map(event => event.event_id).filter(Boolean).slice(-24)
        }) || { timeframe }];
    }));
}

function buildManualSnapshotDelta(current = {}, previous = null) {
    if (!previous || typeof previous !== 'object') return { available: false };
    const snapshotSymbol = snapshot => snapshot?.packet_identity?.symbol
        || snapshot?.current_market_state?.symbol
        || snapshot?.symbol
        || null;
    const snapshotProvider = snapshot => snapshot?.packet_identity?.provider
        || snapshot?.current_market_state?.provider
        || snapshot?.provider
        || null;
    const currentSymbol = snapshotSymbol(current);
    const previousSymbol = snapshotSymbol(previous);
    const currentProvider = snapshotProvider(current);
    const previousProvider = snapshotProvider(previous);
    if (currentSymbol && previousSymbol
        && normalizeCanonicalMarketSymbol(currentSymbol) !== normalizeCanonicalMarketSymbol(previousSymbol)) {
        return {
            available: false,
            reason: 'SYMBOL_MISMATCH',
            previous_symbol: previousSymbol,
            current_symbol: currentSymbol,
            previous_snapshot_id: previous.packet_identity?.snapshot_id || previous.snapshot_id || null,
            current_snapshot_id: current.packet_identity?.snapshot_id || current.snapshot_id || null
        };
    }
    if (currentProvider && previousProvider && String(currentProvider).toUpperCase() !== String(previousProvider).toUpperCase()) {
        return {
            available: false,
            reason: 'PROVIDER_MISMATCH',
            previous_provider: previousProvider,
            current_provider: currentProvider,
            previous_snapshot_id: previous.packet_identity?.snapshot_id || previous.snapshot_id || null,
            current_snapshot_id: current.packet_identity?.snapshot_id || current.snapshot_id || null
        };
    }
    const currentLocations = current.current_actionable_location_catalogue || current.actionable_location_bundles || [];
    const previousLocations = previous.current_actionable_location_catalogue || previous.actionable_location_bundles || [];
    const currentObjectives = current.current_liquidity_objective_map?.all || current.objective_state?.all || [];
    const previousObjectives = previous.current_liquidity_objective_map?.all || previous.objective_state?.all || [];
    const ids = (items, key) => new Set((Array.isArray(items) ? items : []).map(item => item?.[key]).filter(Boolean));
    const recordMap = (items, key) => new Map((Array.isArray(items) ? items : []).filter(item => item?.[key]).map(item => [item[key], item]));
    const currentLocationIds = ids(currentLocations, 'location_id');
    const previousLocationIds = ids(previousLocations, 'location_id');
    const currentLocationMap = recordMap(currentLocations, 'location_id');
    const previousLocationMap = recordMap(previousLocations, 'location_id');
    const currentObjectiveIds = ids(currentObjectives, 'objective_id');
    const previousObjectiveIds = ids(previousObjectives, 'objective_id');
    const currentObjectiveMap = recordMap(currentObjectives, 'objective_id');
    const previousObjectiveMap = recordMap(previousObjectives, 'objective_id');
    const currentEvents = (current.market_delivery_chronology?.events || current.model_setup_evidence?.ICT_STRUCTURE_AND_LIQUIDITY || []);
    const previousEvents = (previous.market_delivery_chronology?.events || previous.model_setup_evidence?.ICT_STRUCTURE_AND_LIQUIDITY || []);
    const eventIds = items => new Set((Array.isArray(items) ? items : []).map(item => item?.event_id || item?.id).filter(Boolean));
    const currentEventIds = eventIds(currentEvents); const previousEventIds = eventIds(previousEvents);
    const added = (now, old) => [...now].filter(id => !old.has(id)).sort();
    const removed = (old, now) => [...old].filter(id => !now.has(id)).sort();
    const changed = (nowMap, oldMap, predicate) => [...nowMap.entries()]
        .filter(([id, item]) => oldMap.has(id) && predicate(item, oldMap.get(id)))
        .map(([id]) => id).sort();
    const lifecycleChanged = (item, previousItem) => JSON.stringify({
        lifecycle_state: item.lifecycle_state || item.structural_lifecycle?.lifecycle_state,
        freshness: item.freshness || item.structural_lifecycle?.freshness,
        opportunity_lifecycle_state: item.opportunity_lifecycle_state || item.opportunity_delivery?.state,
        consumed: item.consumed || item.structural_lifecycle?.consumed,
        invalidated: item.invalidated || item.structural_lifecycle?.invalidated
    }) !== JSON.stringify({
        lifecycle_state: previousItem.lifecycle_state || previousItem.structural_lifecycle?.lifecycle_state,
        freshness: previousItem.freshness || previousItem.structural_lifecycle?.freshness,
        opportunity_lifecycle_state: previousItem.opportunity_lifecycle_state || previousItem.opportunity_delivery?.state,
        consumed: previousItem.consumed || previousItem.structural_lifecycle?.consumed,
        invalidated: previousItem.invalidated || previousItem.structural_lifecycle?.invalidated
    });
    const transitionedTo = (nowMap, oldMap, field, value) => [...nowMap.entries()]
        .filter(([id, item]) => String(item[field] || item.structural_lifecycle?.[field] || '').toUpperCase() === value
            && String(oldMap.get(id)?.[field] || oldMap.get(id)?.structural_lifecycle?.[field] || '').toUpperCase() !== value)
        .map(([id]) => id).sort();
    const currentSummary = current.multi_timeframe_state || current.current_market_summary || {};
    const previousSummary = previous.multi_timeframe_state || previous.current_market_summary || {};
    const latestClosedTimeChanged = Object.fromEntries(AI_SEMANTIC_TIMEFRAMES.map(tf => [tf,
        (currentSummary[tf]?.last_closed_time || null) !== (previousSummary[tf]?.last_closed_time || null)]));
    const currentCandles = current.raw_evidence_appendix?.recent_closed_price_action || current.recent_price_action || {};
    const previousCandles = previous.raw_evidence_appendix?.recent_closed_price_action || previous.recent_price_action || {};
    const newCandleCounts = Object.fromEntries(AI_SEMANTIC_TIMEFRAMES.map(tf => {
        const previousTimes = new Set((previousCandles[tf] || []).map(candle => String(candle?.time || '')));
        return [tf, (currentCandles[tf] || []).filter(candle => !previousTimes.has(String(candle?.time || ''))).length];
    }));
    const newEventRecords = (Array.isArray(currentEvents) ? currentEvents : []).filter(event => {
        const id = event?.event_id || event?.id;
        return id && !previousEventIds.has(id);
    });
    const newEventIdsFor = pattern => newEventRecords.filter(event => pattern.test(`${event?.event_type || ''} ${event?.type || ''} ${event?.strategy || ''}`.toUpperCase())).map(event => event.event_id || event.id).sort();
    return {
        available: true,
        previous_snapshot_id: previous.packet_identity?.snapshot_id || previous.snapshot_id || null,
        current_snapshot_id: current.packet_identity?.snapshot_id || current.snapshot_id || null,
        latest_closed_time_changed: latestClosedTimeChanged,
        new_closed_candle_count_by_timeframe: newCandleCounts,
        new_event_ids: added(currentEventIds, previousEventIds),
        new_location_ids: added(currentLocationIds, previousLocationIds),
        location_ids_touched_since_previous: changed(currentLocationMap, previousLocationMap, lifecycleChanged),
        location_ids_consumed_since_previous: transitionedTo(currentLocationMap, previousLocationMap, 'consumed', 'TRUE'),
        location_ids_invalidated_since_previous: transitionedTo(currentLocationMap, previousLocationMap, 'invalidated', 'TRUE'),
        new_objective_ids: added(currentObjectiveIds, previousObjectiveIds),
        objective_ids_reached_since_previous: changed(currentObjectiveMap, previousObjectiveMap, (item, old) => (item.reached === true || String(item.lifecycle_state || '').toUpperCase() === 'REACHED')
            && !(old.reached === true || String(old.lifecycle_state || '').toUpperCase() === 'REACHED')),
        objective_ids_consumed_since_previous: changed(currentObjectiveMap, previousObjectiveMap, (item, old) => (item.consumed === true || String(item.lifecycle_state || '').toUpperCase() === 'CONSUMED')
            && !(old.consumed === true || String(old.lifecycle_state || '').toUpperCase() === 'CONSUMED')),
        new_liquidity_event_ids: newEventIdsFor(/LIQUIDITY|SWEEP|RAID/),
        new_bos_ids: newEventIdsFor(/\bBOS\b/),
        new_mss_ids: newEventIdsFor(/\bMSS\b/),
        new_choch_ids: newEventIdsFor(/CHOCH/),
        new_displacement_ids: newEventIdsFor(/DISPLACEMENT/),
        new_crt_ids: newEventIdsFor(/CRT/),
        new_tbs_ids: newEventIdsFor(/TBS/),
        new_msnr_ids: newEventIdsFor(/MSNR/),
        removed_actionable_location_ids: removed(previousLocationIds, currentLocationIds),
        current_actionable_location_ids_added: added(currentLocationIds, previousLocationIds)
    };
}

function buildPacketEvidencePackage(source = {}) {
    const storedPackage = source.market_evidence_package && typeof source.market_evidence_package === 'object'
        ? source.market_evidence_package
        : {};
    // Analyze stores the analyst catalog in the replay.  Its canonical
    // evidence package is nested under market_evidence_package; Copy must
    // unwrap that exact package instead of falling back to replay candles and
    // silently discarding canonical zones/lifecycle/identity fields.
    const nestedCanonicalPackage = storedPackage.market_evidence_package
        && typeof storedPackage.market_evidence_package === 'object'
        && storedPackage.market_evidence_package.timeframes
        ? storedPackage.market_evidence_package
        : null;
    const packageEvidence = nestedCanonicalPackage
        ? { ...storedPackage, ...nestedCanonicalPackage }
        : storedPackage;
    const sourceHistory = source.history && typeof source.history === 'object' ? source.history : {};
    const timeframes = Object.fromEntries(AI_SEMANTIC_TIMEFRAMES.map(timeframe => {
        const canonical = packageEvidence.timeframes?.[timeframe] || {};
        const history = Array.isArray(sourceHistory[timeframe]) ? sourceHistory[timeframe] : [];
        const raw = Array.isArray(canonical.raw_closed_candles) && canonical.raw_closed_candles.length
            ? canonical.raw_closed_candles
            : history;
        return [timeframe, {
            ...canonical,
            raw_closed_candles: raw,
            last_closed_time: canonical.last_closed_time || raw.filter(candle => candle?.is_closed !== false).at(-1)?.t || null,
            closed_candle_count: canonical.closed_candle_count ?? raw.filter(candle => candle?.is_closed !== false).length
        }];
    }));
    return { ...packageEvidence, timeframes };
}

function manualPacketEventTime(item = {}) {
    if (!item || typeof item !== 'object') return NaN;
    return normalizeTimestampUTC(manualPacketTimestampValue(item));
}

function manualPacketTimeframeWindow(timeframe) {
    const windows = { '1D': 24 * 60 * 60 * 1000, '4H': 4 * 60 * 60 * 1000, '1H': 60 * 60 * 1000, '15M': 15 * 60 * 1000, '5M': 5 * 60 * 1000 };
    // This is only clipboard relevance, not opportunity expiry. A sequence
    // can span several lower-timeframe candles, so retain at least one day of
    // recent context while still dropping genuinely historical episodes.
    return Math.max((windows[timeframe] || windows['1H']) * MANUAL_PACKET_RELEVANCE_BARS, 24 * 60 * 60 * 1000);
}

function manualPacketLifecycleState(item = {}) {
    return String(item.lifecycle_state || item.target_lifecycle_state || item.freshness
        || item.freshness_state || item.mitigation_state || item.state || '').toUpperCase();
}

function manualPacketIsRelevant(item = {}, timeframe = null, referenceTime = null) {
    if (!item || typeof item !== 'object') return false;
    const state = manualPacketLifecycleState(item);
    const activeState = ['FRESH', 'CURRENT', 'ACTIVE', 'FRESH_PENDING', 'FRESH_PENDING_TODAY', 'FRESH_PENDING_LATER', 'UNMITIGATED', 'PARTIAL'].some(value => state.includes(value));
    const invalidationState = item.invalidated === true || ['INVALIDATED', 'CONSUMED', 'EXPIRED', 'STALE', 'TARGET_DELIVERED'].some(value => state.includes(value));
    const eventTime = manualPacketEventTime(item);
    const referenceMs = normalizeTimestampUTC(referenceTime);
    const recent = Number.isFinite(eventTime) && Number.isFinite(referenceMs)
        ? eventTime >= referenceMs - manualPacketTimeframeWindow(timeframe)
        : false;
    // Active state preserves a current location even when a provider omits a
    // timestamp. Recent invalidations/consumption are retained as context;
    // old inactive records are intentionally omitted from the clipboard.
    return activeState || recent || (!Number.isFinite(eventTime) && !invalidationState);
}

function manualPacketRelevanceRank(item = {}, timeframe = null, referenceTime = null) {
    const eventTime = manualPacketEventTime(item);
    const referenceMs = normalizeTimestampUTC(referenceTime);
    const state = manualPacketLifecycleState(item);
    const active = ['FRESH', 'CURRENT', 'ACTIVE', 'FRESH_PENDING', 'FRESH_PENDING_TODAY', 'FRESH_PENDING_LATER', 'UNMITIGATED'].some(value => state.includes(value));
    const recent = Number.isFinite(eventTime) && Number.isFinite(referenceMs)
        ? eventTime >= referenceMs - manualPacketTimeframeWindow(timeframe) : false;
    const structurallyLinked = !!(item.structural_invalidation || item.structural_invalidation_detail
        || item.evidence_ids?.length || item.supporting_evidence_ids?.length);
    return (active ? 4 : 0) + (recent ? 3 : 0) + (structurallyLinked ? 1 : 0);
}

// Structural location lifecycle and opportunity lifecycle are deliberately
// separate.  A zone can remain a valid historical POI after the move it was
// intended to capture has already delivered.  This helper measures only the
// future-entry path, using the existing 50% remaining-reward principle; it
// does not rank locations or choose a replacement opportunity.
function evaluateManualPendingOpportunityDelivery(item = {}, timeframe = null, objectives = {}, currentPrice = null) {
    const orientation = String(item.source_orientation || item.orientation || item.direction || item.source_direction || '').toUpperCase();
    const direction = ['BUY', 'SELL'].includes(orientation)
        ? orientation
        : String(item.type || item.event_type || '').toUpperCase() === 'DEMAND' ? 'BUY'
            : String(item.type || item.event_type || '').toUpperCase() === 'SUPPLY' ? 'SELL' : null;
    const low = compactEvidenceNumber(item.low, item.zone?.low, item.zone_low);
    const high = compactEvidenceNumber(item.high, item.zone?.high, item.zone_high);
    const price = externalPacketNumber(currentPrice);
    const suppliedRemaining = externalPacketNumber(item.remaining_reward_fraction ?? item.remaining_reward_fraction_at_scan);
    const suppliedDelivery = externalPacketNumber(item.delivery_fraction);
    const suppliedFreshness = String(item.opportunity_freshness || item.opportunity_lifecycle_state || '').toUpperCase();
    const base = {
        opportunity_lifecycle_state: 'CURRENT',
        opportunity_relevance: 'CURRENT',
        delivery_fraction: suppliedDelivery,
        remaining_reward_fraction: suppliedRemaining,
        remaining_objective_ids: [],
        delivered_objective_ids: [],
        entry_reference: null,
        direction
    };
    if (['STALE_DELIVERY', 'STALE_FOR_NEW_ENTRY', 'TARGET_DELIVERED', 'SUBSTANTIALLY_DELIVERED'].includes(suppliedFreshness)) {
        return { ...base, opportunity_lifecycle_state: 'STALE_FOR_NEW_ENTRY', opportunity_relevance: 'STALE_FOR_NEW_ENTRY' };
    }
    if (Number.isFinite(suppliedRemaining) && suppliedRemaining < STRATEGY_SPEC.FRESHNESS.minRemainingRewardFraction) {
        return { ...base, opportunity_lifecycle_state: 'STALE_FOR_NEW_ENTRY', opportunity_relevance: 'STALE_FOR_NEW_ENTRY', delivery_fraction: 1 - suppliedRemaining };
    }
    if (!direction || !Number.isFinite(price) || !Number.isFinite(low) || !Number.isFinite(high) || high < low) return base;

    // Use the canonical midpoint when available.  If no midpoint exists, use
    // the directionally relevant edge; this is a measurement reference only,
    // not a serialized trade entry or a code-selected opportunity.
    const entry = compactEvidenceNumber(item.entry, item.execution_entry, item.midpoint, item.level,
        direction === 'SELL' ? low : high);
    if (!Number.isFinite(entry)) return base;
    const allObjectives = [
        ...(Array.isArray(objectives.above_current_price) ? objectives.above_current_price : []),
        ...(Array.isArray(objectives.below_current_price) ? objectives.below_current_price : [])
    ].filter(objective => objective && (objective.timeframe == null || objective.timeframe === (item.timeframe || timeframe)));
    const usable = objective => objective.reached !== true && objective.consumed !== true && objective.invalidated !== true
        && !['CONSUMED', 'INVALIDATED', 'TARGET_DELIVERED', 'REACHED'].includes(String(objective.lifecycle_state || objective.state || '').toUpperCase());
    const favorable = objective => direction === 'SELL' ? Number(objective.level) < entry : Number(objective.level) > entry;
    const path = allObjectives.filter(objective => usable(objective) && Number.isFinite(Number(objective.level)) && favorable(objective));
    if (!path.length) return { ...base, entry_reference: entry };
    // Measure delivery against the complete usable same-timeframe objective
    // path. Limiting this to the three nearest levels makes one crossed
    // micro-objective look like thesis-level exhaustion and incorrectly
    // removes an older, still-valid pending limit. The catalogue remains
    // factual; the external AI decides whether the remaining path is the
    // best opportunity.
    const ordered = path.slice().sort((a, b) => direction === 'SELL' ? Number(b.level) - Number(a.level) : Number(a.level) - Number(b.level));
    const delivered = ordered.filter(objective => direction === 'SELL' ? price <= Number(objective.level) : price >= Number(objective.level));
    const remaining = ordered.filter(objective => direction === 'SELL' ? price > Number(objective.level) : price < Number(objective.level));
    const farthest = direction === 'SELL' ? Math.min(...ordered.map(objective => Number(objective.level))) : Math.max(...ordered.map(objective => Number(objective.level)));
    const totalReward = Math.abs(farthest - entry);
    const deliveredDistance = direction === 'SELL' ? entry - price : price - entry;
    const deliveryFraction = totalReward > 0 ? Math.max(0, Math.min(1, deliveredDistance / totalReward)) : 0;
    const remainingRewardFraction = 1 - deliveryFraction;
    const stale = remainingRewardFraction < STRATEGY_SPEC.FRESHNESS.minRemainingRewardFraction;
    const partial = delivered.length > 0 && !stale;
    return {
        ...base,
        opportunity_lifecycle_state: stale ? 'STALE_FOR_NEW_ENTRY' : partial ? 'PARTIALLY_DELIVERED' : 'CURRENT',
        opportunity_relevance: stale ? 'STALE_FOR_NEW_ENTRY' : partial ? 'PARTIALLY_DELIVERED' : 'CURRENT',
        delivery_fraction: deliveryFraction,
        remaining_reward_fraction: remainingRewardFraction,
        remaining_objective_ids: remaining.map(objective => objective.objective_id).filter(Boolean),
        delivered_objective_ids: delivered.map(objective => objective.objective_id).filter(Boolean),
        entry_reference: entry
    };
}

function manualChronologyType(item = {}, fallbackType = null) {
    return String(item.event_type || item.type || item.kind || item.strategy || fallbackType || '')
        .trim().toUpperCase().replace(/[\s-]+/g, '_');
}

function isManualCausalChronologyEvent(item = {}, fallbackType = null) {
    const type = manualChronologyType(item, fallbackType);
    return /(LIQUIDITY|SWEEP|RAID|DISPLAC|BOS|MSS|CHOCH|RECLAIM|RETEST|FAIL|INVALIDAT|DELIVERY|OBJECTIVE|CRT|TBS|MSNR|TRANSITION|RANGE_BREAK|STRUCTURE_BREAK)/.test(type);
}

function compactManualStructureSummary(value = {}, chronologyEvents = []) {
    const structure = value.structure || {};
    const compactStructureEvent = (item, type) => {
        if (!item || typeof item !== 'object') return item;
        const event = manualDecisionEvent(item, type, value.timeframe);
        return event || compactManualPacketValue({ buy: item.buy, sell: item.sell });
    };
    const compactSwing = (item, type) => compactManualPacketValue({
        id: item?.id || item?.evidence_id || null,
        type: item?.type || type,
        timeframe: item?.timeframe || value.timeframe || null,
        level: compactEvidenceNumber(item?.level, item?.price, item?.high, item?.low),
        time: item?.event_time || item?.formation_time || item?.time || null,
        direction: item?.direction || null,
        evidence_ids: Array.isArray(item?.evidence_ids) ? item.evidence_ids.slice(0, 8) : undefined
    });
    const sequence = structure.hh_hl_sequence || structure.market_structure_sequence
        || structure.recent_structure_sequence || structure.sequence;
    return compactManualPacketValue({
        structural_trend: structure.structural_trend || null,
        momentum_trend: structure.momentum_trend || null,
        effective_trend: structure.effective_trend || null,
        sequence: Array.isArray(sequence) ? sequence.slice(-8) : sequence || undefined,
        swing_highs: Array.isArray(structure.swing_highs) ? structure.swing_highs.slice(-4).map(item => compactSwing(item, 'SWING_HIGH')) : undefined,
        swing_lows: Array.isArray(structure.swing_lows) ? structure.swing_lows.slice(-4).map(item => compactSwing(item, 'SWING_LOW')) : undefined,
        bos: compactStructureEvent(structure.bos, 'BOS'),
        mss: compactStructureEvent(structure.mss, 'MSS'),
        choch: compactStructureEvent(structure.choch, 'CHoCH'),
        displacement: compactStructureEvent(structure.displacement, 'DISPLACEMENT'),
        latest_causal_events: chronologyEvents.slice(-8)
    }) || {};
}

function manualPacketRecordKey(item = {}, fallbackType = null, timeframe = null) {
    if (!item || typeof item !== 'object') return `${fallbackType || 'ITEM'}:${timeframe || 'NA'}:${String(item)}`;
    return manualPacketCanonicalId(item) || `${item.type || fallbackType || 'ITEM'}:${timeframe || item.timeframe || 'NA'}:${manualPacketTimestampValue(item) || item.level || item.price || item.low || item.high || 'NA'}`;
}

function selectManualPacketRecords(items = [], timeframe = null, referenceTime = null, maxItems = 32) {
    const unique = new Map();
    for (const item of Array.isArray(items) ? items : []) {
        if (!item || typeof item !== 'object' || !manualPacketIsRelevant(item, timeframe, referenceTime)) continue;
        const key = manualPacketRecordKey(item, item.type || item.kind, timeframe);
        if (!unique.has(key)) unique.set(key, item);
    }
    const records = [...unique.values()];
    records.sort((a, b) => {
        const rankDifference = manualPacketRelevanceRank(b, timeframe, referenceTime) - manualPacketRelevanceRank(a, timeframe, referenceTime);
        if (rankDifference) return rankDifference;
        const timeDifference = (Number.isFinite(manualPacketEventTime(b)) ? manualPacketEventTime(b) : -Infinity)
            - (Number.isFinite(manualPacketEventTime(a)) ? manualPacketEventTime(a) : -Infinity);
        if (timeDifference) return timeDifference;
        return manualPacketRecordKey(a, null, timeframe).localeCompare(manualPacketRecordKey(b, null, timeframe));
    });
    if (records.length <= maxItems) return records;
    // Preserve distinct factual sides when both exist. This is a symmetry
    // guarantee, not a BUY/SELL ranking or directional vote.
    const selected = [];
    const selectedKeys = new Set();
    const directions = [...new Set(records.map(item => String(item.direction || '').toUpperCase()).filter(Boolean))];
    for (const direction of directions) {
        const item = records.find(candidate => String(candidate.direction || '').toUpperCase() === direction);
        if (item) {
            selected.push(item);
            selectedKeys.add(manualPacketRecordKey(item, item.type || item.kind, timeframe));
        }
    }
    for (const item of records) {
        if (selected.length >= maxItems) break;
        const key = manualPacketRecordKey(item, item.type || item.kind, timeframe);
        if (!selectedKeys.has(key)) {
            selected.push(item);
            selectedKeys.add(key);
        }
    }
    return selected;
}

function compactManualPacketValue(value) {
    if (Array.isArray(value)) {
        const compact = value.map(compactManualPacketValue).filter(item => item !== undefined);
        return compact.length ? compact : undefined;
    }
    if (!value || typeof value !== 'object') return value == null ? undefined : value;
    const compact = {};
    for (const [key, nested] of Object.entries(value)) {
        const normalized = compactManualPacketValue(nested);
        if (normalized !== undefined && normalized !== null && !(Array.isArray(normalized) && !normalized.length)) compact[key] = normalized;
    }
    return Object.keys(compact).length ? compact : undefined;
}

function compactManualInstitutionalComponent(component = {}, type = null, timeframe = null) {
    if (!component || typeof component !== 'object') return null;
    const compact = {
        id: component.id || component.evidence_id || null,
        type: component.type || component.event_type || type || null,
        direction: component.direction || null,
        side: component.side || null,
        timeframe: component.timeframe || timeframe || null,
        level: Number.isFinite(Number(component.level ?? component.price)) ? Number(component.level ?? component.price) : null,
        event_time: component.event_time || null,
        state: component.state || null,
        quality: component.quality || null,
        body_ratio: component.body_ratio ?? null,
        range_expansion: component.range_expansion ?? null,
        close_quality: component.close_quality ?? null,
        fvg_created: typeof component.fvg_created === 'boolean' ? component.fvg_created : null,
        reclaimed: component.reclaimed === true,
        invalidated: component.invalidated === true,
        evidence_ids: Array.isArray(component.evidence_ids) ? component.evidence_ids.filter(id => typeof id === 'string').slice(0, 12) : []
    };
    return compactManualPacketValue(compact) || null;
}

function compactManualInstitutionalOrigin(origin = {}, timeframe = null) {
    if (!origin || typeof origin !== 'object') return null;
    return compactManualPacketValue({
        id: origin.id || origin.evidence_id || null,
        type: origin.type || null,
        timeframe: origin.timeframe || timeframe || null,
        direction: origin.direction || null,
        low: Number.isFinite(Number(origin.low)) ? Number(origin.low) : null,
        high: Number.isFinite(Number(origin.high)) ? Number(origin.high) : null,
        midpoint: Number.isFinite(Number(origin.midpoint ?? origin.mid)) ? Number(origin.midpoint ?? origin.mid) : null,
        event_time: origin.event_time || origin.formation_time || null,
        freshness: origin.freshness || origin.freshness_state || null,
        mitigation_state: origin.mitigation_state || origin.mitigation || null,
        lifecycle_state: origin.lifecycle_state || origin.state || null,
        invalidated: origin.invalidated === true,
        consumed: origin.consumed === true,
        evidence_ids: Array.isArray(origin.evidence_ids) ? origin.evidence_ids.filter(id => typeof id === 'string').slice(0, 12) : []
    }) || null;
}

function compactManualInstitutionalRecord(record = {}, timeframe = null) {
    if (!record || typeof record !== 'object') return null;
    return compactManualPacketValue({
        id: record.id || null,
        source_class: record.source_class || 'PRICE_ACTION',
        timeframe: record.timeframe || timeframe || null,
        direction: record.direction || null,
        event_time: record.event_time || null,
        completeness: record.completeness || null,
        liquidity_event: compactManualInstitutionalComponent(record.liquidity_event, 'LIQUIDITY_EVENT', timeframe),
        displacement: compactManualInstitutionalComponent(record.displacement, 'DISPLACEMENT', timeframe),
        structural_consequence: compactManualInstitutionalComponent(record.structural_consequence, 'STRUCTURAL_CONSEQUENCE', timeframe),
        origin_locations: (record.origin_locations || []).map(origin => compactManualInstitutionalOrigin(origin, timeframe)).filter(Boolean),
        follow_through: compactManualInstitutionalComponent(record.follow_through, 'FOLLOW_THROUGH', timeframe),
        components_present: Array.isArray(record.components_present) ? record.components_present : [],
        components_missing: Array.isArray(record.components_missing) ? record.components_missing : [],
        evidence_ids: Array.isArray(record.evidence_ids) ? record.evidence_ids.filter(id => typeof id === 'string').slice(0, 32) : []
    }) || null;
}

function compactManualInstitutionalActivityEvidence(activity = {}, referenceTime = null) {
    if (!activity || typeof activity !== 'object') return null;
    const sourceTimeframes = activity.timeframes || {};
    const timeframes = Object.fromEntries(AI_SEMANTIC_TIMEFRAMES.map(timeframe => {
        const records = selectManualPacketRecords(sourceTimeframes[timeframe] || [], timeframe, referenceTime, MANUAL_PACKET_MAX_INSTITUTIONAL_RECORDS_PER_TIMEFRAME)
            .map(record => compactManualInstitutionalRecord(record, timeframe)).filter(Boolean);
        return [timeframe, records];
    }));
    return compactManualPacketValue({
        schema_version: activity.schema_version || 1,
        source_class: activity.source_class || 'PRICE_ACTION',
        as_of_time: activity.as_of_time || null,
        timeframes,
        // Keep a small index for consumers that use the top-level record
        // list; the complete component payload lives once under its semantic
        // timeframe instead of being duplicated in the clipboard.
        records: Object.values(timeframes).flat().map(record => ({
            id: record.id,
            timeframe: record.timeframe,
            direction: record.direction,
            event_time: record.event_time,
            completeness: record.completeness,
            evidence_ids: record.evidence_ids
        })),
        note: activity.note || 'OHLC-derived market footprints describe price-action sequences consistent with institutional-style participation; they do not identify actual participants.'
    }) || null;
}

function compactAiTarget(target = {}, fallbackDirection = null) {
    if (!target || typeof target !== 'object') return null;
    return {
        id: target.id || target.target_id || null,
        direction: target.direction || fallbackDirection || null,
        timeframe: target.timeframe || null,
        level: compactEvidenceNumber(target.level, target.target_level, target.price),
        source: target.primary_target_source || target.source || null,
        type: target.target_type || target.type || null,
        lifecycle_state: target.target_lifecycle_state || target.lifecycle_state || target.state || null,
        reached: target.reached === true || target.consumed === true || target.invalidated === true,
        structural_priority: target.structural_priority ?? null,
        evidence_ids: Array.isArray(target.evidence_ids) ? target.evidence_ids.filter(id => typeof id === 'string').slice(0, 12) : []
    };
}

function compactAiPathQuality(candidate = {}) {
    const evaluated = marketMechanicsPathEvaluation(candidate);
    const explicitClearPath = candidate.clear_path_to_tp1 ?? candidate.CLEAR_PATH_TO_TP1;
    return {
        trade_qualified: evaluated.pass && candidate.trade_qualified !== false && candidate.TRADE_QUALIFIED !== 'NO',
        entry_inside_opposing_4h: candidate.entry_inside_opposing_4h || candidate.ENTRY_INSIDE_OPPOSING_4H || 'NO',
        opposing_4h_barrier_before_tp1: candidate.opposing_4h_barrier_before_tp1 || candidate.OPPOSING_4H_BARRIER_BEFORE_TP1 || 'NO',
        nearest_opposing_4h_ref: candidate.nearest_opposing_4h_ref || candidate.NEAREST_OPPOSING_4H_REF || 'NONE',
        nearest_opposing_4h_type: candidate.nearest_opposing_4h_type || candidate.NEAREST_OPPOSING_4H_TYPE || 'NONE',
        nearest_opposing_4h_zone: candidate.nearest_opposing_4h_zone || candidate.NEAREST_OPPOSING_4H_ZONE || 'NONE',
        barrier_distance_r: candidate.barrier_distance_r ?? candidate.BARRIER_DISTANCE_R ?? null,
        clear_path_to_tp1: explicitClearPath ?? (evaluated.pass && evaluated.status === 'CLEAR' ? 'YES' : 'UNKNOWN'),
        path_quality_penalty: Number(candidate.path_quality_penalty ?? candidate.PATH_QUALITY_PENALTY) || 0,
        qualification_blockers: [...new Set([
            ...(candidate.qualification_blockers || candidate.QUALIFICATION_BLOCKERS || []),
            ...(evaluated.incomplete ? ['PATH_INCOMPLETE'] : []),
            ...(evaluated.blocked ? ['PATH_BLOCKED'] : [])
        ])]
    };
}

const AI_PATH_QUALITY_FIELDS = Object.freeze([
    'TRADE_QUALIFIED',
    'ENTRY_INSIDE_OPPOSING_4H',
    'OPPOSING_4H_BARRIER_BEFORE_TP1',
    'NEAREST_OPPOSING_4H_REF',
    'NEAREST_OPPOSING_4H_TYPE',
    'NEAREST_OPPOSING_4H_ZONE',
    'BARRIER_DISTANCE_R',
    'CLEAR_PATH_TO_TP1',
    'PATH_QUALITY_PENALTY',
    'QUALIFICATION_BLOCKERS'
]);
const AI_PATH_QUALITY_DEFAULTS = Object.freeze(['NO', 'NO', 'NO', 'NONE', 'NONE', 'NONE', null, 'UNKNOWN', 0, ['PATH_INCOMPLETE']]);

function compactAiPathQualityVector(candidate = {}) {
    const path = compactAiPathQuality(candidate);
    return [
        path.trade_qualified ? 'YES' : 'NO',
        path.entry_inside_opposing_4h,
        path.opposing_4h_barrier_before_tp1,
        path.nearest_opposing_4h_ref,
        path.nearest_opposing_4h_type,
        path.nearest_opposing_4h_zone,
        path.barrier_distance_r,
        path.clear_path_to_tp1,
        path.path_quality_penalty,
        path.qualification_blockers
    ];
}

function compactAiCandidate(candidate = {}, options = {}) {
    const setup = candidate.strategy_setup || {};
    const relevance = candidate.current_opportunity_relevance || {};
    const lifecycleMetrics = candidate.evaluation?.metrics?.setup_lifecycle || candidate.setup_lifecycle || {};
    const targetMap = [
        ...(Array.isArray(candidate.target_map) ? candidate.target_map : []),
        ...(Array.isArray(candidate.target_candidates) ? candidate.target_candidates : [])
    ];
    const targetRecords = targetMap.map(target => compactAiTarget(target, candidate.direction)).filter(Boolean);
    const strategyLabels = [...new Set([
        candidate.strategy_label,
        candidate.strategy,
        setup.label,
        setup.primary,
        ...(Array.isArray(candidate.strategy_confluence) ? candidate.strategy_confluence : [])
    ].filter(Boolean))];
    const sourceEvidenceIds = [...new Set([
        ...(Array.isArray(candidate.source_evidence_ids) ? candidate.source_evidence_ids : []),
        ...(Array.isArray(setup.structural_evidence_ids) ? setup.structural_evidence_ids : [])
    ].filter(id => typeof id === 'string'))];
    const invalidation = candidate.structural_invalidation || candidate.structural_invalidation_detail || {};
    return {
        id: candidate.id || null,
        candidate_id: candidate.id || null,
        ...(candidate.AUTHORITY_MODE || candidate.authority_mode ? {
            authority_mode: candidate.AUTHORITY_MODE || candidate.authority_mode,
            candidate_authority: candidate.CANDIDATE_AUTHORITY || candidate.candidate_authority || null,
            market_plan_valid: candidate.MARKET_PLAN_VALID || candidate.market_plan_valid || null,
            poi_valid: candidate.POI_VALID || candidate.poi_valid || null,
            entry_model_qualified: candidate.MODEL_QUALIFIED || candidate.model_qualified || null,
            trade_qualified: candidate.TRADE_QUALIFIED || (candidate.trade_qualified === true ? 'YES' : candidate.trade_qualified === false ? 'NO' : null),
            qualification_blockers: Array.isArray(candidate.QUALIFICATION_BLOCKERS)
                ? candidate.QUALIFICATION_BLOCKERS.slice(0, 12)
                : Array.isArray(candidate.qualification_blockers) ? candidate.qualification_blockers.slice(0, 12) : []
        } : {}),
        candidate_role: candidate.candidate_role || candidate.current_opportunity_role || relevance.candidate_role || null,
        current_opportunity_source: candidate.current_opportunity_source || setup.current_opportunity_source || null,
        direction: candidate.direction || null,
        strategy_label: strategyLabels[0] || null,
        strategy_family: strategyLabels,
        setup_timeframe: candidate.setup_timeframe || candidate.timeframe || null,
        execution_timeframe: candidate.execution_timeframe || candidate.timeframe || null,
        execution_model: candidate.execution_model || candidate.entry_model || null,
        entry_model: candidate.entry_model || candidate.execution_model || null,
        source_evidence_ids: sourceEvidenceIds,
        poi: {
            id: candidate.zone?.id || candidate.execution_zone_id || null,
            type: candidate.zone_type || candidate.zone?.type || null,
            low: candidate.zone_low ?? candidate.entry_region_low ?? candidate.zone?.low ?? null,
            high: candidate.zone_high ?? candidate.entry_region_high ?? candidate.zone?.high ?? null,
            freshness: candidate.freshness || candidate.freshness_state || null,
            mitigation_state: candidate.mitigation_state || candidate.mitigation || null
        },
        execution: {
            entry: candidate.entry ?? null,
            stop_loss: candidate.stop_loss ?? null,
            structural_invalidation_id: invalidation.id || candidate.structural_invalidation_id || null,
            structural_invalidation_level: invalidation.level ?? candidate.structural_invalidation_anchor ?? null,
            structural_invalidation_source: invalidation.source || candidate.structural_invalidation_source || null,
            targets: targetRecords,
            rr: candidate.actual_rr ?? candidate.rr_tp1 ?? candidate.risk_reward ?? null
        },
        ...(options.includePathQuality ? { path_quality: compactAiPathQuality(candidate) } : {}),
        lifecycle: {
            state: candidate.lifecycle_state || candidate.opportunity_status || lifecycleMetrics.opportunity_status || null,
            opportunity_freshness: candidate.opportunity_freshness || lifecycleMetrics.opportunity_freshness || null,
            poi_freshness: candidate.poi_freshness || candidate.freshness || candidate.zone?.freshness || lifecycleMetrics.poi_freshness || null,
            formation_time: candidate.execution_zone_created_time || candidate.event_time || candidate.parent_event_time_ms || null,
            still_actionable_today: candidate.still_actionable_today ?? null,
            entry_consumed: candidate.entry_consumed ?? null,
            tp1_already_reached: candidate.tp1_already_reached ?? null,
            target_lifecycle_state: candidate.target_lifecycle_state || targetRecords[0]?.lifecycle_state || null
        },
        delivery: {
            continuation_state: candidate.continuation_state || relevance.continuation_state || null,
            delivery_fraction: candidate.delivery_fraction ?? relevance.delivery_fraction ?? null,
            remaining_reward_fraction: candidate.remaining_reward_fraction ?? relevance.remaining_reward_fraction ?? null,
            delivery_after_formation: candidate.delivery_after_formation ?? lifecycleMetrics.delivery_after_formation ?? null,
            formation_progress_to_tp1_fraction: candidate.formation_progress_to_tp1_fraction ?? lifecycleMetrics.formation_progress_to_tp1_fraction ?? null,
            post_formation_delivery_progress: candidate.post_formation_delivery_progress ?? lifecycleMetrics.post_formation_delivery_progress ?? null,
            delivery_threshold: candidate.delivery_threshold ?? lifecycleMetrics.delivery_threshold ?? null,
            entry_retracement_distance: relevance.entry_retracement_distance ?? candidate.distance_from_current_price ?? null,
            remaining_structural_objectives: candidate.remaining_structural_objectives ?? relevance.remaining_structural_objectives ?? null
        },
        current_opportunity_relevance: {
            candidate_role: candidate.candidate_role || candidate.current_opportunity_role || relevance.candidate_role || null,
            continuation_state: candidate.continuation_state || relevance.continuation_state || null,
            delivery_fraction: candidate.delivery_fraction ?? relevance.delivery_fraction ?? null,
            remaining_reward_fraction: candidate.remaining_reward_fraction ?? relevance.remaining_reward_fraction ?? null,
            entry_retracement_distance: relevance.entry_retracement_distance ?? candidate.distance_from_current_price ?? null,
            remaining_structural_objectives: candidate.remaining_structural_objectives ?? relevance.remaining_structural_objectives ?? null
        },
        quality_warnings: Array.isArray(candidate.quality_warnings)
            ? candidate.quality_warnings.slice(0, 12)
            : Array.isArray(candidate.quality?.warnings) ? candidate.quality.warnings.slice(0, 12) : [],
        deterministic_valid: candidate.deterministic_valid ?? true
    };
}

function compactAiNeutralObjective(target = {}) {
    if (!target || typeof target !== 'object') return null;
    const level = compactEvidenceNumber(target.level, target.target_level, target.price);
    const lifecycle = target.lifecycle_state || target.target_lifecycle_state || target.state || null;
    const rawType = target.type || target.target_type || null;
    const rawSource = target.source || target.primary_target_source || target.origin || null;
    const normalizedType = String(rawType || '').replace(/^OPPOSING_/, '') || null;
    const normalizedSource = String(rawSource || '').replace(/^(BUY|SELL)_SIDE_LIQUIDITY$/, 'LIQUIDITY').replace(/^OPPOSING_/, '') || null;
    if (level == null && !target.id && !target.target_id) return null;
    return {
        objective_id: target.objective_id || target.id || target.target_id
            || `OBJECTIVE:${target.timeframe || 'NA'}:${normalizedType || normalizedSource || 'LEVEL'}:${level ?? 'NA'}`,
        timeframe: target.timeframe || null,
        level,
        source: normalizedSource,
        type: normalizedType,
        objective_class: target.objective_class || target.target_type || rawType || normalizedSource || 'STRUCTURAL_OBJECTIVE',
        liquidity_side: target.liquidity_side || deriveObjectiveLiquiditySide({ ...target, source: rawSource, type: rawType, target_type: rawType }),
        source_relation_at_detection: target.source_relation_at_detection
            || target.source_relation
            || deriveObjectiveSourceRelation({ ...target, source: rawSource, type: rawType, target_type: rawType })
            || (String(rawSource || '').toUpperCase().includes('SIDE_LIQUIDITY')
                ? (String(target.direction || '').toUpperCase() === 'BUY' ? 'ABOVE_REFERENCE_AT_DETECTION'
                    : String(target.direction || '').toUpperCase() === 'SELL' ? 'BELOW_REFERENCE_AT_DETECTION' : null)
                : null),
        source_orientation_if_factual: deriveCanonicalObjectiveDirection(target),
        source_record_type: rawType,
        source_record_source: rawSource,
        event_time: target.event_time || target.formation_time || target.created_time || null,
        lifecycle_state: lifecycle,
        reached: target.reached === true || lifecycle === 'CONSUMED' || lifecycle === 'INVALIDATED',
        consumed: lifecycle === 'CONSUMED',
        invalidated: lifecycle === 'INVALIDATED',
        evidence_ids: Array.isArray(target.evidence_ids) ? target.evidence_ids.filter(id => typeof id === 'string').slice(0, 12) : []
    };
}

function compactAiOpportunityMaterial(candidate = {}, catalogStatus = 'CURRENT_MATERIAL') {
    const compact = compactAiCandidate(candidate, { includePathQuality: false });
    if (!compact?.candidate_id) return null;
    const rejectionCodes = [...new Set([
        candidate.rejection_code,
        ...(Array.isArray(candidate.rejection_reasons) ? candidate.rejection_reasons : []),
        ...(Array.isArray(candidate.hard_rejections) ? candidate.hard_rejections : []),
        ...(Array.isArray(candidate.qualification_blockers) ? candidate.qualification_blockers : [])
    ].filter(Boolean))].slice(0, 12);
    return {
        ...compact,
        catalog_status: catalogStatus,
        rejection_codes: rejectionCodes,
        hard_invalid: candidate.hard_invalid === true || candidate.hard_invalidity === true
    };
}

function compactAiTimeframeEvidence(timeframe, source = {}, fallbackStructure = {}, options = {}) {
    const manualEvidenceOnly = options.manualEvidenceOnly === true;
    const structure = source.structure || fallbackStructure || {};
    const referenceTime = source.last_closed_candle_time
        || source.raw_closed_candles?.at(-1)?.t
        || options.referenceTime
        || null;
    const compactLocations = (items, type, maxItems = MANUAL_PACKET_MAX_LOCATIONS_PER_TIMEFRAME) => {
        const relevant = manualEvidenceOnly
            ? selectManualPacketRecords(items, timeframe, referenceTime, maxItems)
            : (Array.isArray(items) ? items : []);
        return relevant.map(item => {
            const compact = compactAiEvidenceItem(item, type, timeframe);
            if (manualEvidenceOnly && compact) {
                const model = canonicalModelToken(item.type || item.event_type || type);
                compact.model_semantics_id = item.model_semantics_id || getModelSemantics(model).model_semantics_id;
                compact.source_orientation = item.source_orientation || item.orientation || item.source_direction || item.direction || null;
                compact.role_reversal = item.role_reversal === true || item.flipped === true || item.reclaim_confirmed === true;
                compact.origin_time = item.origin_time || item.formation_time || item.source_time || null;
                compact.confirmation_time = item.confirmation_time || item.event_time || item.reclaim_time || null;
                compact.first_knowable_time = item.first_knowable_time || item.confirmation_time || item.event_time || compact.event_time || null;
                compact.invalidation_basis = item.invalidation_basis || deriveInvalidationBasis(item, model);
                compact.invalidation_confirmation_mode = item.invalidation_confirmation_mode || item.confirmation_mode || null;
                compact.lifecycle_invalidation = item.lifecycle_invalidation || null;
                compact.execution_invalidation = item.execution_invalidation || null;
            }
            return manualEvidenceOnly ? (compactManualPacketValue(compact) || null) : compact;
        }).filter(Boolean);
    };
    const allLocationItems = [
        ...(Array.isArray(source.fvg) ? source.fvg : []),
        ...(Array.isArray(source.order_blocks?.buy) ? source.order_blocks.buy : []),
        ...(Array.isArray(source.order_blocks?.sell) ? source.order_blocks.sell : []),
        ...(Array.isArray(source.msnr_levels) ? source.msnr_levels : []),
        ...(Array.isArray(source.structural_pois) ? source.structural_pois : []),
        ...(Array.isArray(source.zones) ? source.zones : [])
    ];
    const locationSources = [
        ...compactLocations(source.fvg, 'FVG'),
        ...compactLocations(source.order_blocks?.buy, 'OB'),
        ...compactLocations(source.order_blocks?.sell, 'OB'),
        ...compactLocations(source.msnr_levels, 'MSNR'),
        ...compactLocations(source.structural_pois, 'POI'),
        ...compactLocations(source.zones, 'ZONE')
    ];
    const locations = manualEvidenceOnly
        ? selectManualPacketRecords(locationSources, timeframe, referenceTime, MANUAL_PACKET_MAX_LOCATIONS_PER_TIMEFRAME)
        : locationSources;
    const liquidity = source.liquidity && typeof source.liquidity === 'object'
        ? Object.fromEntries(Object.entries(source.liquidity).map(([key, values]) => {
            const normalizedValues = (Array.isArray(values) ? values : []).map(item => {
                if (typeof item !== 'number' && typeof item !== 'string') return item;
                const level = Number(item);
                return Number.isFinite(level) ? { id: `LIQUIDITY:${timeframe}:${key}:${level}`, type: key, source: key, timeframe, level } : null;
            }).filter(Boolean);
            const selectedValues = manualEvidenceOnly
                ? selectManualPacketRecords(normalizedValues, timeframe, referenceTime, 16)
                : normalizedValues;
            return [key, selectedValues.map(item => {
                const compact = compactAiEvidenceItem(item, key, timeframe);
                return manualEvidenceOnly ? (compactManualPacketValue(compact) || null) : compact;
            }).filter(Boolean)];
        }))
        : {};
    const structuralInvalidationItems = manualEvidenceOnly
        ? allLocationItems.filter(item => item?.structural_invalidation || item?.structural_invalidation_detail || item?.structural_invalidation_level != null || item?.invalidation_level != null || item?.invalidation != null)
        : locations;
    const structuralInvalidations = [...new Map(structuralInvalidationItems.map(item => {
        const normalizedItem = manualEvidenceOnly && Number.isFinite(Number(item?.structural_invalidation)) && !item?.structural_invalidation_detail
            ? { ...item, structural_invalidation_detail: { level: Number(item.structural_invalidation), source: item.structural_invalidation_source || null } }
            : item;
        const compact = compactAiStructuralInvalidation(normalizedItem, timeframe);
        return manualEvidenceOnly ? (compactManualPacketValue(compact) || null) : compact;
    }).filter(Boolean).map(item => [item.evidence_id || item.id, item])).values()];
    const swingHighs = compactLocations(structure.swing_highs || structure.recent_swing_highs, 'SWING_HIGH', 8);
    const swingLows = compactLocations(structure.swing_lows || structure.recent_swing_lows, 'SWING_LOW', 8);
    const evidence = compactLocations(source.evidence, 'STRUCTURE_EVIDENCE', MANUAL_PACKET_MAX_EVENTS_PER_TIMEFRAME);
    const compacted = {
        timeframe,
        role: source.role || null,
        last_closed_time: source.last_closed_time || source.last_closed_candle_time || null,
        closed_candle_count: source.closed_candle_count ?? null,
        current_closed_price: source.current_closed_price ?? null,
        structure: {
            structural_trend: structure.structural_trend || structure.trend || null,
            momentum_trend: structure.momentum_trend || null,
            effective_trend: structure.effective_trend || structure.trend || null,
            bias: manualEvidenceOnly ? null : (structure.bias || null),
            sequence: Array.isArray(structure.sequence) ? structure.sequence.slice(-12) : [],
            swing_highs: swingHighs,
            swing_lows: swingLows,
            bos: manualEvidenceOnly
                ? (structure.confirmed_bos || null)
                : (structure.bos || { buy: !!structure.bos_buy, sell: !!structure.bos_sell }),
            choch: manualEvidenceOnly
                ? (structure.confirmed_choch || null)
                : (structure.choch || { buy: !!structure.choch_buy, sell: !!structure.choch_sell }),
            mss: manualEvidenceOnly
                ? (compactManualPacketValue(compactAiEvidenceItem(structure.confirmed_mss, 'MSS', timeframe)) || null)
                : compactAiEvidenceItem(structure.mss, 'MSS', timeframe),
            displacement: manualEvidenceOnly ? (compactManualPacketValue(structure.displacement) || null) : (structure.displacement || null)
        },
        ...(manualEvidenceOnly && Array.isArray(source.confirmed_structure_events) ? {
            confirmed_structure_events: source.confirmed_structure_events.map(event => manualDecisionEvent(event, event?.event_type || 'STRUCTURE_EVENT', timeframe)).filter(Boolean).slice(-MANUAL_PACKET_MAX_EVENTS_PER_TIMEFRAME)
        } : {}),
        liquidity,
        locations,
        structural_invalidations: structuralInvalidations,
        premium_discount: source.premium_discount || null,
        dealing_range: source.dealing_range || null,
        previous_period: source.previous_period || null,
        previous_day_levels: source.previous_day_levels || null,
        atr: source.atr ?? null,
        structural_evidence_ids: Array.isArray(source.structural_evidence_ids) ? source.structural_evidence_ids : [],
        evidence
    };
    if (manualEvidenceOnly) {
        compacted.recent_closed_candles = buildManualRecentClosedCandles(timeframe, source, referenceTime);
    }
    return compacted;
}

function buildCompactAISemanticPackage(liveMarketContext = {}, evidenceCatalog = {}, options = {}) {
    const manualOpportunityDiscovery = options.manualOpportunityDiscovery === true;
    const evidencePackage = liveMarketContext.market_evidence_package?.timeframes
        ? liveMarketContext.market_evidence_package
        : evidenceCatalog.market_evidence_package || {};
    const evidenceTimeframes = evidencePackage.timeframes || {};
    const institutionalActivityEvidence = evidencePackage.institutional_activity_evidence
        || evidenceCatalog.institutional_activity_evidence
        || liveMarketContext.institutional_activity_evidence
        || null;
    const packetReferenceTime = liveMarketContext.as_of_time_utc
        || liveMarketContext.as_of_time
        || evidencePackage.as_of_time
        || evidenceCatalog.as_of_time_utc
        || null;
    const structure = Object.fromEntries(AI_SEMANTIC_TIMEFRAMES.map(tf => [tf,
        compactAiTimeframeEvidence(tf, evidenceTimeframes[tf] || {}, liveMarketContext.structure?.[tf] || {}, {
            manualEvidenceOnly: manualOpportunityDiscovery,
            referenceTime: packetReferenceTime
        })]));
    const rawSourceCandidates = Array.isArray(liveMarketContext.adaptive_setup_candidates)
        ? liveMarketContext.adaptive_setup_candidates
        : Array.isArray(liveMarketContext.valid_deterministic_candidates) ? liveMarketContext.valid_deterministic_candidates : [];
    const authorityMode = isMarketMechanicsMode(liveMarketContext) ? 'MARKET_MECHANICS' : String(liveMarketContext.strategy_mode || rawTextV2StrategyMode()).toUpperCase();
    const sourceCandidates = authorityMode === 'MARKET_MECHANICS'
        ? marketMechanicsLiveCandidates({ ...liveMarketContext, adaptive_setup_candidates: rawSourceCandidates })
        : rawSourceCandidates;
    const authoritySummary = authorityMode === 'MARKET_MECHANICS'
        ? marketMechanicsAuthoritySummary({ ...liveMarketContext, strategy_mode: 'MARKET_MECHANICS', adaptive_setup_candidates: rawSourceCandidates })
        : null;
    const pathQualityByCandidate = manualOpportunityDiscovery ? {} : Object.fromEntries(sourceCandidates
        .filter(candidate => candidate?.id)
        .map(candidate => [candidate.id, compactAiPathQualityVector(candidate)])
        .filter(([, vector]) => JSON.stringify(vector) !== JSON.stringify(AI_PATH_QUALITY_DEFAULTS)));
    const selectable = manualOpportunityDiscovery ? [] : [...new Map(sourceCandidates
        .filter(candidate => ['FRESH_NOW', 'FRESH_PENDING_TODAY', 'FRESH_PENDING_LATER', 'QUALIFIED_PENDING', 'PENDING_UNFILLED'].includes(candidate?.lifecycle_state || candidate?.opportunity_status))
        .filter(candidate => candidate?.id)
        .map(candidate => [candidate.id, compactAiCandidate(candidate)])).values()];
    const opportunityMaterialSource = evidenceCatalog.opportunity_material?.records
        || liveMarketContext.market_evidence_package?.opportunity_material?.records
        || [];
    const opportunityMaterial = manualOpportunityDiscovery ? [] : [...new Map(opportunityMaterialSource.filter(record => record?.candidate_id).map(record => [record.candidate_id, record])).values()].slice(0, 48);
    const locations = Object.values(structure).flatMap(timeframe => Array.isArray(timeframe?.locations) ? timeframe.locations : []);
    const buyLocations = locations.filter(location => String(location?.direction || '').toUpperCase() === 'BUY');
    const sellLocations = locations.filter(location => String(location?.direction || '').toUpperCase() === 'SELL');
    const targetRecords = [];
    const addTarget = (target, direction = null) => {
        if (manualOpportunityDiscovery) {
            const targetState = String(target?.target_lifecycle_state || target?.lifecycle_state || target?.state || '').toUpperCase();
            if (target?.reached === true || target?.consumed === true || target?.invalidated === true
                || ['CONSUMED', 'INVALIDATED', 'TARGET_DELIVERED'].includes(targetState)) return;
            if (!manualPacketIsRelevant(target, target?.timeframe || null, packetReferenceTime)) return;
        }
        const compact = compactAiTarget(target, direction);
        if (!compact || !Number.isFinite(Number(compact.level))) return;
        const key = compact.id || `${compact.direction || ''}:${compact.level}:${compact.source || ''}`;
        if (!targetRecords.some(existing => (existing.id || `${existing.direction || ''}:${existing.level}:${existing.source || ''}`) === key)) targetRecords.push(compact);
    };
    for (const candidate of selectable) for (const target of candidate.execution?.targets || []) addTarget(target, candidate.direction);
    const targetCatalog = liveMarketContext.target_candidates || evidenceCatalog.target_candidates || {};
    for (const direction of ['all', 'buy', 'sell']) for (const target of (targetCatalog[direction] || [])) {
        addTarget(target, direction === 'all' ? null : direction.toUpperCase());
    }
    const evidenceArrays = [
        ...(evidenceCatalog.strategy_events || []),
        ...(evidenceCatalog.crt_events || []),
        ...(evidenceCatalog.tbs_events || []),
        ...(evidenceCatalog.msnr_levels || []),
        ...(manualOpportunityDiscovery ? [] : (evidenceCatalog.fvg_zones || [])),
        ...(manualOpportunityDiscovery ? [] : (evidenceCatalog.ob_zones || [])),
        ...(manualOpportunityDiscovery ? [] : (evidenceCatalog.execution_zones || []))
    ];
    const evidenceById = new Map();
    const relevantEvidence = manualOpportunityDiscovery
        ? AI_SEMANTIC_TIMEFRAMES.flatMap(timeframe => selectManualPacketRecords(
            evidenceArrays.filter(item => !item?.timeframe || item.timeframe === timeframe),
            timeframe,
            packetReferenceTime,
            MANUAL_PACKET_MAX_EVENTS_PER_TIMEFRAME
        ))
        : evidenceArrays;
    for (const item of relevantEvidence) {
        const compact = compactAiEvidenceItem(item, item?.strategy || item?.type, item?.timeframe);
        if (compact?.id && !evidenceById.has(compact.id)) evidenceById.set(compact.id, compact);
    }
    const rejected = liveMarketContext.rejected_setup_candidates || [];
    const rejectionCounts = {};
    const rejectedRecords = rejected.map(item => {
        const codes = [...new Set([item?.rejection_code, ...(item?.rejection_reasons || [])].filter(Boolean))];
        for (const code of codes) rejectionCounts[code] = (rejectionCounts[code] || 0) + 1;
        return { id: item?.id || null, candidate_id: item?.id || null, rejection_code: codes[0] || null, rejection_codes: codes, direction: item?.direction || null, timeframe: item?.timeframe || null };
    }).filter(item => item.candidate_id);
    const marketContext = liveMarketContext.market_context || {};
    const multiTimeframeTrend = liveMarketContext.multi_timeframe_direction?.trend || Object.fromEntries(AI_SEMANTIC_TIMEFRAMES.map(tf => [tf, structure[tf].structure.effective_trend]));
    const regeneration = liveMarketContext.current_opportunity_regeneration || {};
    // Manual discovery receives market locations as neutral facts.  A
    // location is not a trade until the external AI interprets the complete
    // market context and chooses direction.  Keep the directional buckets
    // only for the automatic/internal selector path.
    const locationFacts = manualOpportunityDiscovery
        ? { locations }
        : { buy: buyLocations.slice(0, 120), sell: sellLocations.slice(0, 120) };
    const invalidationFacts = Object.fromEntries(AI_SEMANTIC_TIMEFRAMES.map(tf => [tf, structure[tf].structural_invalidations || []]));
    for (const item of evidenceById.values()) {
        const invalidation = item?.structural_invalidation;
        const timeframe = AI_SEMANTIC_TIMEFRAMES.includes(item?.timeframe) ? item.timeframe : null;
        if (!invalidation || !timeframe || !item.id) continue;
        if (invalidationFacts[timeframe].some(existing => (existing.evidence_id || existing.id) === item.id)) continue;
        invalidationFacts[timeframe].push({
            id: item.id,
            evidence_id: item.id,
            type: item.type || 'STRUCTURAL_INVALIDATION',
            timeframe,
            level: invalidation.level ?? null,
            source: invalidation.source || null,
            event_time: item.event_time || null,
            source_location_id: item.source_location_id || invalidation.source_location_id || null,
            source_model: item.source_model || invalidation.source_model || null,
            source_event_id: item.source_event_id || invalidation.source_event_id || item.id || null,
            source_price: invalidation.source_price ?? invalidation.level ?? null,
            invalidation_basis: item.invalidation_basis || invalidation.invalidation_basis || invalidation.basis || null,
            confirmation_mode: item.confirmation_mode || invalidation.confirmation_mode || null,
            state: item.state || null,
            invalidated: item.invalidated === true,
            evidence_ids: [...new Set([item.id, ...(item.evidence_ids || [])])].slice(0, 12)
        });
    }
    const deliveryLocations = manualOpportunityDiscovery
        ? locationFacts.locations
        : [...locationFacts.buy, ...locationFacts.sell];
    const deliveryFacts = {
        locations: deliveryLocations
            .filter(location => location?.freshness || location?.mitigation_state || location?.state || location?.consumed || location?.invalidated)
            .map(location => manualOpportunityDiscovery ? compactManualPacketValue({
                id: location.id,
                type: location.type,
                timeframe: location.timeframe,
                formation_time: location.formation_time || location.event_time,
                freshness: location.freshness,
                mitigation_state: location.mitigation_state,
                lifecycle_state: location.lifecycle_state,
                invalidated: location.invalidated,
                consumed: location.consumed,
                evidence_ids: location.evidence_ids
            }) : location).filter(Boolean),
        targets: manualOpportunityDiscovery
            ? targetRecords.map(compactAiNeutralObjective).filter(Boolean)
            : targetRecords.map(target => ({ id: target.id, direction: target.direction, timeframe: target.timeframe, type: target.type, source: target.source, level: target.level, lifecycle_state: target.lifecycle_state, reached: target.reached, evidence_ids: target.evidence_ids }))
    };
    const automaticDirectionalContext = {
        daily_bias: liveMarketContext.daily_bias || marketContext.daily_bias || null,
        directional_bias: marketContext.directional_bias || null,
        liquidity_draw: marketContext.liquidity?.draw || marketContext.liquidity?.liquidity_draw || null,
        dealing_range_position: liveMarketContext.premium_discount?.zone || marketContext.premium_discount?.zone || null,
        conflicts: marketContext.conflicts || [],
        structural_invalidation_ids: Array.isArray(liveMarketContext.daily_bias?.invalidation_evidence_ids) ? liveMarketContext.daily_bias.invalidation_evidence_ids : [],
        multi_timeframe_trend: multiTimeframeTrend,
        volatility: liveMarketContext.volatility || marketContext.volatility || null,
        market_regime: liveMarketContext.market_regime?.primary_regime || liveMarketContext.market_regime?.regime || marketContext.market_regime || null
    };
    const manualMarketFactContext = {
        timeframe_structure: multiTimeframeTrend,
        dealing_range_position: liveMarketContext.premium_discount?.zone || marketContext.premium_discount?.zone || null,
        conflicts: marketContext.conflicts || [],
        volatility_facts: liveMarketContext.volatility || marketContext.volatility || null
    };
    return {
        schema_version: 2,
        package_type: 'AI_SEMANTIC_MARKET',
        authority_mode: authorityMode,
        live_authority: authorityMode,
        active_authority_count: authorityMode === 'MARKET_MECHANICS'
            ? (authoritySummary?.active_authority_count || 0)
            : 1,
        legacy_trade_authority: authorityMode === 'MARKET_MECHANICS' ? 'DISABLED' : 'ENABLED_IN_EXPLICIT_MODE',
        authority_invariants: authorityMode === 'MARKET_MECHANICS'
            ? (authoritySummary?.invariants || 'FAIL')
            : 'NOT_APPLICABLE',
        authority_invariant_violation: authorityMode === 'MARKET_MECHANICS'
            ? (authoritySummary?.invariant_violation || null)
            : null,
        snapshot: {
            snapshot_id: liveMarketContext.snapshot_id || evidencePackage.snapshot_id || null,
            pair: liveMarketContext.pair || evidenceCatalog.pair || null,
            provider: getMarketDataProvider(),
            as_of: liveMarketContext.as_of_time_utc || liveMarketContext.as_of_time || evidenceCatalog.as_of_time_utc || null,
            current_price: liveMarketContext.current_price ?? evidenceCatalog.current_price ?? null,
            ...(manualOpportunityDiscovery ? {
                asset_class: liveMarketContext.asset_class || liveMarketContext.symbol_metadata?.asset_class || evidenceCatalog.symbol_metadata?.asset_class || null,
                session: liveMarketContext.session || evidenceCatalog.session || null,
                volatility: liveMarketContext.volatility || evidenceCatalog.volatility || null
            } : {})
        },
        ...(authorityMode === 'MARKET_MECHANICS' ? {
            market_plan: liveMarketContext.market_plan || liveMarketContext.market_context?.market_plan || null,
            market_mechanics: liveMarketContext.market_mechanics || null
        } : {}),
        timeframes: structure,
        institutional_activity_evidence: manualOpportunityDiscovery
            ? compactManualInstitutionalActivityEvidence(institutionalActivityEvidence, packetReferenceTime)
            : institutionalActivityEvidence,
        ...(manualOpportunityDiscovery
            ? {
                market_fact_context: manualMarketFactContext,
                market_observations: {
                    structural_observations: multiTimeframeTrend,
                    delivery_facts: deliveryFacts,
                    conflicts: marketContext.conflicts || []
                }
            }
            : {
                directional_context: automaticDirectionalContext,
                phase_evidence: {
                    current_regime: liveMarketContext.market_regime?.primary_regime || liveMarketContext.market_regime?.regime || null,
                    current_structure: multiTimeframeTrend,
                    delivery_by_candidate: selectable.map(candidate => ({ candidate_id: candidate.candidate_id, candidate_role: candidate.candidate_role, continuation_state: candidate.delivery.continuation_state, delivery_fraction: candidate.delivery.delivery_fraction, remaining_reward_fraction: candidate.delivery.remaining_reward_fraction })),
                    conflicts: marketContext.conflicts || [],
                    liquidity: marketContext.liquidity || null
                }
            }),
        selectable_opportunities: manualOpportunityDiscovery ? [] : selectable,
        live_market_mechanics_candidates: authorityMode === 'MARKET_MECHANICS' && !manualOpportunityDiscovery ? selectable : [],
        forming_market_mechanics_setups: authorityMode === 'MARKET_MECHANICS'
            ? (liveMarketContext.market_mechanics?.model_states || []).filter(item => item.state && item.state !== 'QUALIFIED')
            : [],
        legacy_diagnostic_candidates: authorityMode === 'MARKET_MECHANICS'
            ? (liveMarketContext.legacy_diagnostic_candidates || rawSourceCandidates
                .map(candidate => normalizeMarketMechanicsAuthority(candidate, liveMarketContext, 'DIAGNOSTIC_ONLY'))
                .filter(candidate => candidate.CANDIDATE_AUTHORITY === 'DIAGNOSTIC_ONLY'))
            : [],
        path_quality_by_candidate: pathQualityByCandidate,
        // Compatibility aliases are intentionally compact records, not the
        // old nested replay candidates.
        adaptive_setup_candidates: manualOpportunityDiscovery ? [] : selectable,
        candidate_catalog: manualOpportunityDiscovery ? [] : authorityMode === 'MARKET_MECHANICS'
            ? selectable.map(candidate => ({ ...candidate, catalog_status: 'VALID_SELECTABLE', candidate_authority: 'LIVE' }))
            : [
                ...selectable.map(candidate => ({ ...candidate, catalog_status: 'VALID_SELECTABLE' })),
                ...opportunityMaterial.filter(candidate => !selectable.some(selected => selected.candidate_id === candidate.candidate_id)),
                ...rejectedRecords.map(record => ({ ...record, catalog_status: 'REJECTED' }))
            ],
        opportunity_material: {
            records: opportunityMaterial,
            ...(manualOpportunityDiscovery
                ? { locations: locationFacts.locations }
                : { buy_locations: locationFacts.buy, sell_locations: locationFacts.sell }),
            selection_summary: manualOpportunityDiscovery ? null : evidenceCatalog.opportunity_material || null,
            note: manualOpportunityDiscovery
                ? 'These are deterministic market locations, not preconstructed trades. The external AI must interpret them.'
                : 'CURRENT_SELECTABLE is an internal selector result only. Zero retained selectable candidates does not prove NO_TRADE.'
        },
        important_levels: Object.fromEntries(AI_SEMANTIC_TIMEFRAMES.map(tf => [tf, {
            current_closed_price: structure[tf].current_closed_price,
            swing_highs: structure[tf].structure.swing_highs,
            swing_lows: structure[tf].structure.swing_lows,
            liquidity: structure[tf].liquidity,
            dealing_range: structure[tf].dealing_range,
            previous_period: structure[tf].previous_period,
            previous_day_levels: structure[tf].previous_day_levels
        }])),
        rejected_opportunity_summary: manualOpportunityDiscovery ? null : { counts: rejectionCounts, records: rejectedRecords },
        target_context: manualOpportunityDiscovery
            ? targetRecords.map(compactAiNeutralObjective).filter(Boolean)
            : targetRecords,
        target_candidates: manualOpportunityDiscovery
            ? { all: targetRecords.map(compactAiNeutralObjective).filter(Boolean), buy: [], sell: [] }
            : { all: targetRecords, buy: targetRecords.filter(target => target.direction === 'BUY'), sell: targetRecords.filter(target => target.direction === 'SELL') },
        structural_invalidations: invalidationFacts,
        deterministic_evidence: {
            strategy_events: [...evidenceById.values()],
            evidence_id_count: evidenceById.size
        },
        strategy_detections: liveMarketContext.strategy_detections || null,
        current_opportunity_regeneration: manualOpportunityDiscovery ? null : {
            snapshot_id: regeneration.snapshot_id || liveMarketContext.snapshot_id || null,
            historical_discovered_count: regeneration.historical_discovered_count ?? null,
            historical_rejected_count: regeneration.historical_rejected_count ?? null,
            current_regenerated_count: regeneration.current_regenerated_count ?? 0,
            current_regenerated_valid_count: regeneration.current_regenerated_valid_count ?? 0,
            current_regenerated_selectable_count: regeneration.current_regenerated_selectable_count ?? 0,
            candidate_ids: regeneration.candidate_ids || regeneration.current_candidate_ids || [],
            selectable_candidate_ids: regeneration.selectable_candidate_ids || regeneration.current_selectable_candidate_ids || []
        },
        risk_constraints: {
            minimum_rr: liveMarketContext.risk_constraints?.minimum_rr ?? null,
            spread_valid: liveMarketContext.risk_constraints?.spread_valid ?? null,
            slippage_valid: liveMarketContext.risk_constraints?.slippage_valid ?? null
        }
    };
}

function manualDecisionEvent(item = {}, fallbackType = null, fallbackTimeframe = null) {
    if (!item || typeof item !== 'object') return null;
    const eventTime = manualPacketTimestampValue(item);
    const level = compactEvidenceNumber(item.level, item.price, item.midpoint, item.zone?.midpoint);
    const low = compactEvidenceNumber(item.low, item.zone?.low, item.zone_low);
    const high = compactEvidenceNumber(item.high, item.zone?.high, item.zone_high);
    if (!item.id && !item.event_id && !item.evidence_id && !eventTime && level == null && low == null && high == null && !item.direction) return null;
    const eventId = item.event_id || item.id || item.evidence_id
        || `${fallbackType || item.type || item.kind || 'EVENT'}:${fallbackTimeframe || item.timeframe || 'NA'}:${eventTime || level || `${low || ''}-${high || ''}`}`;
    if (!eventId && !eventTime && level == null && low == null && high == null) return null;
    return compactManualPacketValue({
        event_id: String(eventId),
        event_type: item.event_type || item.type || item.kind || item.strategy || fallbackType || null,
        timeframe: item.timeframe || fallbackTimeframe || null,
        direction: item.direction || null,
        time: eventTime,
        origin_time: item.origin_time || item.formation_time || item.source_time || null,
        confirmation_time: item.confirmation_time || item.event_time || item.reclaim_time || null,
        first_knowable_time: item.first_knowable_time || item.confirmation_time || item.event_time || eventTime,
        structure_event_type: item.structure_event_type || null,
        broken_swing_id: item.broken_swing_id || null,
        broken_swing_pivot_time: item.broken_swing_pivot_time || null,
        broken_swing_confirmation_time: item.broken_swing_confirmation_time || null,
        broken_level: item.broken_level ?? null,
        break_direction: item.break_direction || item.direction || null,
        confirmation_mode: item.confirmation_mode || null,
        prior_structural_state: item.prior_structural_state || null,
        resulting_structural_state: item.resulting_structural_state || null,
        level,
        zone: low != null || high != null ? { low, high } : undefined,
        state: item.state || item.lifecycle_state || item.freshness || null,
        evidence_ids: [...new Set([
            ...(Array.isArray(item.evidence_ids) ? item.evidence_ids : []),
            ...(item.id ? [item.id] : []),
            ...(item.evidence_id ? [item.evidence_id] : [])
        ].filter(id => typeof id === 'string'))].slice(0, 16)
    }) || null;
}

function buildManualDeliveryChronology(semantic = {}, referenceTime = null) {
    const events = new Map();
    const add = (item, fallbackType, timeframe, options = {}) => {
        if (!isManualCausalChronologyEvent(item, fallbackType) && !options.allowLocation) return;
        const event = manualDecisionEvent(item, fallbackType, timeframe);
        if (!event) return;
        if (options.allowLocation) event.event_type = 'LOCATION_FORMED';
        const existing = events.get(event.event_id);
        if (!existing || (event.time && !existing.time)) events.set(event.event_id, event);
    };
    for (const timeframe of AI_SEMANTIC_TIMEFRAMES) {
        const current = semantic.timeframes?.[timeframe] || {};
        const structure = current.structure || {};
        for (const item of selectManualPacketRecords(current.evidence || [], timeframe, referenceTime, MANUAL_PACKET_MAX_EVENTS_PER_TIMEFRAME)) {
            add(item, item.type || 'STRUCTURE_EVENT', timeframe);
        }
        // Locations have their own catalogue. Only retain a small number of
        // active/recent location-formation events here when they explain the
        // current delivery; the chronology is not a second location dump.
        for (const item of selectManualPacketRecords(current.locations || [], timeframe, referenceTime, 4)) {
            add(item, item.type || 'LOCATION_FORMED', timeframe, { allowLocation: true });
        }
        for (const key of ['bos', 'mss', 'choch', 'displacement']) {
            if (structure[key] && typeof structure[key] === 'object') add(structure[key], key.toUpperCase(), timeframe);
        }
        for (const values of Object.values(current.liquidity || {})) {
            for (const item of selectManualPacketRecords(values, timeframe, referenceTime, MANUAL_PACKET_MAX_EVENTS_PER_TIMEFRAME)) {
                add(item, item.type || 'LIQUIDITY_EVENT', timeframe);
            }
        }
    }
    for (const item of selectManualPacketRecords(semantic.deterministic_evidence?.strategy_events || [], null, referenceTime, 48)) {
        if (isManualCausalChronologyEvent(item, item.type || item.strategy || 'MODEL_EVENT')) add(item, item.type || item.strategy || 'MODEL_EVENT', item.timeframe);
    }
    for (const item of semantic.target_context || []) {
        const delivered = item?.reached === true || item?.consumed === true
            || ['CONSUMED', 'TARGET_DELIVERED', 'REACHED'].includes(String(item?.lifecycle_state || '').toUpperCase());
        if (delivered && manualPacketIsRelevant(item, item.timeframe, referenceTime)) add(item, 'OBJECTIVE_DELIVERY', item.timeframe);
    }
    const institutional = semantic.institutional_activity_evidence?.timeframes || {};
    for (const timeframe of AI_SEMANTIC_TIMEFRAMES) {
        for (const record of institutional[timeframe] || []) {
            for (const component of ['liquidity_event', 'displacement', 'structural_consequence', 'follow_through']) {
                add(record[component], component.toUpperCase(), timeframe);
            }
            for (const origin of record.origin_locations || []) add(origin, 'ORIGIN', timeframe);
        }
    }
    const ordered = [...events.values()].sort((a, b) => {
        const at = manualPacketEventTime(a);
        const bt = manualPacketEventTime(b);
        if (Number.isFinite(at) && Number.isFinite(bt) && at !== bt) return at - bt;
        if (Number.isFinite(at) !== Number.isFinite(bt)) return Number.isFinite(at) ? -1 : 1;
        return a.event_id.localeCompare(b.event_id);
    });
    const recent = ordered.filter(item => manualPacketIsRelevant(item, item.timeframe, referenceTime));
    return {
        ordering: 'ASCENDING_EVENT_TIME',
        events: (recent.length ? recent : ordered).slice(-96)
    };
}

function manualObjectiveRecord(target = {}, timeframe = null, sourceType = null) {
    const level = compactEvidenceNumber(target.level, target.target_level, target.price);
    if (level == null) return null;
    const source = target.source || target.primary_target_source || sourceType || null;
    const type = target.type || target.target_type || sourceType || 'LEVEL';
    const objectiveId = target.objective_id || target.id || target.target_id
        || `OBJECTIVE:${timeframe || target.timeframe || 'NA'}:${type}:${level}`;
    const lifecycle = target.lifecycle_state || target.target_lifecycle_state || target.state || null;
    return compactManualPacketValue({
        objective_id: String(objectiveId),
        timeframe: target.timeframe || timeframe || null,
        level,
        source,
        type,
        objective_class: target.objective_class || type || source || 'STRUCTURAL_OBJECTIVE',
        liquidity_side: deriveObjectiveLiquiditySide({ ...target, source, type }),
        source_relation_at_detection: deriveObjectiveSourceRelation({ ...target, source, type }),
        source_orientation_if_factual: deriveCanonicalObjectiveDirection({ ...target, objective_id: objectiveId, source, type }),
        event_time: target.event_time || target.formation_time || target.created_time || null,
        reached: target.reached === true,
        consumed: target.consumed === true || lifecycle === 'CONSUMED',
        invalidated: target.invalidated === true || lifecycle === 'INVALIDATED',
        lifecycle_state: lifecycle,
        evidence_ids: Array.isArray(target.evidence_ids) ? target.evidence_ids.filter(id => typeof id === 'string').slice(0, 16) : []
    }) || null;
}

function buildManualLiquidityObjectiveMap(semantic = {}, currentPrice = null) {
    const records = new Map();
    const add = record => {
        if (!record) return;
        if (!records.has(record.objective_id)) records.set(record.objective_id, record);
    };
    for (const target of semantic.target_context || []) add(manualObjectiveRecord(target));
    for (const timeframe of AI_SEMANTIC_TIMEFRAMES) {
        const liquidity = semantic.timeframes?.[timeframe]?.liquidity || {};
        for (const [type, values] of Object.entries(liquidity)) {
            for (const value of Array.isArray(values) ? values : []) add(manualObjectiveRecord(value, timeframe, type));
        }
    }
    const numericPrice = Number(currentPrice);
    const sorted = [...records.values()].sort((a, b) => a.level - b.level || a.objective_id.localeCompare(b.objective_id));
    const state = buildManualObjectiveSemanticState({
        above_current_price: sorted.filter(item => Number.isFinite(numericPrice) && item.level > numericPrice),
        below_current_price: sorted.filter(item => Number.isFinite(numericPrice) && item.level < numericPrice)
    }, currentPrice);
    return state;
}

function manualLocationModelFamily(type = '') {
    const normalized = String(type || '').toUpperCase();
    if (normalized.includes('CRT')) return 'CRT';
    if (normalized.includes('TBS')) return 'TBS';
    if (normalized.includes('MSNR')) return 'MSNR';
    if (normalized.includes('FVG') || normalized.includes('FAIR_VALUE_GAP')) return 'FVG';
    if (normalized.includes('OB') || normalized.includes('ORDER_BLOCK')) return 'OB';
    if (normalized.includes('SUPPLY')) return 'SUPPLY';
    if (normalized.includes('DEMAND')) return 'DEMAND';
    if (normalized.includes('FLIP') || normalized.includes('RECLAIM')) return 'FLIP';
    return 'ICT_STRUCTURE_AND_LIQUIDITY';
}

function buildManualInvalidationCatalogue(semantic = {}) {
    const records = new Map();
    for (const timeframe of AI_SEMANTIC_TIMEFRAMES) {
        for (const item of semantic.structural_invalidations?.[timeframe] || []) {
            const level = compactEvidenceNumber(item.level, item.invalidation?.level);
            const id = item.invalidation_id || item.id || item.evidence_id;
            if (!id || level == null || records.has(id)) continue;
            const sourceModel = canonicalModelToken(item.source_model || item.type || item.invalidation?.source);
            const invalidationBasis = item.invalidation_basis || item.invalidation?.basis || deriveInvalidationBasis(item, sourceModel);
            records.set(id, compactManualPacketValue({
                invalidation_id: String(id),
                timeframe: item.timeframe || timeframe,
                type: item.type || item.invalidation?.source || 'STRUCTURAL_INVALIDATION',
                model_semantics_id: item.model_semantics_id || getModelSemantics(sourceModel).model_semantics_id,
                level,
                event_time: item.event_time || null,
                source: item.source || item.invalidation?.source || null,
                // Do not manufacture provenance from the invalidation's own
                // identity.  A standalone invalidation may be valid evidence,
                // but it is not thereby linked to a location or event.
                source_evidence_id: item.evidence_id || null,
                source_location_id: item.source_location_id || item.location_id || null,
                source_model: sourceModel,
                source_timeframe: item.source_timeframe || item.timeframe || timeframe,
                source_event_id: item.source_event_id || item.event_id || null,
                source_price: item.source_price ?? item.level ?? level,
                invalidation_basis: invalidationBasis,
                confirmation_mode: item.confirmation_mode || item.invalidation_confirmation_mode || item.invalidation?.confirmation_mode || null,
                lifecycle_invalidation: item.lifecycle_invalidation || null,
                execution_invalidation: item.execution_invalidation || {
                    level,
                    basis: invalidationBasis,
                    confirmation_mode: item.confirmation_mode || item.invalidation_confirmation_mode || null
                },
                direction_if_deterministic: item.direction || null,
                state: item.state || null,
                invalidated: item.invalidated === true,
                consumed: item.consumed === true,
                evidence_ids: Array.isArray(item.evidence_ids) ? item.evidence_ids.filter(idValue => typeof idValue === 'string').slice(0, 16) : []
            }));
        }
    }
    return [...records.values()];
}

function buildManualLocationCatalogue(semantic = {}, invalidations = [], objectives = {}, currentPrice = null, referenceTime = null) {
    const locations = new Map();
    for (const timeframe of AI_SEMANTIC_TIMEFRAMES) {
        for (const item of semantic.timeframes?.[timeframe]?.locations || []) {
            if (!manualLocationStateIsStructurallyExecutable(item)) continue;
            if (!manualPacketIsRelevant(item, timeframe, referenceTime)) continue;
            const opportunityDelivery = evaluateManualPendingOpportunityDelivery(item, timeframe, objectives, currentPrice);
            if (opportunityDelivery.opportunity_lifecycle_state === 'STALE_FOR_NEW_ENTRY') continue;
            const id = manualPacketCanonicalId(item);
            if (!id || locations.has(id)) continue;
            const low = compactEvidenceNumber(item.low, item.zone?.low, item.zone_low);
            const high = compactEvidenceNumber(item.high, item.zone?.high, item.zone_high);
            const midpoint = compactEvidenceNumber(item.midpoint, item.price, item.level, item.zone?.midpoint);
            const evidenceIds = [...new Set([id, ...(item.evidence_ids || [])].filter(value => typeof value === 'string'))];
            const compatibleInvalidationIds = invalidations.filter(invalidation => {
                const lifecycle = String(invalidation.lifecycle_state || invalidation.state || '').toUpperCase();
                const usable = invalidation.invalidated !== true
                    && invalidation.consumed !== true
                    && !['INVALIDATED', 'CONSUMED', 'EXPIRED'].includes(lifecycle);
                const sameTimeframe = invalidation.timeframe === (item.timeframe || timeframe);
                const explicitLocationLink = invalidation.source_location_id === id
                    || invalidation.source_evidence_id === id
                    || invalidation.source_event_id === id;
                const evidenceLink = invalidation.evidence_ids?.some(value => evidenceIds.includes(value));
                // Same-timeframe linkage remains the default.  An explicitly
                // traceable source/evidence link is also sufficient across
                // timeframes; timeframe equality alone must never authorize a
                // stop, but it must not block a genuine HTF structural anchor.
                return usable && (sameTimeframe || explicitLocationLink || evidenceLink)
                    && (explicitLocationLink || evidenceLink);
            }).map(invalidation => invalidation.invalidation_id).filter(Boolean);
            const allObjectives = [...(objectives.above_current_price || []), ...(objectives.below_current_price || [])];
            const spatialObjectiveIds = allObjectives.filter(objective =>
                objective.timeframe === (item.timeframe || timeframe)
                && (objective.evidence_ids?.some(value => evidenceIds.includes(value))
                    || (low != null && high != null && objective.level >= low && objective.level <= high))
            ).map(objective => objective.objective_id);
            const relation = Number.isFinite(Number(currentPrice)) && low != null && high != null
                ? currentPrice < low ? 'BELOW_ZONE' : currentPrice > high ? 'ABOVE_ZONE' : 'INSIDE_ZONE'
                : null;
            const formedAt = manualPacketTimestampValue(item);
            const barsSinceFormation = Number.isFinite(Number(item.bars_since_formation))
                ? Number(item.bars_since_formation)
                : null;
            const locationRecord = compactManualPacketValue({
                 location_id: String(id),
                 type: item.type || item.event_type || null,
                 model_family: manualLocationModelFamily(item.type || item.event_type || item.model_family),
                 model_semantics_id: item.model_semantics_id || getModelSemantics(item.type || item.event_type || item.model_family).model_semantics_id,
                 permitted_entry_geometry: item.permitted_entry_geometry || getModelSemantics(item.type || item.event_type || item.model_family).permitted_entry_geometry,
                source_orientation: item.source_orientation || item.orientation || item.direction || item.source_direction
                    || (String(item.type || item.event_type || '').toUpperCase() === 'DEMAND' ? 'BUY' : String(item.type || item.event_type || '').toUpperCase() === 'SUPPLY' ? 'SELL' : null),
                role_reversal: item.role_reversal === true || item.reclaim_confirmed === true
                    || ['FLIP', 'RECLAIM', 'RECLAIM_RETEST'].includes(String(item.type || item.event_type || '').toUpperCase()),
                timeframe: item.timeframe || timeframe,
                zone_low: low,
                zone_high: high,
                midpoint_if_defined: midpoint,
                formed_at: manualPacketTimestampValue(item),
                freshness: item.freshness || null,
                mitigated: item.mitigation_state || item.mitigation || null,
                mitigation_state: item.mitigation_state || item.mitigation || null,
                lifecycle_state: item.lifecycle_state || item.state || null,
                opportunity_lifecycle_state: opportunityDelivery.opportunity_lifecycle_state,
                opportunity_relevance: opportunityDelivery.opportunity_relevance,
                delivery_fraction: opportunityDelivery.delivery_fraction,
                remaining_reward_fraction: opportunityDelivery.remaining_reward_fraction,
                remaining_objective_ids: opportunityDelivery.remaining_objective_ids,
                delivered_objective_ids: opportunityDelivery.delivered_objective_ids,
                consumed: item.consumed === true,
                invalidated: item.invalidated === true,
                 origin_evidence_ids: evidenceIds,
                 invalidation_basis: item.invalidation_basis || deriveInvalidationBasis(item, canonicalModelToken(item.type || item.event_type || item.model_family)),
                 touch_count: item.touch_count ?? item.touches ?? null,
                 last_touch_time: item.last_touch_time || item.retest_time || null,
                 close_beyond_count: item.close_beyond_count ?? null,
                 rejection_count: item.rejection_count ?? item.reaction_count ?? null,
                formation_context: compactManualPacketValue({
                    source: item.source || null,
                    event_time: manualPacketTimestampValue(item),
                    evidence_ids: evidenceIds
                }),
                delivery_since_formation: item.delivery_since_formation || item.delivery_since_formation_facts || null,
                current_relationship: compactManualPacketValue({
                    price_relation: relation,
                    current_price: currentPrice,
                    distance_to_near_edge: low != null && high != null && Number.isFinite(Number(currentPrice))
                        ? Math.min(Math.abs(Number(currentPrice) - low), Math.abs(Number(currentPrice) - high)) : null,
                    distance_to_far_edge: low != null && high != null && Number.isFinite(Number(currentPrice))
                        ? Math.max(Math.abs(Number(currentPrice) - low), Math.abs(Number(currentPrice) - high)) : null,
                    distance_to_midpoint: midpoint != null && Number.isFinite(Number(currentPrice)) ? Math.abs(Number(currentPrice) - midpoint) : null,
                    traded_through: item.traded_through ?? null,
                    newer_structure: item.newer_structure || null
                }),
                compatible_invalidation_ids: compatibleInvalidationIds,
                spatially_relevant_objective_ids: spatialObjectiveIds,
                zone: compactManualPacketValue({ low, high, midpoint }),
                formation: compactManualPacketValue({ formed_at: formedAt, bars_since_formation: barsSinceFormation, origin_evidence_ids: evidenceIds }),
                 structural_lifecycle: compactManualPacketValue({
                    freshness: item.freshness || null,
                    lifecycle_state: item.lifecycle_state || item.state || null,
                    mitigation_state: item.mitigation_state || item.mitigation || null,
                    consumed: item.consumed === true,
                     invalidated: item.invalidated === true
                 }),
                 lifecycle_invalidation: item.lifecycle_invalidation || null,
                 execution_invalidation: item.execution_invalidation || null,
                opportunity_delivery: compactManualPacketValue({
                    state: opportunityDelivery.opportunity_lifecycle_state,
                    relevance: opportunityDelivery.opportunity_relevance,
                    delivery_fraction: opportunityDelivery.delivery_fraction,
                    remaining_reward_fraction: opportunityDelivery.remaining_reward_fraction,
                    delivered_objective_ids: opportunityDelivery.delivered_objective_ids,
                    remaining_objective_ids: opportunityDelivery.remaining_objective_ids
                }),
                supporting_evidence_ids: evidenceIds,
                conflicting_evidence_ids: [],
                events_since_formation: [],
                containing_location_ids: [],
                overlapping_location_ids: []
            });
            if (locationRecord) {
                // Preserve an explicit empty compatibility set in V3.  It is
                // a meaningful fact: this location has no supplied stop link.
                locationRecord.compatible_invalidation_ids = compatibleInvalidationIds;
                locations.set(id, locationRecord);
            }
        }
    }
    const records = [...locations.values()];
    for (const record of records) {
        const low = record.zone_low; const high = record.zone_high;
        if (low == null || high == null) continue;
        record.containing_location_ids = records.filter(other => other.location_id !== record.location_id
            && other.zone_low != null && other.zone_high != null
            && other.zone_low <= low && other.zone_high >= high).map(other => other.location_id).sort();
        record.overlapping_location_ids = records.filter(other => other.location_id !== record.location_id
            && other.zone_low != null && other.zone_high != null
            && other.zone_low <= high && other.zone_high >= low).map(other => other.location_id).sort();
    }
    return records;
}

function buildManualModelEvidence(semantic = {}) {
    const groups = { ICT_STRUCTURE_AND_LIQUIDITY: [], OB: [], FVG: [], SUPPLY: [], DEMAND: [], FLIP: [], CRT: [], TBS: [], MSNR: [] };
    const records = [];
    const add = (item, fallbackType = null, timeframe = null) => {
        const compact = manualDecisionEvent(item, fallbackType, timeframe);
        if (!compact) return;
        const type = String(compact.event_type || '').toUpperCase();
        const family = manualLocationModelFamily(type);
        const key = `${family}:${compact.event_id}`;
        if (records.some(record => record._key === key)) return;
        records.push({ ...compact, _key: key });
    };
    for (const item of semantic.deterministic_evidence?.strategy_events || []) add(item, item.type || item.strategy, item.timeframe);
    for (const timeframe of AI_SEMANTIC_TIMEFRAMES) {
        const current = semantic.timeframes?.[timeframe] || {};
        for (const item of current.locations || []) add(item, item.type || 'LOCATION', timeframe);
        for (const item of current.evidence || []) add(item, item.type || 'STRUCTURE_EVENT', timeframe);
        for (const values of Object.values(current.liquidity || {})) {
            for (const item of Array.isArray(values) ? values : []) add(item, item.type || 'LIQUIDITY_EVENT', timeframe);
        }
        for (const key of ['mss', 'displacement']) if (current.structure?.[key]) add(current.structure[key], key.toUpperCase(), timeframe);
    }
    for (const record of records) {
        const { _key, ...publicRecord } = record;
        groups[manualLocationModelFamily(publicRecord.event_type)].push(publicRecord);
    }
    for (const key of Object.keys(groups)) groups[key] = groups[key].slice(0, 64);
    return groups;
}

function buildManualConflictMap(semantic = {}) {
    const conflicts = [];
    for (let leftIndex = 0; leftIndex < AI_SEMANTIC_TIMEFRAMES.length; leftIndex += 1) {
        for (let rightIndex = leftIndex + 1; rightIndex < AI_SEMANTIC_TIMEFRAMES.length; rightIndex += 1) {
            const leftTf = AI_SEMANTIC_TIMEFRAMES[leftIndex];
            const rightTf = AI_SEMANTIC_TIMEFRAMES[rightIndex];
            const left = String(semantic.timeframes?.[leftTf]?.structure?.effective_trend || '').toUpperCase();
            const right = String(semantic.timeframes?.[rightTf]?.structure?.effective_trend || '').toUpperCase();
            if (!left || !right || left === 'NEUTRAL' || right === 'NEUTRAL' || left === right) continue;
            conflicts.push({
                conflict_id: `CONFLICT:TREND:${leftTf}:${rightTf}`,
                type: 'EFFECTIVE_TREND_DISAGREEMENT',
                timeframes: [leftTf, rightTf],
                facts: { [leftTf]: left, [rightTf]: right },
                evidence_ids: [...new Set([
                    ...(semantic.timeframes?.[leftTf]?.structural_evidence_ids || []),
                    ...(semantic.timeframes?.[rightTf]?.structural_evidence_ids || [])
                ])].slice(0, 16),
                interpretation_required: true
            });
        }
    }
    // Keep opposing overlapping locations visible as a factual conflict. This
    // does not select a side or reject either location; it gives the external
    // AI the exact relationship it otherwise has to reconstruct manually.
    const locationRecords = AI_SEMANTIC_TIMEFRAMES.flatMap(timeframe =>
        (semantic.timeframes?.[timeframe]?.locations || []).map(item => ({ item, timeframe }))
    ).map(({ item, timeframe }) => ({
        id: manualPacketCanonicalId(item),
        timeframe,
        type: item.type || item.event_type || null,
        orientation: String(item.source_orientation || item.orientation || item.direction || item.source_direction || '').toUpperCase(),
        low: compactEvidenceNumber(item.low, item.zone?.low, item.zone_low),
        high: compactEvidenceNumber(item.high, item.zone?.high, item.zone_high),
        structural_lifecycle_state: item.lifecycle_state || item.state || item.freshness || null,
        opportunity_lifecycle_state: item.opportunity_lifecycle_state || item.opportunity_relevance || null,
        consumed: item.consumed === true,
        invalidated: item.invalidated === true,
        execution_eligible: manualLocationStateIsStructurallyExecutable(item)
    })).filter(item => item.id && item.low != null && item.high != null && item.high >= item.low);
    for (let leftIndex = 0; leftIndex < locationRecords.length; leftIndex += 1) {
        const left = locationRecords[leftIndex];
        for (let rightIndex = leftIndex + 1; rightIndex < locationRecords.length; rightIndex += 1) {
            const right = locationRecords[rightIndex];
            if (left.id === right.id || left.orientation === right.orientation
                || !['BUY', 'SELL'].includes(left.orientation) || !['BUY', 'SELL'].includes(right.orientation)
                || left.high < right.low || right.high < left.low) continue;
            const ids = [left.id, right.id].sort();
            conflicts.push({
                conflict_id: `CONFLICT:LOCATION:${ids[0]}:${ids[1]}`,
                type: 'OVERLAPPING_OPPOSING_LOCATIONS',
                timeframes: [...new Set([left.timeframe, right.timeframe])],
                facts: {
                    locations: [
                        { location_id: left.id, type: left.type, source_orientation: left.orientation, zone: { low: left.low, high: left.high }, structural_lifecycle_state: left.structural_lifecycle_state, opportunity_lifecycle_state: left.opportunity_lifecycle_state, consumed: left.consumed, invalidated: left.invalidated, execution_eligible: left.execution_eligible },
                        { location_id: right.id, type: right.type, source_orientation: right.orientation, zone: { low: right.low, high: right.high }, structural_lifecycle_state: right.structural_lifecycle_state, opportunity_lifecycle_state: right.opportunity_lifecycle_state, consumed: right.consumed, invalidated: right.invalidated, execution_eligible: right.execution_eligible }
                    ]
                },
                evidence_ids: ids,
                interpretation_required: true
            });
        }
    }
    for (const item of semantic.market_observations?.conflicts || []) {
        const compact = compactManualPacketValue({
            conflict_id: item.conflict_id || item.id || `CONFLICT:FACT:${conflicts.length + 1}`,
            type: item.type || 'DETERMINISTIC_CONTEXT_CONFLICT',
            timeframes: item.timeframes || item.timeframe || null,
            facts: item.facts || item.description || item,
            evidence_ids: Array.isArray(item.evidence_ids) ? item.evidence_ids.slice(0, 16) : [],
            interpretation_required: true
        });
        if (compact && !conflicts.some(existing => existing.conflict_id === compact.conflict_id)) conflicts.push(compact);
    }
    return conflicts.slice(0, 48);
}

function buildManualCurrentMarketSummary(semantic = {}, chronology = {}, modelEvidence = {}) {
    return Object.fromEntries(AI_SEMANTIC_TIMEFRAMES.map(timeframe => {
        const value = semantic.timeframes?.[timeframe] || {};
        const timeframeEvents = (chronology.events || [])
            .filter(event => event.timeframe === timeframe && event.event_type !== 'LOCATION_FORMED')
            .slice(-8);
        return [timeframe, compactManualPacketValue({
            timeframe,
            role: value.role || null,
            last_closed_time: value.last_closed_time || null,
            last_closed_price: value.current_closed_price ?? null,
            closed_candle_count: value.closed_candle_count ?? null,
            structure: compactManualStructureSummary(value, timeframeEvents),
            latest_meaningful_events: timeframeEvents,
            dealing_context: {
                dealing_range: value.dealing_range || null,
                premium_discount: value.premium_discount || null,
                previous_period: value.previous_period || null,
                previous_day_levels: value.previous_day_levels || null,
                atr: value.atr ?? null
            },
            model_evidence_ids: Object.values(modelEvidence).flat()
                .filter(item => item.timeframe === timeframe)
                .map(item => item.event_id)
                .filter(Boolean)
                .slice(0, 24)
        }) || { timeframe }];
    }));
}

function buildManualPacketCrossReferenceIndex(packet = {}) {
    const index = { locations: new Map(), objectives: new Map(), invalidations: new Map(), events: new Map(), evidence: new Map() };
    for (const item of packet.actionable_location_bundles || packet.current_actionable_location_catalogue || []) {
        if (item?.location_id) index.locations.set(item.location_id, item);
        for (const id of item?.origin_evidence_ids || []) index.evidence.set(id, item);
    }
    for (const item of packet.objective_state?.all || packet.current_liquidity_objective_map?.all || [
        ...(packet.current_liquidity_objective_map?.above_current_price || []),
        ...(packet.current_liquidity_objective_map?.below_current_price || [])
    ]) if (item?.objective_id) index.objectives.set(item.objective_id, item);
    for (const item of packet.structural_invalidations || packet.structural_invalidation_catalogue || []) if (item?.invalidation_id) index.invalidations.set(item.invalidation_id, item);
    for (const event of packet.market_delivery_chronology?.events || []) {
        if (event?.event_id) index.events.set(event.event_id, event);
        for (const id of event?.evidence_ids || []) index.evidence.set(id, event);
    }
    return index;
}

function validateManualExternalAIPacketIntegrity(packet = {}) {
    const issues = [];
    const timeframes = packet.multi_timeframe_state || packet.current_market_summary || {};
    if (JSON.stringify(Object.keys(timeframes)) !== JSON.stringify(AI_SEMANTIC_TIMEFRAMES)) issues.push('MISSING_CANONICAL_TIMEFRAMES');
    const locations = packet.actionable_location_bundles || packet.current_actionable_location_catalogue || [];
    const locationIds = new Set();
    for (const location of locations) {
        if (!location?.location_id) { issues.push('ACTIONABLE_LOCATION_ID_MISSING'); continue; }
        if (locationIds.has(location.location_id)) issues.push(`DUPLICATE_LOCATION_ID:${location.location_id}`);
        locationIds.add(location.location_id);
        if (location.consumed === true || location.invalidated === true) issues.push(`ACTIONABLE_LOCATION_STRUCTURALLY_UNUSABLE:${location.location_id}`);
        const lifecycle = String(location.lifecycle_state || location.structural_lifecycle?.lifecycle_state || '').toUpperCase();
        const freshness = String(location.freshness || location.structural_lifecycle?.freshness || '').toUpperCase();
        if (['CONSUMED', 'INVALIDATED'].includes(lifecycle) || ['CONSUMED', 'INVALIDATED'].includes(freshness)) issues.push(`ACTIONABLE_LOCATION_LIFECYCLE_CONTRADICTION:${location.location_id}`);
        const low = compactEvidenceNumber(location.zone_low, location.zone?.low);
        const high = compactEvidenceNumber(location.zone_high, location.zone?.high);
        if ((low == null) !== (high == null) || (low != null && high < low)) issues.push(`ACTIONABLE_LOCATION_RANGE_INVALID:${location.location_id}`);
        for (const id of location.compatible_invalidation_ids || []) if (!(packet.structural_invalidations || packet.structural_invalidation_catalogue || []).some(item => item.invalidation_id === id)) issues.push(`MISSING_LOCATION_INVALIDATION_REF:${location.location_id}:${id}`);
        for (const id of location.spatially_relevant_objective_ids || []) if (!(packet.objective_state?.all || packet.current_liquidity_objective_map?.all || [...(packet.current_liquidity_objective_map?.above_current_price || []), ...(packet.current_liquidity_objective_map?.below_current_price || [])]).some(item => item.objective_id === id)) issues.push(`MISSING_LOCATION_OBJECTIVE_REF:${location.location_id}:${id}`);
    }
    const objectives = packet.objective_state?.all || [
        ...(packet.current_liquidity_objective_map?.above_current_price || []),
        ...(packet.current_liquidity_objective_map?.below_current_price || [])
    ];
    const objectiveLevels = new Map();
    for (const objective of objectives) {
        if (!objective?.objective_id || !Number.isFinite(Number(objective.level))) issues.push('OBJECTIVE_LEVEL_INVALID');
        if (objectiveLevels.has(objective.objective_id) && objectiveLevels.get(objective.objective_id) !== Number(objective.level)) issues.push(`OBJECTIVE_ID_CONFLICT:${objective.objective_id}`);
        objectiveLevels.set(objective.objective_id, Number(objective.level));
        if (objective.relative_to_current_price && !['ABOVE', 'BELOW', 'AT_PRICE'].includes(objective.relative_to_current_price)) issues.push(`OBJECTIVE_RELATION_INVALID:${objective.objective_id}`);
    }
    const invalidationLevels = new Map();
    for (const invalidation of packet.structural_invalidations || packet.structural_invalidation_catalogue || []) {
        if (!invalidation?.invalidation_id || !Number.isFinite(Number(invalidation.level))) issues.push('INVALIDATION_LEVEL_INVALID');
        if (invalidationLevels.has(invalidation.invalidation_id) && invalidationLevels.get(invalidation.invalidation_id) !== Number(invalidation.level)) issues.push(`INVALIDATION_ID_CONFLICT:${invalidation.invalidation_id}`);
        invalidationLevels.set(invalidation.invalidation_id, Number(invalidation.level));
    }
    const raw = packet.raw_evidence_appendix?.recent_closed_price_action || packet.recent_price_action || {};
    for (const timeframe of AI_SEMANTIC_TIMEFRAMES) {
        const candles = raw[timeframe] || [];
        let previous = null;
        for (const candle of candles) {
            const values = [candle?.open, candle?.high, candle?.low, candle?.close].map(Number);
            const time = normalizeTimestampUTC(candle?.time);
            if (!Number.isFinite(time) || values.some(value => !Number.isFinite(value)) || values[1] < Math.max(values[0], values[3], values[2]) || values[2] > Math.min(values[0], values[3], values[1])) issues.push(`RAW_CANDLE_INVALID:${timeframe}`);
            if (previous != null && time <= previous) issues.push(`RAW_CANDLE_ORDER_INVALID:${timeframe}`);
            previous = time;
        }
    }
    const result = { valid: issues.length === 0, issues, checked_at: new Date().toISOString() };
    Object.defineProperty(result, 'index', { value: buildManualPacketCrossReferenceIndex(packet), enumerable: false });
    return result;
}

function manualLocationEventRelation(event = {}, location = {}) {
    const locationIds = new Set([
        location.location_id,
        ...(location.origin_evidence_ids || []),
        ...(location.supporting_evidence_ids || [])
    ].filter(Boolean));
    const eventIds = new Set([
        event.event_id,
        event.location_id,
        event.evidence_id,
        ...(event.evidence_ids || [])
    ].filter(Boolean));
    if (event.location_id && event.location_id === location.location_id) return 'CAUSAL';
    if ([...eventIds].some(id => locationIds.has(id))) return 'CAUSAL';
    const eventLow = compactEvidenceNumber(event.zone?.low, event.low, event.zone_low);
    const eventHigh = compactEvidenceNumber(event.zone?.high, event.high, event.zone_high);
    const locationLow = compactEvidenceNumber(location.zone_low);
    const locationHigh = compactEvidenceNumber(location.zone_high);
    if (eventLow != null && eventHigh != null && locationLow != null && locationHigh != null
        && eventLow <= locationHigh && eventHigh >= locationLow) return 'OVERLAPPING';
    const eventLevel = compactEvidenceNumber(event.level, event.price);
    if (eventLevel != null && locationLow != null && locationHigh != null
        && eventLevel >= locationLow && eventLevel <= locationHigh) return 'SPATIALLY_RELEVANT';
    return null;
}

function buildProfessionalManualMarketPacket({ semantic = {}, pair = null, provider = null, result = {}, source = {}, minimumRR = null } = {}) {
    const referenceTime = source.scan_as_of || result.time || semantic.snapshot?.as_of || null;
    const recentPriceAction = buildManualRecentPriceAction(semantic);
    const currentMarketContext = buildManualCurrentMarketContext(semantic, pair);
    const chronology = buildManualDeliveryChronology(semantic, referenceTime);
    const objectives = buildManualLiquidityObjectiveMap(semantic, semantic.snapshot?.current_price);
    const invalidations = buildManualInvalidationCatalogue(semantic);
    const locations = buildManualLocationCatalogue(semantic, invalidations, objectives, semantic.snapshot?.current_price, referenceTime);
    const modelEvidence = buildManualModelEvidence(semantic);
    const conflicts = buildManualConflictMap(semantic);
    const multiTimeframeState = buildManualTimeframeState(semantic, chronology, currentMarketContext);
    const objectiveState = objectives;
    const locationIds = new Set(locations.map(item => item.location_id));
    for (const location of locations) {
        const formedAt = normalizeTimestampUTC(location.formed_at);
        location.events_since_formation = (chronology.events || [])
            .filter(event => event && event.event_id && (!Number.isFinite(formedAt) || normalizeTimestampUTC(event.time) > formedAt))
            .map(event => ({ event, relation: manualLocationEventRelation(event, location) }))
            .filter(item => item.relation)
            .slice(-MANUAL_PACKET_MAX_EVENTS_PER_TIMEFRAME)
            .map(({ event, relation }) => compactManualPacketValue({
                 event_id: event.event_id,
                 event_type: event.event_type,
                 timeframe: event.timeframe,
                 direction: event.direction || null,
                 time: event.time,
                 location_id: event.location_id || null,
                 relation
             }));
        location.supporting_evidence_ids = [...new Set([
            ...(location.supporting_evidence_ids || []),
            ...(location.origin_evidence_ids || [])
        ])].filter(Boolean).slice(0, 24);
        const locationEvidenceIds = new Set([...(location.origin_evidence_ids || []), ...(location.supporting_evidence_ids || []), location.location_id].filter(Boolean));
        location.conflicting_evidence_ids = conflicts
            .filter(conflict => (conflict.timeframes || []).includes(location.timeframe)
                && (conflict.evidence_ids || []).some(id => locationEvidenceIds.has(id)))
            .flatMap(conflict => conflict.evidence_ids || [])
            .slice(0, 24);
        location.containing_location_ids = (location.containing_location_ids || []).filter(id => locationIds.has(id));
        location.overlapping_location_ids = (location.overlapping_location_ids || []).filter(id => locationIds.has(id));
    }
    const identity = {
        symbol: pair || semantic.snapshot?.pair || null,
        generated_at: source.scan_as_of || result.time || semantic.snapshot?.as_of || null,
        app_build_id: result.app_build_id || source.app_build_id || APP_BUILD_ID,
        serializer_id: result.clipboard_serializer_id || source.clipboard_serializer_id || CLIPBOARD_SERIALIZER_ID,
        scan_id: result.scan_id || source.scan_id || null,
        provider: provider || semantic.snapshot?.provider || null,
        strategy_version: result.strategy_version || STRATEGY_SPEC_VERSION || null,
        snapshot_id: semantic.snapshot?.snapshot_id || source.snapshot_id || result.snapshot_id || null,
        current_price: semantic.snapshot?.current_price ?? source.quote?.price ?? result.current_price ?? null,
        quote_time: source.quote?.quote_time || null
    };
    const packet = {
        packet_type: 'EXTERNAL_AI_MARKET_DECISION',
        schema_version: 3,
        external_ai_packet_schema: 'MARKET_STATE_V3',
        packet_identity: identity,
        professional_trader_mandate: [
            'Find today\'s highest-quality current trading opportunity on the supplied symbol, if one exists.',
            'Analyze BUY and SELL possibilities. Do not force a trade; NO_TRADE is a professional decision.',
            'Use only supplied deterministic prices, events, locations, invalidations, objectives, and evidence IDs.',
            'Understand current delivery and chronology before selecting a model or location. A historical valid location is not automatically a current opportunity.',
            'Use RECENT PRICE ACTION as an observation of the same closed-candle snapshot. Reconcile it with deterministic evidence, but do not invent structure, locations, invalidations, objectives, or executable prices from candles.'
        ],
        strategy_contract: {
            facts_owner: 'CODE',
            interpretation_owner: 'EXTERNAL_AI',
            semantic_timeframes: AI_SEMANTIC_TIMEFRAMES,
            minimum_rr: minimumRR,
            supported_setup_tokens: MANUAL_SETUP_TOKENS,
            market_phase_values: MANUAL_MARKET_PHASES,
            confidence_format: 'INTEGER_PERCENT_0_TO_100; NO_TRADE_NULL',
            rules: [
                'Use supplied deterministic facts only; never invent entry, stop, target, or market data.',
                'Reason in order: CURRENT MARKET STATE -> RECENT DELIVERY / CHRONOLOGY -> MULTI-TIMEFRAME CONTEXT -> LIQUIDITY MAP -> CURRENT PHASE -> DIRECTION -> LOCATION -> MODEL / EXECUTION -> INVALIDATION -> OBJECTIVE -> EXACT RR.',
                'A stop must be a supplied structural invalidation belonging to the thesis; an objective must be a genuine remaining neutral market fact.',
                'Consumed, invalidated, or unusable objectives cannot be used. minimum_rr is a preferred quality benchmark; it does not authorize target fabrication or invalidate a structurally coherent opportunity with a lower realistic RR. If every genuine supplied target is below minimum_rr but a finite structural objective exists, do not return NO_TRADE or claim that no target exists solely because of the RR shortfall: select the best structural target, report its actual RR, and state the below-benchmark warning.',
                'PENDING_LIMIT may be away from current price and does not require 5M/15M confirmation unless supplied setup semantics require it. CONFIRMATION_ENTRY requires supplied confirmation.',
                'Freshness is not opportunity relevance, distance alone is not rejection, and confidence never makes invalid geometry valid.',
                'Combined setup labels require same-opportunity components with compatible chronology, location, direction, and evidence.',
                'setup is one supported model/type or a same-opportunity + combination; it is not a prose description of supporting evidence.',
                'market_phase is one supplied phase enum, not a thesis paragraph. confidence is an integer percentage after validity; NO_TRADE confidence is null.',
                'Every returned ID and numeric value must refer to the same supplied deterministic fact. The code recalculates RR from final entry, stop_loss, and TP1.',
                'Recent price action contains only closed OHLC candles from this canonical snapshot. It is for interpreting delivery, rejection, compression, expansion, pullback quality, and transition; deterministic catalogues remain authoritative for executable geometry.'
            ]
        },
        current_market_state: compactManualPacketValue({
            symbol: identity.symbol,
            snapshot_time: currentMarketContext.snapshot_time,
            quote_time: identity.quote_time,
            current_price: currentMarketContext.current_price,
            asset_class: currentMarketContext.asset_class,
            session: currentMarketContext.session_context,
            volatility: currentMarketContext.volatility_context,
            provider: identity.provider,
            latest_closed_time_by_timeframe: Object.fromEntries(AI_SEMANTIC_TIMEFRAMES.map(tf => [tf, semantic.timeframes?.[tf]?.last_closed_time || null]))
        }),
        snapshot_delta: buildManualSnapshotDelta({
            packet_identity: identity,
            multi_timeframe_state: multiTimeframeState,
            current_actionable_location_catalogue: locations,
            current_liquidity_objective_map: objectives,
            market_delivery_chronology: chronology,
            raw_evidence_appendix: { recent_closed_price_action: recentPriceAction.timeframes }
        }, source.previous_manual_packet || source.previous_scan_replay?.manual_packet || null),
        multi_timeframe_state: multiTimeframeState,
        liquidity_state: Object.fromEntries(AI_SEMANTIC_TIMEFRAMES.map(tf => [tf, {
            timeframe: tf,
            above_current_price: (objectives.above_current_price || []).filter(item => item.timeframe === tf),
            below_current_price: (objectives.below_current_price || []).filter(item => item.timeframe === tf),
            recent_events: (chronology.events || []).filter(event => event.timeframe === tf && /LIQUIDITY|SWEEP|RAID/.test(String(event.event_type || '').toUpperCase())).slice(-12)
        }])),
        actionable_location_bundles: locations,
        objective_state: objectiveState,
        structural_invalidations: invalidations,
        model_evidence: Object.fromEntries(Object.keys(modelEvidence).map(key => [key, modelEvidence[key] || []])),
        conflict_state: conflicts,
        raw_evidence_appendix: {
            recent_closed_price_action: recentPriceAction.timeframes,
            institutional_activity: semantic.institutional_activity_evidence || null
        },
        current_market_context: currentMarketContext,
        recent_price_action: recentPriceAction.timeframes,
        current_market_summary: buildManualCurrentMarketSummary(semantic, chronology, modelEvidence),
        market_delivery_chronology: chronology,
        current_liquidity_objective_map: objectives,
        current_actionable_location_catalogue: locations,
        structural_invalidation_catalogue: invalidations,
        model_setup_evidence: modelEvidence,
        multi_timeframe_conflict_map: conflicts,
        institutional_activity_evidence: semantic.institutional_activity_evidence || null,
        provenance: {
            packet_schema: 'MARKET_STATE_V3',
            raw_candles_included: recentPriceAction.complete,
            raw_candle_policy: {
                closed_only: true,
                candles_per_timeframe: MANUAL_RECENT_CANDLES_PER_TIMEFRAME,
                timeframes: AI_SEMANTIC_TIMEFRAMES
            },
            direction_preselected: false,
            candidate_ranking_included: false,
            all_executable_prices_deterministic: true,
            evidence_ids_traceable: true,
            semantic_consistency_passed: null,
            provider: identity.provider,
            snapshot_id: identity.snapshot_id,
            scan_id: identity.scan_id,
            app_build_id: identity.app_build_id
        }
    };
    const integrity = validateManualExternalAIPacketIntegrity(packet);
    packet.provenance.semantic_consistency_passed = integrity.valid;
    packet.packet_integrity_result = integrity;
    packet.packet_diagnostics = {
        approx_character_count: JSON.stringify(packet).length,
        section_counts: {
            locations: locations.length,
            objectives: objectiveState.all?.length || 0,
            events: chronology.events?.length || 0,
            raw_candles: Object.values(recentPriceAction.timeframes).reduce((sum, candles) => sum + candles.length, 0)
        },
        location_count: locations.length,
        objective_count: objectiveState.all?.length || 0,
        event_count: chronology.events?.length || 0,
        raw_candle_count: Object.values(recentPriceAction.timeframes).reduce((sum, candles) => sum + candles.length, 0)
    };
    return packet;
}

